/* The other half of that drift. The harness globs the domain directory, so a new
   file is always loaded HERE — which means a file missing from bootstrap.php's
   explicit list would pass every test and 404 in production, the worst possible
   split. Assert the list covers the directory. */
chk('bootstrap loads every domain file, so a new one cannot pass tests and 404 live', (function () use ($ROOT) {
    $src = (string)@file_get_contents($ROOT . '/_lib/bootstrap.php');
    $missing = [];
    foreach (glob($ROOT . '/_lib/domain/*.php') ?: [] as $f) {
        $name = basename($f, '.php');
        if (strpos($src, "'" . $name . "'") === false) $missing[] = $name;
    }
    if ($missing) fwrite(STDERR, "       bootstrap.php is missing: " . implode(', ', $missing) . "\n");
    return $missing === [];
})());

/** Just the `$map = [ ... ];` literal from backend.php.
 *  Scoped deliberately: the file also RETURNS arrays like
 *  ['ok' => false, 'error' => 'unknown_op'], which match the same shape and
 *  would otherwise be read as routes to a handler called unknown_op(). */
function backend_map_src(string $root): string {
    $src = (string)@file_get_contents($root . '/_lib/backend.php');
    $start = strpos($src, '$map = [');
    if ($start === false) return '';
    $end = strpos($src, "\n        ];", $start);
    return $end === false ? '' : substr($src, $start, $end - $start);
}

/* ── Every route in the dispatcher actually goes somewhere ────────────────
 *
 * backend_dispatch() is a map of ~400 op strings to handler names, and nothing
 * checked that the right-hand side exists. A renamed or deleted handler, or a
 * typo in either column, passes review, passes every test that does not happen
 * to call that one op, and then throws in production — where the dispatcher's
 * catch turns it into a flat `internal` with the real cause only in the error
 * log. That is the failure a centre reports by telephone.
 *
 * All of them resolve today. This is the guard, not a fix: it costs one
 * reflection call per op and it makes the class of mistake impossible to ship.
 */
chk('every dispatcher op resolves to a function that exists', (function () use ($ROOT) {
    $src = backend_map_src($ROOT);
    preg_match_all("/'([a-zA-Z0-9._]+)'\s*=>\s*'([a-z0-9_]+)'/", $src, $m, PREG_SET_ORDER);
    $broken = [];
    foreach ($m as [, $op, $fn]) {
        if (!function_exists($fn)) $broken[] = $op . ' -> ' . $fn . '()';
    }
    if ($broken) fwrite(STDERR, "       unresolvable: " . implode(', ', $broken) . "\n");
    // Guard the guard: if the regex stops matching, this must fail loudly
    // rather than passing over an empty list.
    return count($m) > 300 && $broken === [];
})());
/* Two ops may share a handler (a legacy alias), but one op must not appear
   twice — the second silently wins and the first is dead code that reads as
   live wiring. */
chk('…and no op is declared twice', (function () use ($ROOT) {
    $src = backend_map_src($ROOT);
    preg_match_all("/'([a-zA-Z0-9._]+)'\s*=>\s*'[a-z0-9_]+'/", $src, $m);
    $dupes = array_keys(array_filter(array_count_values($m[1]), fn($n) => $n > 1));
    if ($dupes) fwrite(STDERR, "       duplicated ops: " . implode(', ', $dupes) . "\n");
    return $dupes === [];
})());


/* ── The organisation, not only the summer programme ─────────────────────────
 *
 * Everything built so far served the summer cohort, and NGG exists the other
 * eleven months of the year: a launch to announce, a centre opening, a donor
 * report, certificates to award. A designer that can only make ID cards says the
 * organisation is only a summer programme.
 */
/* ── The media cloud, and the silence around it ──────────────────────────────
 *
 * Reported as "Cloudinary seems disconnected, the uploads do not save to
 * Cloudinary anymore". The uploads were not failing — the client falls back to
 * storing the image locally whenever the cloud cannot be used, which is right,
 * and nothing anywhere reported that it had happened. A cloud with rotated keys
 * behaved exactly like a healthy one from every screen in the product.
 */
chk('a host with no Cloudinary keys is healthy, not broken', (function () {
    $keep = $GLOBALS['CONFIG']['cloudinary'] ?? null;
    $GLOBALS['CONFIG']['cloudinary'] = [];
    $h = ops_cloudinary_health();
    $GLOBALS['CONFIG']['cloudinary'] = $keep;
    // Running without a cloud is a supported deployment. Flagging it would teach
    // people to ignore the panel, which costs you the warning that matters.
    return $h['ok'] === true && $h['configured'] === false && $h['state'] === 'not_configured';
})());
chk('…and keys Cloudinary refuses are reported as refused, not as silence', (function () {
    $keep = $GLOBALS['CONFIG']['cloudinary'] ?? null;
    $GLOBALS['CONFIG']['cloudinary'] = ['cloud_name' => 'ngg', 'api_key' => 'k', 'api_secret' => 's'];
    cache_put('ops.cloudinary', null);
    @unlink(cache_path('ops.cloudinary'));
    $GLOBALS['__cloudinary_ping_mock'] = fn() => ['code' => 401, 'body' => '', 'error' => ''];
    $h = ops_cloudinary_health();
    unset($GLOBALS['__cloudinary_ping_mock']);
    @unlink(cache_path('ops.cloudinary'));
    $GLOBALS['CONFIG']['cloudinary'] = $keep;
    return $h['ok'] === false && $h['state'] === 'bad_credentials'
        && strpos($h['detail'], 'falling back') !== false;   // says what it MEANS, not just what happened
})());
chk('…an exhausted plan and an unreachable host are told apart', (function () {
    $keep = $GLOBALS['CONFIG']['cloudinary'] ?? null;
    $GLOBALS['CONFIG']['cloudinary'] = ['cloud_name' => 'ngg', 'api_key' => 'k', 'api_secret' => 's'];
    $states = [];
    foreach ([[420, '', ''], [0, '', 'could not connect']] as $r) {
        @unlink(cache_path('ops.cloudinary'));
        $GLOBALS['__cloudinary_ping_mock'] = fn() => ['code' => $r[0], 'body' => $r[1], 'error' => $r[2]];
        $states[] = ops_cloudinary_health()['state'];
    }
    unset($GLOBALS['__cloudinary_ping_mock']);
    @unlink(cache_path('ops.cloudinary'));
    $GLOBALS['CONFIG']['cloudinary'] = $keep;
    /* Four states because they have four different fixes: rotate a key, wait for
       a plan to reset, open a firewall, or nothing at all. */
    return $states === ['exhausted', 'unreachable'];
})());
chk('…and a working cloud reports how much of the plan is left', (function () {
    $keep = $GLOBALS['CONFIG']['cloudinary'] ?? null;
    $GLOBALS['CONFIG']['cloudinary'] = ['cloud_name' => 'ngg', 'api_key' => 'k', 'api_secret' => 's'];
    @unlink(cache_path('ops.cloudinary'));
    $GLOBALS['__cloudinary_ping_mock'] = fn() => ['code' => 200,
        'body' => json_encode(['credits' => ['used_percent' => 62.4]]), 'error' => ''];
    $h = ops_cloudinary_health();
    unset($GLOBALS['__cloudinary_ping_mock']);
    @unlink(cache_path('ops.cloudinary'));
    $GLOBALS['CONFIG']['cloudinary'] = $keep;
    // Visible BEFORE the ceiling is hit, rather than after uploads start failing.
    return $h['ok'] === true && $h['state'] === 'ok' && abs(($h['usedPercent'] ?? 0) - 62.4) < 0.01
        && strpos($h['detail'], '62%') !== false;
})());
chk('the health check is cached, so the diagnostics page is not an outbound call per load', (function () {
    $keep = $GLOBALS['CONFIG']['cloudinary'] ?? null;
    $GLOBALS['CONFIG']['cloudinary'] = ['cloud_name' => 'ngg', 'api_key' => 'k', 'api_secret' => 's'];
    @unlink(cache_path('ops.cloudinary'));
    $calls = 0;
    $GLOBALS['__cloudinary_ping_mock'] = function () use (&$calls) { $calls++; return ['code' => 200, 'body' => '{}', 'error' => '']; };
    ops_cloudinary_health(); ops_cloudinary_health(); ops_cloudinary_health();
    unset($GLOBALS['__cloudinary_ping_mock']);
    @unlink(cache_path('ops.cloudinary'));
    $GLOBALS['CONFIG']['cloudinary'] = $keep;
    return $calls === 1;
})());
chk('a silent fallback to local storage becomes a recorded warning', (function () {
    /* The whole point. The upload already succeeded from the family's side; what
       was missing was anybody knowing it had not reached the cloud. */
    db_exec("DELETE FROM ops_events WHERE source = 'cloudinary.upload'");
    $keep = $GLOBALS['CONFIG']['cloudinary'] ?? null;
    $GLOBALS['CONFIG']['cloudinary'] = ['cloud_name' => 'ngg', 'api_key' => 'k', 'api_secret' => 's'];
    ops_record('warn', 'cloudinary.upload', 'Upload fell back to local storage', 'kind=headshot · signed: upload_failed_401');
    ops_record('warn', 'cloudinary.upload', 'Upload fell back to local storage', 'kind=headshot · signed: upload_failed_401');
    $GLOBALS['CONFIG']['cloudinary'] = $keep;
    $row = db_row("SELECT hits, detail FROM ops_events WHERE source = 'cloudinary.upload' LIMIT 1");
    // Collapsed into a hit count: a broken deployment must not fill the table
    // one family at a time, and "how many" is the useful number anyway.
    return $row && (int)$row['hits'] === 2 && strpos((string)$row['detail'], '401') !== false;
})());

/* ── The asset library ───────────────────────────────────────────────────────
 *
 * The bug it exists to fix, first, so the fix is anchored to the failure: a
 * placed image was a data: URL inside the design, and a design is capped at
 * 512KB. One 1600px photograph is around 400KB of JPEG — 548KB base64 — so a
 * poster with a photo on it could not be saved AT ALL.
 */
$DASSET_PNG = (function () {
    // A real PNG, big enough that base64-ing it into a design is the problem.
    $im = @imagecreatetruecolor(400, 300);
    if (!$im) return '';
    for ($x = 0; $x < 400; $x += 2) for ($y = 0; $y < 300; $y += 2) {
        imagesetpixel($im, $x, $y, imagecolorallocate($im, ($x * 7) % 255, ($y * 11) % 255, ($x + $y) % 255));
    }
    ob_start(); imagepng($im); $raw = (string)ob_get_clean(); imagedestroy($im);
    return 'data:image/png;base64,' . base64_encode($raw);
})();
chk('a design carrying a whole photograph inline is refused — the bug the library fixes', (function () {
    // Half a megabyte of base64 in one element, which is one ordinary photo.
    $fat = 'data:image/png;base64,' . str_repeat('A', 520 * 1024);
    $r = backend_dispatch('admin.card.template.save', ['requesterId' => 'NGG-2025-0099', 'template' => [
        'name' => 'Poster with a photo', 'kind' => 'graphic', 'w' => 877, 'h' => 1240, 'wMm' => 210, 'hMm' => 297,
        'elements' => [['id' => 'bg', 'type' => 'image', 'x' => 0, 'y' => 0, 'w' => 877, 'h' => 1240, 'src' => $fat]],
    ]]);
    return ($r['error'] ?? '') === 'too_large';
})());
chk('…so an image goes to the library and the design holds only a URL', (function () use ($DASSET_PNG) {
    if ($DASSET_PNG === '') return true;                       // no GD on this host
    $up = backend_dispatch('admin.design.asset.upload', ['requesterId' => 'NGG-2025-0099',
        'name' => 'Launch backdrop', 'folder' => 'photo', 'dataUrl' => $DASSET_PNG]);
    if (empty($up['ok'])) return false;
    $GLOBALS['__assetId'] = $up['asset']['assetId'];
    $GLOBALS['__assetUrl'] = $up['asset']['url'];
    $save = backend_dispatch('admin.card.template.save', ['requesterId' => 'NGG-2025-0099', 'template' => [
        'name' => 'Poster that saves', 'kind' => 'graphic', 'w' => 877, 'h' => 1240, 'wMm' => 210, 'hMm' => 297,
        'elements' => [['id' => 'bg', 'type' => 'image', 'x' => 0, 'y' => 0, 'w' => 877, 'h' => 1240,
                        'src' => $up['asset']['url']]],
    ]]);
    // Dimensions read from the bytes, not trusted from the client.
    return !empty($save['ok']) && $up['asset']['width'] === 400 && $up['asset']['height'] === 300
        && $up['asset']['local'] === true && $up['asset']['bytes'] > 100;
})());
chk('the same file uploaded twice is one file, not two', (function () use ($DASSET_PNG) {
    if ($DASSET_PNG === '') return true;
    $before = (int)(db_row("SELECT COUNT(*) n FROM design_assets WHERE archivedAt = ''")['n'] ?? 0);
    $again = backend_dispatch('admin.design.asset.upload', ['requesterId' => 'NGG-2025-0099',
        'name' => 'A different name', 'dataUrl' => $DASSET_PNG]);
    $after = (int)(db_row("SELECT COUNT(*) n FROM design_assets WHERE archivedAt = ''")['n'] ?? 0);
    /* The point of a library rather than a folder: the same logo dropped into
       eleven posters is one file. Content-addressed, so the name does not
       matter — the bytes do. */
    return !empty($again['deduped']) && $after === $before
        && $again['asset']['assetId'] === ($GLOBALS['__assetId'] ?? '');
