    foreach ($r['editions'] as $e) if ($e['editionId'] === 'SUM-2031') return $e['participants'] === 3 && $e['ungrouped'] === 1;
    return false;
})());
chk('groups: deleting one with children in it is refused', (function () use ($GA) {
