        'centreScope' => json_encode([$ctr['centreId']]), 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    db_insert('members', ['memberId' => 'NGG-INSCOPE', 'fullName' => 'In Scope', 'email' => 'inscope@example.com',
