        $r = backend_dispatch('journal.save', ['requesterId' => 'NGG-2025-0099', 'title' => 'Album', 'media' => $many]);
        $n = count($r['entry']['media'] ?? []);
        db_exec('DELETE FROM program_journal WHERE entryId = ?', [$r['entry']['entryId']]);
        return $n === 12;
    })());

