    })());
    chk('journal: a tagged person can find what they were part of', (function () use ($EID) {
        $r = backend_dispatch('journal.person', ['requesterId' => 'NGG-2025-0099', 'signedIn' => true, 'personId' => 'NGG-2025-0001']);
        return in_array($EID, array_column($r['entries'] ?? [], 'entryId'), true);
    })());
    chk('journal: filters narrow the feed', (function () {
        $r = backend_dispatch('journal.feed', ['requesterId' => 'NGG-2025-0099', 'signedIn' => true, 'kind' => 'issue']);
        foreach (($r['entries'] ?? []) as $e) if ($e['kind'] !== 'issue') return false;
        return count($r['entries']) >= 1;
    })());
    chk('journal: delete removes the entry and its tags', (function () use ($EID) {
        backend_dispatch('journal.delete', ['requesterId' => 'NGG-2025-0099', 'entryId' => $EID]);
        return db_row('SELECT id FROM program_journal WHERE entryId = ?', [$EID]) === null
            && db_row('SELECT id FROM program_journal_tags WHERE entryId = ?', [$EID]) === null;
    })());


    /* ── §8c · The Programme record ────────────────────────────────────────
     * The three tiles at the top of §8c are counts, so what matters is that
     * they count exactly the rows the reader can open, that the derived
     * numbers stay derived, and that "a mentor reviews it before it appears
     * here" is enforced where the sentence is printed rather than by a client
     * filtering a list it was handed.
     * ──────────────────────────────────────────────────────────────────── */
    db_exec("DELETE FROM program_journal_tags");
    db_exec("DELETE FROM program_journal");
    db_exec("DELETE FROM program_journal_updates");
    db_exec("DELETE FROM program_journal_follows");

    $mk = function (array $f) {
        $r = backend_dispatch('journal.save', array_merge(['requesterId' => 'NGG-2025-0099'], $f));
        return (string)($r['entry']['entryId'] ?? '');
    };
    $thisYear = (int)gmdate('Y');
    $ISSUE = $mk(['title' => 'Ayobo hall double-booked on Thursdays', 'kind' => 'issue', 'status' => 'open',
                  'body' => 'The centre manager has us and the choir in the same room from 4pm.',
                  'ownerName' => 'Mr Adewale',
                  'occurredAt' => gmdate('Y-m-d\TH:i:s\Z', time() - 6 * 86400)]);
    $DEC = $mk(['title' => 'Thursday sessions move to 5pm', 'kind' => 'decision', 'status' => 'resolved',
                'parentEntryId' => $ISSUE, 'agreedWith' => 2, 'notified' => 18]);
    $CON = $mk(['title' => 'Egbeda parents funded twenty ID cards', 'kind' => 'contribution',
                'amountMinor' => 1200000, 'contributors' => 9, 'currency' => 'NGN',
                'media' => [['url' => 'https://ex.co/r1.jpg', 'type' => 'image', 'alt' => 'Receipt one'],
                            ['url' => 'https://ex.co/r2.jpg', 'type' => 'image', 'alt' => 'Receipt two']]]);
    $ADV = $mk(['title' => 'Tell someone the week you start slipping', 'kind' => 'advice']);
    $MIL = $mk(['title' => 'First cohort graduation', 'kind' => 'milestone',
                'countValue' => 41, 'countTotal' => 46, 'countUnit' => 'finished twelve weeks',
                'occurredAt' => gmdate('Y-m-d\TH:i:s\Z', strtotime('-1 year'))]);

    /* Following, and reading it as a member, both need the entry to be one a
       member may read. Widened deliberately and through the audited call, the
       way a mentor would. */
    backend_dispatch('journal.visibility', ['requesterId' => 'NGG-2025-0099', 'entryId' => $ISSUE, 'visibility' => 'community']);

    $shape = function (string $id, string $who = 'NGG-2025-0099') {
        $f = backend_dispatch('journal.feed', ['requesterId' => $who, 'signedIn' => true, 'per' => 50]);
        foreach ($f['entries'] as $e) if ($e['entryId'] === $id) return $e;
        return null;
    };

    // ── The tiles ──
    $sum = backend_dispatch('journal.feed', ['requesterId' => 'NGG-2025-0099', 'signedIn' => true])['summary'];
    chk('§8c: the Open issues tile counts the issues that are open', $sum['openIssues'] === 1);
    chk('§8c: …and "Needs attention" is the SAME number as the tile above it',
        $sum['needsAttention'] === $sum['openIssues']);
    chk('§8c: the Raised tile sums this year\'s contributions', $sum['raisedMinor'] === 1200000);
    chk('§8c: …and prints it the way the artboard does — ₦12k, not 1200000',
        $sum['raised'] === '₦12k' && $sum['raisedYear'] === $thisYear);
    /* The open issue is six days old, which is LAST month for the first six
       days of every month — so what "this month" holds depends on the date. */
    $issueThisMonth = gmdate('Y-m', time() - 6 * 86400) === gmdate('Y-m') ? 1 : 0;
    chk('§8c: "This month" counts this month, and last year\'s milestone is not in it',
        $sum['thisMonth'] === 3 + $issueThisMonth);
    chk('§8c: Everything counts everything readable', $sum['everything'] === 5);

    // ── The cards ──
    $iss = $shape($ISSUE);
    chk('§8c: an open issue says how long it has been open, in words',
        ($iss['openFor'] ?? '') === '6 days');
    chk('§8c: …and carries who owns it, not only who raised it',
        ($iss['ownerName'] ?? '') === 'Mr Adewale');
    chk('§8c: …with no updates yet, and nothing pretending to be the latest one',
        ($iss['updates'] ?? -1) === 0
        && array_key_exists('latestUpdate', $iss) && $iss['latestUpdate'] === null);

    $con = $shape($CON);
    chk('§8c: a contribution prints the amount as money', ($con['amount'] ?? '') === '₦12,000');
    chk('§8c: …and how many families it came from', ($con['contributors'] ?? 0) === 9);
    /* The design draws a full bar on a contribution with no stated goal. A bar
       that read 0% because nobody set a target would say the opposite. */
    chk('§8c: …and a contribution with no target reads as met, not as 0%',
        ($con['progress'] ?? -1) === 100);
    chk('§8c: …while one with a target reads as the fraction it actually is', (function () use ($mk, $shape) {
        $id = $mk(['title' => 'Half way', 'kind' => 'contribution', 'amountMinor' => 500000, 'targetMinor' => 2000000]);
        $e = $shape($id);
        db_exec('DELETE FROM program_journal WHERE entryId = ?', [$id]);
        return ($e['progress'] ?? -1) === 25;
    })());
    /* "receipts attached (2)" is the media already on the entry. A stored
       tally beside the list it counts is two records of one fact. */
    chk('§8c: …and the receipts are counted from the attachments themselves',
        ($con['attachments'] ?? 0) === 2);

    $dec = $shape($DEC);
    chk('§8c: a decision carries the entry it follows from', ($dec['parentEntryId'] ?? '') === $ISSUE);
    chk('§8c: …and its provenance, which cannot be reconstructed later',
        ($dec['agreedWith'] ?? 0) === 2 && ($dec['notified'] ?? 0) === 18);
    chk('§8c: an entry cannot follow itself',
        backend_dispatch('journal.save', ['requesterId' => 'NGG-2025-0099', 'entryId' => $DEC,
            'title' => 'Loop', 'parentEntryId' => $DEC])['error'] === 'bad_parent');

    $mil = $shape($MIL);
    chk('§8c: a milestone carries its headline number and what it is out of',
        ($mil['countValue'] ?? 0) === 41 && ($mil['countTotal'] ?? 0) === 46
        && ($mil['countUnit'] ?? '') === 'finished twelve weeks');

    // ── Updates ──
    chk('§8c: an update needs something in it',
        backend_dispatch('journal.update.add', ['requesterId' => 'NGG-2025-0099', 'entryId' => $ISSUE, 'body' => '  '])['error'] === 'body_required');
    chk('§8c: a member without the capability cannot write the record',
        backend_dispatch('journal.update.add', ['requesterId' => 'NGG-2025-0001', 'entryId' => $ISSUE, 'body' => 'x'])['error'] === 'forbidden');
    backend_dispatch('journal.update.add', ['requesterId' => 'NGG-2025-0099', 'entryId' => $ISSUE,
        'body' => 'Mr Adewale met the manager.']);
    backend_dispatch('journal.update.add', ['requesterId' => 'NGG-2025-0099', 'entryId' => $ISSUE,
        'body' => 'Waiting on a written slot confirmation before we tell parents.']);
    $iss = $shape($ISSUE);
    chk('§8c: the card counts the updates', ($iss['updates'] ?? 0) === 2);
    chk('§8c: …and the LATEST one is the one it shows, not the first',
        strpos((string)($iss['latestUpdate']['body'] ?? ''), 'Waiting on a written') === 0);

    // ── Following ──
    chk('§8c: a member follows an issue',
        !empty(backend_dispatch('journal.follow', ['memberId' => 'NGG-2025-0001', 'entryId' => $ISSUE])['following']));
    chk('§8c: …and the count is a row count, so it agrees with the list',
        ($shape($ISSUE)['followers'] ?? 0) === 1);
    chk('§8c: …and the follower is told they are following, nobody else is',
        !empty($shape($ISSUE, 'NGG-2025-0001')['following'])
        && empty($shape($ISSUE, 'NGG-2025-0002')['following']));
    /* An update nobody hears about makes the button a lie. */
    chk('§8c: …and an update actually reaches them',
        (function () use ($ISSUE) {
            db_exec("DELETE FROM notifications WHERE memberId = 'NGG-2025-0001' AND kind = 'journal.update'");
            backend_dispatch('journal.update.add', ['requesterId' => 'NGG-2025-0099', 'entryId' => $ISSUE, 'body' => 'Slot confirmed.']);
            return (int)(db_row("SELECT COUNT(*) c FROM notifications WHERE memberId = 'NGG-2025-0001' AND kind = 'journal.update'")['c'] ?? 0) === 1;
        })());
    chk('§8c: unfollowing is possible, which is the only thing that makes following safe',
        empty(backend_dispatch('journal.follow', ['memberId' => 'NGG-2025-0001', 'entryId' => $ISSUE])['following'])
        && ($shape($ISSUE)['followers'] ?? -1) === 0);
    chk('§8c: you cannot follow an entry you cannot read — that would tell you it exists',
        backend_dispatch('journal.follow', ['memberId' => 'NGG-2025-0001', 'entryId' => 'PJ-NOPE'])['error'] === 'not_found');

    // ── Propose, and the promise on the card ──
    $prop = backend_dispatch('journal.propose', ['memberId' => 'NGG-2025-0001',
        'title' => 'The gate light has been out for a fortnight', 'kind' => 'issue']);
    chk('§8c: anybody signed in may propose an entry', !empty($prop['ok']));
    chk('§8c: …and is told what happens next, not just "saved"',
        strpos((string)($prop['message'] ?? ''), 'mentors') !== false);
    $PID = (string)$prop['entryId'];
    chk('§8c: a proposal is staff-only, whatever it asked for',
        (string)db_row('SELECT visibility FROM program_journal WHERE entryId = ?', [$PID])['visibility'] === 'staff');
    /* This is the promise §8c prints on the card that makes it, so it is kept
       on the server rather than by a client filtering its own list. */
    chk('§8c: …and it does NOT appear on the record until a mentor publishes it',
        $shape($PID, 'NGG-2025-0001') === null);
    chk('§8c: …though a mentor sees it, marked as a proposal and by whom',
        ($shape($PID)['proposed'] ?? false) === true
        && ($shape($PID)['proposedName'] ?? '') !== '');
    /* A member reads exactly the one entry that was widened for them. The
       proposal must not push that number up — a tile that counts entries the
       reader cannot open sends them looking for something that is not there. */
    chk('§8c: …and it is not counted in the tiles a member reads',
        backend_dispatch('journal.feed', ['requesterId' => 'NGG-2025-0001', 'signedIn' => true])['summary']['everything'] === 1);
    chk('§8c: publishing is a mentor\'s act, not the proposer\'s',
        backend_dispatch('journal.publish', ['requesterId' => 'NGG-2025-0001', 'entryId' => $PID])['error'] === 'forbidden');
    chk('§8c: a mentor publishes it', !empty(backend_dispatch('journal.publish', ['requesterId' => 'NGG-2025-0099', 'entryId' => $PID])['ok']));
    chk('§8c: …and takes authorship, because somebody has to be answerable for the record',
        (string)db_row('SELECT authorName FROM program_journal WHERE entryId = ?', [$PID])['authorName'] !== '');
    chk('§8c: …and the child who proposed it is told',
        (int)(db_row("SELECT COUNT(*) c FROM notifications WHERE memberId = 'NGG-2025-0001' AND kind = 'journal.published'")['c'] ?? 0) === 1);
    chk('§8c: …and an ordinary entry cannot be "published", because it never was a proposal',
        backend_dispatch('journal.publish', ['requesterId' => 'NGG-2025-0099', 'entryId' => $ADV])['error'] === 'not_a_proposal');

    // ── The filter the chip actually asks for ──
    $need = backend_dispatch('journal.feed', ['requesterId' => 'NGG-2025-0099', 'signedIn' => true, 'need' => 'attention']);
    chk('§8c: "Needs attention" returns the open issues and nothing else',
        count($need['entries']) === 2
        && count(array_filter($need['entries'], fn($e) => $e['kind'] === 'issue' && $e['status'] === 'open')) === 2);

    // ── Who may propose ──
    chk('§8c: the footer card is offered to a member, who cannot publish',
        backend_dispatch('journal.feed', ['requesterId' => 'NGG-2025-0001', 'signedIn' => true])['canPropose'] === true);
    chk('§8c: …and not to a mentor, who writes the entry instead of proposing it',
        backend_dispatch('journal.feed', ['requesterId' => 'NGG-2025-0099', 'signedIn' => true])['canPropose'] === false);

    // ── Money, at the edges ──
    chk('§8c: money is rounded the way a tile shows it, at every size',
        pj_money(0) === '₦0' && pj_money(1200000) === '₦12,000'
        && pj_money(4800000, 'NGN', true) === '₦48k'
        && pj_money(150000000, 'NGN', true) === '₦1.5m'
        && pj_money(99900, 'NGN', true) === '₦999');
    chk('§8c: an issue open today does not read "0 days"',
        pj_open_for(gmdate('c'), time()) === 'today'
        && pj_open_for(gmdate('c', time() - 86400), time()) === '1 day'
        && pj_open_for(gmdate('c', time() - 70 * 86400), time()) === '2 months');

    db_exec("DELETE FROM program_journal_updates");
    db_exec("DELETE FROM program_journal_follows");
    db_exec("DELETE FROM program_journal_tags");
    db_exec("DELETE FROM program_journal");
})();


/* ── Analytics depth: comparison, rigour, segmentation ──────────────────────
 * The statistics are tested without fixtures, so a failure points at the maths
 * rather than at a seed. These are the numbers a funder may act on. */
(function () {
    chk('depth: normal CDF matches the known values', (function () {
        return abs(an_norm_cdf(0.0) - 0.5) < 1e-6
            && abs(an_norm_cdf(1.96) - 0.975) < 1e-3
            && abs(an_norm_cdf(-1.96) - 0.025) < 1e-3
            && abs(an_norm_cdf(1.0) - 0.8413) < 1e-3;
    })());
    chk('depth: Wilson does NOT claim certainty from four observations', (function () {
        // The naive interval returns [100, 100] here, which is the whole reason
        // for using Wilson: four children all attending is not proof of 100%.
        $ci = an_ci(4, 4);
        return $ci['rate'] === 100.0 && $ci['low'] < 60.0 && $ci['high'] === 100.0;
    })());
    chk('depth: an interval narrows as n grows', (function () {
        $small = an_ci(3, 4)['width'];
        $mid = an_ci(45, 60)['width'];
        $big = an_ci(300, 400)['width'];
        return $small > $mid && $mid > $big && $big < 12.0;
    })());
    chk('depth: an interval never escapes 0..100', (function () {
        foreach ([[0, 1], [1, 1], [0, 3], [7, 7]] as [$s, $n]) {
            $ci = an_ci($s, $n);
            if ($ci['low'] < 0.0 || $ci['high'] > 100.0) return false;
        }
        return an_ci(0, 0)['rate'] === null;   // no data ⇒ no number
    })());
    chk('depth: a gap on tiny groups is reported as UNKNOWN, not as a finding', (function () {
        // 75% vs 85% on 4 and 20 is the shape of a real centre comparison here.
        $r = an_compare_rates(3, 4, 17, 20);
        return $r['ok'] === false && $r['verdict'] === 'too_small'
            && strpos($r['text'], 'cannot be told apart') !== false;
    })());
    chk('depth: a genuine difference IS reported as significant', (function () {
        $r = an_compare_rates(45, 60, 30, 60);
        return !empty($r['ok']) && !empty($r['significant']) && $r['p'] < 0.05;
    })());
    chk('depth: 60 child-days from 3 children does NOT earn a p-value', (function () {
        /* The clustering trap, and the reason this guard exists. Without the
           child counts the very same call returns a confident p=0.006 — a claim
           about three people dressed up as sixty observations. */
        $loose = an_compare_rates(51, 60, 39, 60);
        $tight = an_compare_rates(51, 60, 39, 60, 3, 3);
        return !empty($loose['significant'])
            && empty($tight['significant'])
            && $tight['verdict'] === 'too_few_people'
            && strpos($tight['text'], 'not independent evidence') !== false;
    })());
    chk('depth: enough children AND enough days does earn one', (function () {
        $r = an_compare_rates(45, 60, 30, 60, 15, 15);
        return !empty($r['ok']) && !empty($r['significant']);
    })());
    chk('depth: a small difference on big groups is reported as noise', (function () {
        $r = an_compare_rates(31, 60, 29, 60);
        return !empty($r['ok']) && empty($r['significant']) && $r['verdict'] === 'not_significant';
    })());
    chk('depth: the previous period is the same length, immediately before', (function () {
        $p = an_previous_period('2026-07-01', '2026-07-14');   // 14 days
        return $p['from'] === '2026-06-17' && $p['to'] === '2026-06-30';
    })());
    chk('depth: age bands and dimension labels are stable', (function () {
        return an_age_band(11) === '10–11' && an_age_band(12) === '12–13'
            && an_age_band(17) === '16–17' && an_age_band(0) === 'Unknown'
            && an_dim_value(['gender' => 'F'], 'gender') === 'Female'
            && an_dim_value(['gender' => ''], 'gender') === 'Not recorded'
            && an_dim_value(['track' => ''], 'track') === 'Unassigned';
    })());
    chk('depth: a child is not charged for days before they enrolled', (function () {
        $days = ['2026-07-01', '2026-07-02', '2026-07-03'];
        $s = ['studentId' => 'X1', 'enrolledAt' => '2026-07-03T00:00:00Z'];
        [$hit, $opp] = an_student_units($s, $days, ['X1' => ['2026-07-03' => true]]);
        // One opportunity, one attendance — not one of three.
        return $opp === 1 && $hit === 1;
    })());
    chk('depth: the op is admin-gated', (function () {
        return backend_dispatch('analytics.depth', ['requesterId' => ''])['ok'] !== true;
    })());
    chk('depth: the op returns comparison, segments, weekday and narrative', (function () {
        $r = backend_dispatch('analytics.depth', ['requesterId' => 'NGG-2025-0099']);
        if (empty($r['ok'])) return false;
        $d = $r['depth'];
        if (!empty($d['empty'])) return true;   // no centres in scope is a valid shape
        return isset($d['headline']['attendance'], $d['crosstab']['rows'], $d['weekday'], $d['retention'])
            && is_array($d['findings']) && count($d['findings']) >= 1
            && count($d['method']) >= 4;
    })());
    chk('depth: a crosstab cell too thin to compare is flagged as such', (function () {
        $r = backend_dispatch('analytics.depth', ['requesterId' => 'NGG-2025-0099']);
        $d = $r['depth'] ?? [];
        if (!empty($d['empty'])) return true;
        foreach (($d['crosstab']['rows'] ?? []) as $row) {
            foreach ($row['cells'] as $c) {
                if (!$c) continue;
                // Every cell must declare whether it is readable on its own.
                if (!array_key_exists('thin', $c) || !array_key_exists('n', $c)) return false;
            }
        }
        return true;
    })());
})();

/* ── Level 6 depth, part two: dose–response, statistical power, concentration ──
 *
 * The three questions the tables cannot answer however carefully they are read:
 * does attending more actually help, what could this cohort even have detected,
 * and who is the headline average made of. Same discipline as above — the maths
 * is tested without fixtures so a failure points at the formula. */
(function () {
    // ── Dose–response ────────────────────────────────────────────────────────
    chk('depth: dose–response refuses to run on a handful of children', (function () {
        $r = an_correlate([10, 20, 30, 40, 50], [1, 2, 3, 4, 5]);
        // A perfect r on five children is exactly the shape that must NOT print.
        return $r['ok'] === false && $r['verdict'] === 'too_few_people'
            && strpos($r['text'], 'not a relationship') !== false;
    })());
    chk('depth: a real dose–response is found, and stated as association not cause', (function () {
        $r = an_correlate(range(10, 21), range(30, 41));
        return !empty($r['ok']) && $r['verdict'] === 'associated' && $r['r'] > 0.99 && $r['p'] < 0.001
            && strpos($r['text'], 'association, not cause') !== false;
    })());
    chk('depth: an outcome everyone shares is "no variation", not r = 0', (function () {
        // Twelve children, identical grade. r is undefined here; reporting 0 would
        // read as "attendance does not matter" from data that cannot say either way.
        $r = an_correlate(range(1, 12), array_fill(0, 12, 55));
        return $r['ok'] === false && $r['verdict'] === 'no_variation'
            && strpos($r['text'], 'nothing to relate') !== false;
    })());
    chk('depth: noise is reported as no association, and points at the power note', (function () {
        $r = an_correlate(range(1, 12), [1, 2, 1, 2, 1, 2, 1, 2, 1, 2, 1, 2]);
        return !empty($r['ok']) && $r['verdict'] === 'not_significant' && empty($r['significant'])
            && strpos($r['text'], 'not proof there is none') !== false
            && strpos($r['text'], 'detectable-effect') !== false;
    })());

    // ── Statistical power ────────────────────────────────────────────────────
    chk('depth: the detectable effect shrinks as the cohort grows', (function () {
        $small = an_detectable(70.0, 10);
        $big = an_detectable(70.0, 160);
        return !empty($small['ok']) && !empty($big['ok']) && $small['mde'] > $big['mde'];
    })());
    chk('depth: quadrupling the children halves the detectable effect', (function () {
        // The sentence the panel prints, checked against the arithmetic behind it.
        $a = an_detectable(70.0, 20)['mde'];
        $b = an_detectable(70.0, 80)['mde'];
        return abs($a / $b - 2.0) < 0.02;
    })());
    chk('depth: a real threshold is stated as one — a 20-point gap at 80 children', (function () {
        /* The number that makes "no significant difference" readable: a 15-point
           gap here could be real and still invisible, and a panel that omits this
           invites the opposite conclusion. */
        $r = an_detectable(70.0, 80);
        return $r['mde'] > 15.0 && $r['mde'] < 25.0 && $r['power'] === 80 && empty($r['blind'])
            && strpos($r['text'], 'not absent — it is invisible here') !== false;
    })());
    chk('depth: at this programme\'s size the figure is a verdict, not a threshold', (function () {
        /* Ten children per group already asks for ~57 points, and five for ~81.
           Printed as an ordinary threshold that reads as a broken calculation, and
           a coordinator who dismisses it also dismisses the warning it carries. */
        foreach ([10, 5] as $per) {
            $r = an_detectable(70.0, $per);
            if (empty($r['ok']) || empty($r['blind']) || $r['mde'] <= 50.0) return false;
            if (strpos($r['text'], 'no realistic gap could be shown at all') === false) return false;
            if (strpos($r['text'], 'unresolved rather than as evidence of no difference') === false) return false;
        }
        return true;
    })());
    chk('depth: too few children to state a detectable effect at all', (function () {
        return an_detectable(70.0, 1)['ok'] === false;
    })());

    // ── Concentration ────────────────────────────────────────────────────────
    chk('depth: a level programme is called even', (function () {
        $r = an_concentration(array_fill(0, 12, 70.0));
        return !empty($r['ok']) && $r['shape'] === 'even' && $r['gini'] < 0.01
            && strpos($r['text'], 'describes most children') !== false;
    })());
    chk('depth: half the children carrying all the attendance is called very uneven', (function () {
        /* Both of these average 50%. One is a healthy programme and one is a
           retention emergency, and the headline rate is identical. */
        $even = an_concentration(array_fill(0, 12, 50.0));
        $split = an_concentration(array_merge(array_fill(0, 6, 100.0), array_fill(0, 6, 0.0)));
        return $even['shape'] === 'even' && $split['shape'] === 'very uneven'
            && $split['topThirdShare'] > 60.0 && $split['bottomThirdShare'] === 0.0
            && abs($split['evenShare'] - 33.3) < 0.2
            && strpos($split['text'], 'weakest third') !== false;
    })());
    chk('depth: a spread below the child floor is refused, not printed', (function () {
        return an_concentration([10.0, 90.0, 50.0])['ok'] === false;
    })());
    chk('depth: nobody attending is not a spread', (function () {
        $r = an_concentration(array_fill(0, 12, 0.0));
        return $r['ok'] === false && strpos($r['text'], 'Nobody attended') !== false;
    })());

    // ── The per-child join ───────────────────────────────────────────────────
    $mkUnits = function (int $n, int $days, callable $attend): array {
        $dayList = [];
        for ($i = 0; $i < $days; $i++) $dayList[] = gmdate('Y-m-d', strtotime("2026-05-04 +$i day"));
        $students = []; $present = [];
        for ($k = 1; $k <= $n; $k++) {
            $sid = 'DOSE-' . $k;
            $students[] = ['studentId' => $sid, 'centre' => 'Egbeda', 'enrolledAt' => '2026-05-01T00:00:00Z'];
            foreach ($dayList as $di => $d) if ($attend($k, $di)) $present[$sid][$d] = true;
        }
        return ['days' => $dayList, 'students' => $students, 'present' => $present];
    };

    chk('depth: a child with no opportunity-days is left out, not entered as 0%', (function () use ($mkUnits) {
        $u = $mkUnits(12, 10, fn($k, $d) => $d < $k);
        // A thirteenth child who enrolled after the window closed.
        $u['students'][] = ['studentId' => 'DOSE-LATE', 'enrolledAt' => '2026-09-01T00:00:00Z'];
        $rates = an_child_rates($u);
        return count($rates) === 12 && !isset($rates['DOSE-LATE']);
    })());

    // Twelve children attending 1..12 of twelve days, so the dose really varies.
    $units = $mkUnits(12, 12, fn($k, $d) => $d < $k);
    foreach ($units['students'] as $s) {
        db_insert('summer_students', ['studentId' => $s['studentId'], 'cohortId' => 'DOSE-C', 'centre' => 'Egbeda',
            'track' => 'Tech', 'status' => 'active', 'enrolledAt' => $s['enrolledAt'], 'updatedAt' => now_iso()]);
    }
    // Grades for ten of the twelve, rising with attendance.
    db_insert('assignments', ['assignmentId' => 'DOSE-A1', 'title' => 'Dose', 'week' => 1, 'points' => 100, 'createdAt' => now_iso()]);
    for ($k = 1; $k <= 10; $k++) {
        db_insert('assignment_submissions', ['submissionId' => 'DOSE-S' . $k, 'assignmentId' => 'DOSE-A1',
            'memberId' => 'DOSE-' . $k, 'status' => 'graded', 'grade' => 40 + $k * 4,
            'submittedAt' => now_iso(), 'gradedAt' => now_iso(), 'createdAt' => now_iso()]);
    }
    // One star on every day each child actually attended.
    foreach ($units['present'] as $sid => $days) {
        foreach (array_keys($days) as $d) {
            db_insert('member_stars', ['subjectId' => $sid, 'subjectType' => 'student', 'givenById' => 'NGG-2025-0099',
                'stars' => 1, 'category' => 'effort', 'centre' => 'Egbeda', 'date' => $d, 'createdAt' => now_iso()]);
        }
    }

    $panels = an_dose_response($units);
    $byKey = []; foreach ($panels as $p) $byKey[$p['key']] = $p;

    chk('depth: a child with no recorded outcome is excluded, not counted as zero', (function () use ($byKey) {
        /* Ten of twelve have a grade. Entering the other two as zero would
           manufacture the very association the panel exists to test — and the
           coverage line has to say so on screen, not just in the code. */
        $g = $byKey['grade'] ?? null;
        return $g && $g['covered'] === 10 && $g['of'] === 12 && $g['n'] === 10;
    })());
    chk('depth: attendance and grades rising together is found as an association', (function () use ($byKey) {
        $g = $byKey['grade'] ?? null;
        return $g && !empty($g['ok']) && $g['verdict'] === 'associated' && $g['r'] > 0.9;
    })());
    chk('depth: stars per day attended is not a restatement of attendance', (function () use ($byKey) {
        /* The trap this denominator exists for. One star per attended day means a
           raw star total correlates with attendance at r = 1.0 by construction —
           and so does stars-per-opportunity-day, which is why that denominator was
           wrong too. Per day attended is a flat 1.0 for every child, so the panel
           correctly reports it has nothing to relate rather than a perfect finding. */
        $s = $byKey['stars'] ?? null;
        return $s && $s['ok'] === false && $s['verdict'] === 'no_variation';
    })());

    // ── Findings and payload ─────────────────────────────────────────────────
    chk('depth: an absent dose–response is raised as a warning, not left as a null result', (function () {
        $f = an_findings(['dose' => [[
            'key' => 'grade', 'outcome' => 'Assignment grades', 'unit' => 'average graded score',
            'has' => 'a graded score', 'covered' => 14, 'of' => 20,
            'ok' => true, 'verdict' => 'not_significant', 'text' => 'No association.',
        ]]]);
        foreach ($f as $x) if ($x['code'] === 'dose_flat') {
            return $x['severity'] === 'warn' && strpos($x['detail'], 'what happens') !== false;
        }
        return false;
    })());
    chk('depth: a concentrated average is raised as a finding about two groups', (function () {
        $sp = an_concentration(array_merge(array_fill(0, 6, 100.0), array_fill(0, 6, 0.0)));
        $f = an_findings(['spread' => $sp]);
        foreach ($f as $x) if ($x['code'] === 'attendance_concentrated') return $x['severity'] === 'bad';
        return false;
    })());
    chk('depth: a flat period carries the size of the gap it could have seen', (function () {
        /* Without this the screen says "level" and a coordinator reads "nothing
           changed", from a cohort that could not have seen a 20-point move. */
        $now = ['hit' => 45, 'opp' => 60, 'n' => 20] + an_ci(45, 60);
        $prev = ['hit' => 43, 'opp' => 60, 'n' => 20] + an_ci(43, 60);
        $f = an_findings(['now' => $now, 'prev' => $prev, 'power' => an_detectable(75.0, 40)]);
        foreach ($f as $x) if ($x['code'] === 'period_flat') return strpos($x['detail'], 'invisible here') !== false;
        return false;
    })());
    chk('depth: a flat period on a blind cohort says so instead of naming a threshold', (function () {
        $now = ['hit' => 45, 'opp' => 60, 'n' => 20] + an_ci(45, 60);
        $prev = ['hit' => 43, 'opp' => 60, 'n' => 20] + an_ci(43, 60);
        $f = an_findings(['now' => $now, 'prev' => $prev, 'power' => an_detectable(75.0, 8)]);
        foreach ($f as $x) if ($x['code'] === 'period_flat') return strpos($x['detail'], 'unresolved') !== false;
        return false;
    })());
    chk('depth: the coverage sentence reads as English for every outcome', (function () {
        /* "children have a average graded score" shipped once. The phrase that
           follows "have" cannot be the same string as the axis label. */
        $f = an_findings(['dose' => [[
            'key' => 'stars', 'outcome' => 'Mentor stars', 'unit' => 'stars per day attended',
            'has' => 'stars on record', 'covered' => 14, 'of' => 20,
            'ok' => true, 'verdict' => 'associated', 'text' => 'Found.',
        ]]]);
        foreach ($f as $x) if ($x['code'] === 'dose_response') {
            return strpos($x['detail'], 'do not have stars on record') !== false
                && strpos($x['detail'], 'stars per day attended') === false;
        }
        return false;
    })());
    chk('depth: the empty state names the dose and spread checks it could not run', (function () {
        $f = an_findings([]);
        return count($f) === 1 && $f[0]['code'] === 'nothing_testable'
            && strpos($f[0]['detail'], 'attending and doing better') !== false
            && strpos($f[0]['detail'], 'uneven spread') !== false;
    })());
    chk('depth: the op returns spread, dose–response and detectable effect', (function () {
        $r = backend_dispatch('analytics.depth', ['requesterId' => 'NGG-2025-0099']);
        if (empty($r['ok'])) return false;
        $d = $r['depth'];
        if (!empty($d['empty'])) return true;
        if (!isset($d['spread'], $d['dose'], $d['power']) || !is_array($d['dose'])) return false;
        // Every dose panel must carry its coverage, so the screen can say who is in it.
        foreach ($d['dose'] as $p) if (!isset($p['covered'], $p['of'], $p['outcome'], $p['unit'], $p['has'], $p['text'])) return false;
        // And the method list must explain all three, or they are unreadable numbers.
        return isset($d['method']['power'], $d['method']['dose'], $d['method']['spread']);
    })());
})();

/* ── Sex, and the reason a funder could not be answered ──────────────────────
 *
 * The finding this block was written for: `summer_students` had a `sex` column
 * (migration 34) AND a `gender` column (migration 39) for the same fact,
 * NOTHING in the product ever wrote either — the registration form did not ask
 * — and the analytics workspace read `gender`, so the gender panel reported
 * every child as "Not recorded" for every cohort this system has ever run.
 *
 * It passed the suite the whole time, because the analytics fixtures insert
 * `gender` by hand. These tests go through the real registration route instead,
 * which is the only way this class of bug is visible.
 */
(function () {
    $ADM = 'NGG-2025-0099';

    chk('sex: one vocabulary, and "not recorded" stays its own answer', (function () {
        return sex_normalise('M') === 'Male' && sex_normalise('female') === 'Female'
            && sex_normalise('  Boy ') === 'Male' && sex_normalise('girl') === 'Female'
            && sex_normalise('') === '' && sex_normalise('prefer not to say') === ''
            /* Prefers `sex`, falls back to the legacy column, so a row written
               before migration 78 reads correctly even where the backfill has
               not run. */
            && person_sex(['sex' => '', 'gender' => 'F']) === 'Female'
            && person_sex(['sex' => 'Male', 'gender' => 'F']) === 'Male'
            && sex_label(['sex' => '']) === 'Not recorded';
    })());

    chk('sex: the registration form asks, and asks in a locked field', (function () use ($ADM) {
        $f = backend_dispatch('admin.forms.get', ['requesterId' => $ADM, 'formId' => 'summer-reg'])['form']['fields'] ?? [];
        $sex = null; foreach ($f as $x) if (($x['key'] ?? '') === 'sex') $sex = $x;
        $v = backend_dispatch('admin.forms.get', ['requesterId' => $ADM, 'formId' => 'volunteer'])['form']['fields'] ?? [];
        $vsex = null; foreach ($v as $x) if (($x['key'] ?? '') === 'sex') $vsex = $x;
        /* Locked, so a republish cannot quietly drop it. A cohort registered
           without sex can never be disaggregated afterwards — it is not
           recoverable from a name and re-asking the families is not a plan. */
        return $sex && !empty($sex['locked']) && $sex['options'] === ['Male', 'Female'] && empty($sex['required'])
            && $vsex && !empty($vsex['locked']);
    })());

    chk('sex: a form published before the field existed gets it back on read', (function () {
        /* The mechanism this codebase already built for exactly this — a live
           form row written last month has no `sex` key, and serving it verbatim
           would mean the field ships in code and never reaches a parent. */
        $fields = array_values(array_filter(form_defaults_for('summer-reg'), fn($f) => ($f['key'] ?? '') !== 'sex'));
        $back = form_restore_locked($fields, 'summer-reg');
        $keys = array_column($back, 'key');
        $i = array_search('sex', $keys, true);
        // Beside its neighbour, not at a numeric index into a different list.
        return $i !== false && $keys[$i - 1] === 'dob';
    })());

    chk('sex: a child registered through the real route arrives with it stored', (function () use ($ADM) {
        $centre = (string)(db_row("SELECT name FROM centres WHERE status = 'active' ORDER BY id LIMIT 1")['name'] ?? 'Main');
        $g = backend_dispatch('admin.gates.create', ['requesterId' => $ADM, 'kind' => 'register', 'generate' => true, 'name' => 'Sex desk']);
        $r = backend_dispatch('gate.register', ['gate' => $g['gateId'], 'data' => [
            'fullName' => 'Sex Test Child', 'firstName' => 'Sex', 'lastName' => 'Child',
            'dob' => gmdate('Y-m-d', strtotime('-12 years -2 months')),
            'sex' => 'Female',
            'faculty' => 'Music', 'course' => 'Piano', 'centre' => $centre,
            'parentName' => 'A Parent', 'parentPhone' => '08030000901']]);
        if (empty($r['ok'])) return false;
        $GLOBALS['__sexKid'] = (string)($r['studentId'] ?? '');
        $row = db_row('SELECT sex FROM summer_students WHERE studentId = ?', [$GLOBALS['__sexKid']]);
        return $row && (string)$row['sex'] === 'Female';
    })());

    chk('sex: …and a value off the dropdown is refused rather than stored as a fourth spelling', (function () use ($ADM) {
        /* The form's own option check runs first — which is right, and is why
           the normaliser exists for the paths that have no dropdown: the desk
           enrolment, the roster edit and the CSV import. */
        $centre = (string)(db_row("SELECT name FROM centres WHERE status = 'active' ORDER BY id LIMIT 1")['name'] ?? 'Main');
        $g = backend_dispatch('admin.gates.create', ['requesterId' => $ADM, 'kind' => 'register', 'generate' => true, 'name' => 'Sex desk 2']);
        $r = backend_dispatch('gate.register', ['gate' => $g['gateId'], 'data' => [
            'fullName' => 'Bad Sex Child', 'firstName' => 'Bad', 'lastName' => 'Child',
            'dob' => gmdate('Y-m-d', strtotime('-12 years -2 months')), 'sex' => 'boy',
            'faculty' => 'Music', 'course' => 'Piano', 'centre' => $centre,
            'parentName' => 'A Parent', 'parentPhone' => '08030000902']]);
        return !empty($r['errors']['sex']);
    })());

    chk('sex: the analytics gender panel counts them, which it never did before', (function () use ($ADM) {
        db_exec("UPDATE summer_students SET sex = 'Female', gender = '' WHERE studentId LIKE 'SUM-AN-1%'");
        db_exec("UPDATE summer_students SET sex = 'Male', gender = '' WHERE studentId LIKE 'SUM-AN-2%'");
        $r = backend_dispatch('analytics.workspace', ['requesterId' => $ADM]);
        $rows = $r['workspace']['research']['gender'] ?? [];
        $by = []; foreach ($rows as $x) $by[$x['gender']] = (int)$x['count'];
        /* THE regression. Before the fix `perStudent` read $s['gender'] — a
           column nothing writes — so this array was one row, "Not recorded",
           holding the whole cohort. */
        return ($by['Female'] ?? 0) >= 1 && ($by['Male'] ?? 0) >= 1;
    })());

    chk('sex: …and the gender crosstab can finally show a gap', (function () use ($ADM) {
        $r = backend_dispatch('analytics.depth', ['requesterId' => $ADM, 'rowDim' => 'gender', 'colDim' => 'age']);
        $d = $r['depth'] ?? [];
        if (!empty($d['empty'])) return true;
        $rows = array_column($d['crosstab']['rows'] ?? [], 'label');
        /* Not one undifferentiated "Not recorded" bucket, which is what this
           returned for every cohort before the fix — so the panel that exists
           to show whether girls and boys learn differently could only ever
           report that there was no difference. */
        return in_array('Female', $rows, true) && in_array('Male', $rows, true);
    })());

    /* ── The transition window ───────────────────────────────────────────────
     * Grades 4–6 and 7–9 — where gender gaps in schooling widen, and therefore
     * what an evidence fund's eligibility section is written against. Without a
     * class on the record it is not a question this system can answer, and it
     * is the first thing such an application asks.
     */
    chk('grade: a class is asked in the words a parent uses and stored as a number', (function () {
        /* Ask locally, store globally. A funder writes "grades 7 to 9"; a Lagos
           parent knows their child is in JSS 2. A VARCHAR holding both spellings
           is something somebody maps by hand the week a proposal is due. */
        return grade_normalise('JSS 2') === 8 && grade_normalise('jss2') === 8
            && grade_normalise('J.S.S 3') === 9 && grade_normalise('P4') === 4
            && grade_normalise('Basic 6') === 6 && grade_normalise('grade 8') === 8
            && grade_normalise('SSS 1') === 10 && grade_normalise(5) === 5
            /* A wrong grade is worse than a missing one — it puts a child inside
               an eligibility window they are not in, and an application built on
               that misrepresents the programme to a funder. */
            && grade_normalise('nursery 2') === 0 && grade_normalise('creche') === 0
            && grade_normalise('13') === 0 && grade_normalise('') === 0;
    })());

    chk('grade: the two transition windows are the funders\' windows, held as data', (function () {
        return grade_band(3)['transition'] === false && grade_band(4)['transition'] === true
            && grade_band(6)['transition'] === true && grade_band(7)['transition'] === true
            && grade_band(9)['transition'] === true && grade_band(10)['transition'] === false
            && grade_in_transition(4) && grade_in_transition(9)
            && !grade_in_transition(3) && !grade_in_transition(10) && !grade_in_transition(0)
            && grade_band(8)['label'] === 'JSS 1–3' && grade_band(0)['label'] === 'Not recorded';
    })());

    chk('grade: the registration form asks for it, locked, in local words', (function () use ($ADM) {
        $f = backend_dispatch('admin.forms.get', ['requesterId' => $ADM, 'formId' => 'summer-reg'])['form']['fields'] ?? [];
        $g = null; foreach ($f as $x) if (($x['key'] ?? '') === 'grade') $g = $x;
        return $g && !empty($g['locked']) && empty($g['required'])
            && in_array('JSS 2', $g['options'], true) && in_array('Primary 4', $g['options'], true)
            && count($g['options']) === 12;
    })());

    chk('grade: a child registered with a class carries the number AND the day it was true', (function () use ($ADM) {
        $centre = (string)(db_row("SELECT name FROM centres WHERE status = 'active' ORDER BY id LIMIT 1")['name'] ?? 'Main');
        $g = backend_dispatch('admin.gates.create', ['requesterId' => $ADM, 'kind' => 'register', 'generate' => true, 'name' => 'Grade desk']);
        $r = backend_dispatch('gate.register', ['gate' => $g['gateId'], 'data' => [
            'fullName' => 'Grade Test Child', 'firstName' => 'Grade', 'lastName' => 'Child',
            'dob' => gmdate('Y-m-d', strtotime('-13 years -2 months')), 'sex' => 'Male', 'grade' => 'JSS 2',
            'faculty' => 'Music', 'course' => 'Piano', 'centre' => $centre,
            'parentName' => 'A Parent', 'parentPhone' => '08030000903']]);
        if (empty($r['ok'])) return false;
        $GLOBALS['__gradeKid'] = (string)($r['studentId'] ?? '');
        $row = db_row('SELECT gradeLevel, gradeAsAt FROM summer_students WHERE studentId = ?', [$GLOBALS['__gradeKid']]);
        /* The date matters as much as the number. A child registered in Primary
           4 in June is in Primary 5 by September, and reporting them as Primary
           4 two years later is a false statement about eligibility, not a stale
           one. */
        return $row && (int)$row['gradeLevel'] === 8 && (string)$row['gradeAsAt'] === gmdate('Y-m-d')
            && person_grade($row)['transition'] === true
            && person_grade($row)['label'] === 'JSS 2';
    })());

    chk('grade: a stored class ages, and says so rather than pretending', (function () {
        $old = ['gradeLevel' => 4, 'gradeAsAt' => gmdate('Y-m-d', strtotime('-3 years'))];
        $fresh = ['gradeLevel' => 4, 'gradeAsAt' => gmdate('Y-m-d')];
        return person_grade($old)['yearsStale'] === 3 && person_grade($fresh)['yearsStale'] === 0
            && person_grade(['gradeLevel' => 0])['yearsStale'] === 0;
    })());

    chk('grade: the workspace can say how many children are at the transition point', (function () use ($ADM) {
        $r = backend_dispatch('analytics.workspace', ['requesterId' => $ADM]);
        $tw = $r['workspace']['research']['transitionWindow'] ?? null;
        if (!is_array($tw)) return false;
        /* Reported over children WITH a class on file, never over the roster.
           "18% are at the transition point" when only a quarter have a class
           recorded is a number that goes into an application and is wrong. */
        return array_key_exists('inWindow', $tw) && array_key_exists('recorded', $tw)
            && array_key_exists('enrolled', $tw)
            && ($tw['recorded'] === 0 ? $tw['pct'] === null : $tw['pct'] === (int)round($tw['inWindow'] / $tw['recorded'] * 100));
    })());

    chk('grade: …and cross-tabulate the class band against sex', (function () use ($ADM) {
        $r = backend_dispatch('analytics.depth', ['requesterId' => $ADM, 'rowDim' => 'grade', 'colDim' => 'gender']);
        $d = $r['depth'] ?? [];
        if (!empty($d['empty'])) return true;
        $rows = array_column($d['crosstab']['rows'] ?? [], 'label');
        // Bands, not twelve rows of three children each — every cell too thin
        // to mean anything is a table with nothing in it.
        return isset($d['dims']['grade']) && $d['crosstab']['rowDim'] === 'grade'
            && (in_array('JSS 1–3', $rows, true) || in_array('Primary 4–6', $rows, true)
                || in_array('Not recorded', $rows, true));
    })());

    chk('grade: the analysts can see the window, and the description says so', (function () use ($ADM) {
        $ev = insight_evidence(['requesterId' => $ADM]);
        if (!empty($ev['empty'])) return true;
        $t = $ev['transition'] ?? null;
        if (!is_array($t) || !array_key_exists('coveragePct', $t)) return false;
        $cap = ichat_capabilities(ichat_shape($ev));
        // Only named while the block is actually populated — the drift rule.
        if (empty($t['bands'])) return strpos($cap, 'transition point') === false;
        return strpos($cap, 'transition point') !== false
            && insight_scrub(json_encode($ev, JSON_UNESCAPED_SLASHES) ?: '') === [];
    })());

    chk('grade: a cohort registered before the field existed is fixable from the roster', (function () use ($ADM) {
        $id = $GLOBALS['__gradeKid'] ?? '';
        if ($id === '') return true;
        $up = backend_dispatch('admin.summer.student.update', ['requesterId' => $ADM, 'studentId' => $id,
            'data' => ['grade' => 'Primary 5']]);
        $row = db_row('SELECT gradeLevel, gradeAsAt FROM summer_students WHERE studentId = ?', [$id]);
        backend_dispatch('admin.summer.student.update', ['requesterId' => $ADM, 'studentId' => $id, 'data' => ['grade' => 'nursery 1']]);
        $cleared = db_row('SELECT gradeLevel, gradeAsAt FROM summer_students WHERE studentId = ?', [$id]);
        // Re-stamped on edit: a coordinator correcting a class in October is
        // stating what is true in October, not amending the June record.
        return !empty($up['ok']) && (int)$row['gradeLevel'] === 5 && (string)$row['gradeAsAt'] === gmdate('Y-m-d')
            && (int)$cleared['gradeLevel'] === 0 && (string)$cleared['gradeAsAt'] === '';
    })());

    chk('sex: a cohort registered before the field existed is fixable from the roster', (function () use ($ADM) {
        $id = $GLOBALS['__sexKid'] ?? '';
        if ($id === '') return true;
        $up = backend_dispatch('admin.summer.student.update', ['requesterId' => $ADM, 'studentId' => $id,
            'data' => ['sex' => 'M']]);
        $row = db_row('SELECT sex FROM summer_students WHERE studentId = ?', [$id]);
        // …and an unrecognised value clears it rather than storing a fourth spelling.
        backend_dispatch('admin.summer.student.update', ['requesterId' => $ADM, 'studentId' => $id, 'data' => ['sex' => 'other']]);
        $cleared = db_row('SELECT sex FROM summer_students WHERE studentId = ?', [$id]);
        return !empty($up['ok']) && (string)$row['sex'] === 'Male' && (string)$cleared['sex'] === '';
    })());
})();

/* ── Baseline and endline ────────────────────────────────────────────────────
 *
 * The programme could report an average coursework grade and call the trend a
 * learning gain. It is not one: different tasks, different markers, drifting
 * difficulty, and a different set of children submitting each week. What a
 * funder means by "we measured learning" is the same instrument administered
 * twice to the same children, differenced per child — and the tests that matter
 * here are the ones about what makes that number defensible rather than merely
 * produced.
 */
(function () {
    $ADM = 'NGG-2025-0099';
    $c = summer_ensure_cohort();

    chk('assessment: an instrument locks the moment it has measured a child', (function () use ($ADM) {
        $r = backend_dispatch('admin.assessment.instrument.save', ['requesterId' => $ADM, 'data' => [
            'name' => 'EGRA oral reading', 'domain' => 'literacy', 'maxScore' => 50, 'items' => 20,
            'gradeFrom' => 'Primary 4', 'gradeTo' => 'JSS 3']]);
        if (empty($r['ok'])) return false;
        $GLOBALS['__instr'] = $r['instrumentId'];
        // Editable while nothing has been measured with it.
        $edit = backend_dispatch('admin.assessment.instrument.save', ['requesterId' => $ADM,
            'instrumentId' => $r['instrumentId'], 'data' => ['name' => 'EGRA oral reading', 'domain' => 'literacy',
                'maxScore' => 60, 'gradeFrom' => 'Primary 4', 'gradeTo' => 'JSS 3']]);
        $row = db_row('SELECT maxScore, gradeFrom, gradeTo FROM assessment_instruments WHERE instrumentId = ?', [$r['instrumentId']]);
        return !empty($edit['ok']) && (int)$row['maxScore'] === 60
            // Grades normalised through the same helper the registration form uses.
            && (int)$row['gradeFrom'] === 4 && (int)$row['gradeTo'] === 9;
    })());

    chk('assessment: a window is one administration, and there is only one per phase', (function () use ($ADM) {
        $iid = $GLOBALS['__instr'] ?? '';
        if ($iid === '') return true;
        $b = backend_dispatch('admin.assessment.window.save', ['requesterId' => $ADM, 'data' => [
            'instrumentId' => $iid, 'phase' => 'baseline', 'label' => 'Week 1', 'opensAt' => '2026-07-06', 'closesAt' => '2026-07-10']]);
        $e = backend_dispatch('admin.assessment.window.save', ['requesterId' => $ADM, 'data' => [
            'instrumentId' => $iid, 'phase' => 'endline', 'label' => 'Week 6', 'opensAt' => '2026-08-10', 'closesAt' => '2026-08-14']]);
        /* A second baseline for the same test is not a richer dataset. It is an
           ambiguity about which score pairs with the endline, and it would be
           resolved silently by whichever row a query happened to read first. */
        $dupe = backend_dispatch('admin.assessment.window.save', ['requesterId' => $ADM, 'data' => [
            'instrumentId' => $iid, 'phase' => 'baseline', 'label' => 'Oops']]);
        $bad = backend_dispatch('admin.assessment.window.save', ['requesterId' => $ADM, 'data' => [
            'instrumentId' => $iid, 'phase' => 'midline', 'opensAt' => '2026-08-01', 'closesAt' => '2026-07-01']]);
        $GLOBALS['__wBase'] = $b['windowId'] ?? ''; $GLOBALS['__wEnd'] = $e['windowId'] ?? '';
        return !empty($b['ok']) && !empty($e['ok'])
            && ($dupe['error'] ?? '') === 'phase_exists' && ($bad['error'] ?? '') === 'bad_dates';
    })());

    /* Twelve children with a known pattern, so every number below can be
       checked by hand rather than merely observed. */
    $kids = [];
    for ($i = 1; $i <= 12; $i++) {
        $id = 'AS-' . $i;
        db_insert('summer_students', ['studentId' => $id, 'cohortId' => (string)$c['cohortId'],
            'fullName' => 'Assess Child ' . $i, 'firstName' => 'Assess', 'lastName' => 'Child' . $i,
            'age' => 12, 'centre' => 'Assessville', 'track' => 'Tech',
            'sex' => $i % 2 === 0 ? 'Female' : 'Male', 'gradeLevel' => $i <= 6 ? 5 : 8,
            'gradeAsAt' => gmdate('Y-m-d'), 'status' => 'active', 'regStatus' => 'verified',
            'enrolledAt' => now_iso(), 'updatedAt' => now_iso()]);
        $kids[] = $id;
    }

    chk('assessment: a score above the paper\'s maximum is refused, not clamped', (function () use ($ADM) {
        $w = $GLOBALS['__wBase'] ?? ''; if ($w === '') return true;
        $r = backend_dispatch('admin.assessment.record', ['requesterId' => $ADM, 'windowId' => $w,
            'results' => [['studentId' => 'AS-1', 'score' => 999], ['studentId' => 'NOPE', 'score' => 10]]]);
        /* A 55 on a paper marked out of 50 is a transcription error. Clamping it
           to 50 buries the error inside a number somebody later averages. */
        return !empty($r['ok']) && $r['saved'] === 0 && count($r['rejected']) === 2;
    })());

    chk('assessment: absent is not a zero', (function () use ($ADM) {
        $w = $GLOBALS['__wBase'] ?? ''; if ($w === '') return true;
        backend_dispatch('admin.assessment.record', ['requesterId' => $ADM, 'windowId' => $w,
            'results' => [['studentId' => 'AS-12', 'absent' => true]]]);
        $row = db_row("SELECT score, absent FROM assessment_results WHERE windowId = ? AND studentId = 'AS-12'", [$w]);
        /* A child who did not sit did not score nothing — they have no score.
           Recording absence as 0 drags the mean down and turns an attendance
           problem into a learning finding. The analysis excludes absent rows. */
        return $row && (int)$row['absent'] === 1;
    })());

    chk('assessment: recording the first score locks the instrument against silent revision', (function () use ($ADM) {
        $w = $GLOBALS['__wBase'] ?? ''; $iid = $GLOBALS['__instr'] ?? '';
        if ($w === '' || $iid === '') return true;
        /* Baseline: children 1–6 score 20, children 7–11 score 30. */
        $res = [];
        for ($i = 1; $i <= 11; $i++) $res[] = ['studentId' => 'AS-' . $i, 'score' => $i <= 6 ? 20 : 30];
        $rec = backend_dispatch('admin.assessment.record', ['requesterId' => $ADM, 'windowId' => $w, 'results' => $res]);
        $inst = db_row('SELECT lockedAt FROM assessment_instruments WHERE instrumentId = ?', [$iid]);
        /* Revising a test after baseline makes every existing pair
           incomparable, and the revision leaves no trace in the numbers. */
        $edit = backend_dispatch('admin.assessment.instrument.save', ['requesterId' => $ADM,
            'instrumentId' => $iid, 'data' => ['name' => 'EGRA oral reading', 'domain' => 'numeracy', 'maxScore' => 60]]);
        // The NAME stays editable — fixing a typo in a label alters no score.
        $rename = backend_dispatch('admin.assessment.instrument.save', ['requesterId' => $ADM,
            'instrumentId' => $iid, 'data' => ['name' => 'EGRA oral reading v1', 'domain' => 'literacy', 'maxScore' => 60,
                'gradeFrom' => 'Primary 4', 'gradeTo' => 'JSS 3']]);
        // …and the honest path when a test genuinely must change is a new version.
        $rev = backend_dispatch('admin.assessment.instrument.revise', ['requesterId' => $ADM, 'instrumentId' => $iid]);
        return $rec['saved'] === 11 && (string)$inst['lockedAt'] !== ''
            && ($edit['error'] ?? '') === 'locked' && !empty($edit['note'])
            && !empty($rename['ok']) && !empty($rev['ok']) && (int)$rev['version'] === 2;
    })());

    chk('assessment: THE number is the mean of per-child differences, not of two cohorts', (function () use ($ADM) {
        $we = $GLOBALS['__wEnd'] ?? ''; if ($we === '') return true;
        /* Endline: children 1–6 return and gain 10 each (20 → 30). Children
           7–11 — the HIGHER scorers at baseline — do not come back. So:
             two-cohort comparison: baseline mean 24.5 → endline mean 30, "+5.5"
             paired difference over the six who sat both: exactly +10
           The two answers differ, and only the second is a claim about learning. */
        $res = [];
        for ($i = 1; $i <= 6; $i++) $res[] = ['studentId' => 'AS-' . $i, 'score' => 30];
        backend_dispatch('admin.assessment.record', ['requesterId' => $ADM, 'windowId' => $we, 'results' => $res]);
        $g = backend_dispatch('admin.assessment.gains', ['requesterId' => $ADM, 'instrumentId' => $GLOBALS['__instr']]);
        $row = ($g['gains'] ?? [])[0] ?? null;
        if (!$row) return false;
        $GLOBALS['__gain'] = $row;

        return $row['paired'] === 6 && $row['satBaseline'] === 11 && $row['satEndline'] === 6
            && abs($row['gain']['mean'] - 10) < 0.01
            // Zero variance in the differences, so the interval collapses on it.
            && abs($row['gain']['lo'] - 10) < 0.01 && abs($row['gain']['hi'] - 10) < 0.01
            && $row['gain']['significant'] === true
            /* The paired baseline (20) is NOT the cohort baseline (24.5). Both
               are reported, because quoting the second beside the endline is
               the mistake this whole file exists to prevent. */
            && abs($row['pairedBaselinePct'] - 20 / 60 * 100) < 0.2
            /* 270/11 = 24.545 out of 60 = 40.9%. Not 41.7% — which is what it
               was when the mean was cast to an int before the division, an
               error introduced by the code rather than present in the data. */
            && abs($row['baselineMeanPct'] - 40.9) < 0.05;
    })());

    chk('assessment: attrition is measured and its DIRECTION named', (function () {
        $row = $GLOBALS['__gain'] ?? null; if (!$row) return true;
        $a = $row['attrition'];
        /* The first question a reviewer asks. Here the leavers scored HIGHER at
           baseline (30 vs 20), so the +10 gain is if anything an understatement
           — and the report has to say which way it cuts rather than leave a
           reader to work it out. */
        return $a['baselineOnly'] === 5 && is_array($a['bias'])
            && $a['bias']['direction'] === 'leavers_were_stronger'
            && $a['bias']['deltaPoints'] < 0;
    })());

    chk('assessment: …and says so in words, alongside the no-control-group caveat', (function () {
        $row = $GLOBALS['__gain'] ?? null; if (!$row) return true;
        $texts = implode(' | ', array_column($row['caveats'], 'text'));
        $levels = array_column($row['caveats'], 'level');
        /* The first caveat is always the one that matters most: pre/post with no
           comparison group measures how much these children changed, not how
           much of it the programme caused. Nothing in this feature may be
           phrased as causation. */
        return in_array('method', $levels, true)
            && strpos($texts, 'not how much of the change the programme caused') !== false
            // 6 of 11 came back — under the 70% floor, and said.
            && strpos($texts, 'came back for the endline') !== false
            && strpos($texts, 'understatement') !== false;
    })());

    chk('assessment: the gain splits by sex and by class band', (function () {
        $row = $GLOBALS['__gain'] ?? null; if (!$row) return true;
        $bySex = []; foreach ($row['bySex'] as $r) $bySex[$r['group']] = $r;
        $byBand = []; foreach ($row['byBand'] as $r) $byBand[$r['group']] = $r;
        /* Three girls and three boys among the six pairs — each under the
           five-pair floor, so each is MARKED rather than quietly reported. That
           is the finding: we cannot yet say whether girls gained more. */
        return count($bySex) === 2 && $bySex['Female']['n'] === 3 && $bySex['Male']['n'] === 3
            && $bySex['Female']['tooThin'] === true && $bySex['Male']['tooThin'] === true
            // All six pairs are Primary 4–6; the JSS children never returned.
            && isset($byBand['Primary 4–6']) && $byBand['Primary 4–6']['n'] === 6;
    })());

    chk('assessment: a paired mean under the floor is refused rather than quoted', (function () {
        $st = assess_paired_stats([4, 6, 5]);
        $ok = assess_paired_stats([4, 6, 5, 5, 5, 5]);
        return $st['n'] === 3 && $st['tooThin'] === true && $st['significant'] === false
            && $ok['tooThin'] === false && $ok['n'] === 6
            && assess_paired_stats([])['mean'] === null;
    })());

    chk('assessment: an interval that spans zero is not called a change', (function () {
        /* Movement in both directions and a mean near zero: the honest answer is
           that this sample cannot distinguish it from noise. */
        $st = assess_paired_stats([-8, 9, -6, 7, -5, 6, -7, 4]);
        return $st['significant'] === false && $st['lo'] < 0 && $st['hi'] > 0;
    })());

    chk('assessment: the sheet flags a child the instrument was not written for', (function () use ($ADM) {
        $w = $GLOBALS['__wBase'] ?? ''; if ($w === '') return true;
        $sh = backend_dispatch('admin.assessment.sheet', ['requesterId' => $ADM, 'windowId' => $w, 'centre' => 'Assessville']);
        $by = []; foreach ($sh['students'] ?? [] as $s) $by[$s['studentId']] = $s;
        db_insert('summer_students', ['studentId' => 'AS-P1', 'cohortId' => (string)summer_ensure_cohort()['cohortId'],
            'fullName' => 'Too Young', 'centre' => 'Assessville', 'gradeLevel' => 1, 'status' => 'active',
            'regStatus' => 'verified', 'enrolledAt' => now_iso(), 'updatedAt' => now_iso()]);
        $sh2 = backend_dispatch('admin.assessment.sheet', ['requesterId' => $ADM, 'windowId' => $w, 'centre' => 'Assessville']);
        $by2 = []; foreach ($sh2['students'] ?? [] as $s) $by2[$s['studentId']] = $s;
        /* Flagged, not excluded. Silently dropping a child shrinks the sample
           with nothing on screen to show it happened. */
        return isset($by['AS-1']) && $by['AS-1']['outOfRange'] === false
            && $by['AS-1']['result']['score'] === 20
            && isset($by2['AS-P1']) && $by2['AS-P1']['outOfRange'] === true;
    })());

    /* ── The catalogue of published instruments ─────────────────────────────
     * The machinery above can administer any instrument. What was missing was
     * the shortlist of ones a reviewer already recognises, with the provenance
     * attached — because "a test we wrote" is the weakest possible answer to
     * "measured with what?". */

    chk('assessment: the catalogue ships real instruments with a citation each', (function () use ($ADM) {
        $r = backend_dispatch('admin.assessment.catalogue', ['requesterId' => $ADM]);
        if (empty($r['ok']) || count($r['catalogue']) < 12) return false;
        foreach ($r['catalogue'] as $c) {
            // An entry with no source, licence or citation is decoration.
            foreach (['name', 'family', 'source', 'licence', 'citation', 'adapt', 'unit'] as $f) {
                if (trim((string)($c[$f] ?? '')) === '') return false;
            }
            if (!in_array($c['scale'], ASSESS_SCALES, true)) return false;
            if (!in_array($c['domain'], ASSESS_DOMAINS, true)) return false;
        }
        $keys = array_column($r['catalogue'], 'key');
        // The fund this was assembled for asks about gender AND learning.
        $domains = array_unique(array_column($r['catalogue'], 'domain'));
        return count($keys) === count(array_unique($keys))
            && in_array('literacy', $domains, true) && in_array('numeracy', $domains, true)
            && in_array('gender_attitudes', $domains, true)
            && strpos((string)$r['note'], 'local adaptation') !== false;
    })());

    chk('assessment: adopting carries the provenance onto the instrument', (function () use ($ADM) {
        $r = backend_dispatch('admin.assessment.adopt', ['requesterId' => $ADM, 'keys' => ['egra.orf']]);
        if (empty($r['ok']) || count($r['created']) !== 1) return false;
        $iid = $r['created'][0]['instrumentId'];
        $GLOBALS['__catOrf'] = $iid;
        $row = db_row('SELECT * FROM assessment_instruments WHERE instrumentId = ?', [$iid]);
        return (string)$row['catalogueKey'] === 'egra.orf'
            && strpos((string)$row['citation'], 'RTI International') !== false
            && (string)$row['scale'] === 'rate'
            && strpos((string)$row['unit'], 'per minute') !== false
            && trim((string)$row['adaptNote']) !== ''
            && (int)$row['gradeFrom'] === 2 && (int)$row['gradeTo'] === 6;
    })());

    chk('assessment: adopting the same instrument twice does not mint a second one', (function () use ($ADM) {
        /* Two instruments for one test split a cohort's results into two
           half-sized paired sets, each below the floor, with nothing on screen
           to explain why the numbers halved. */
        $again = backend_dispatch('admin.assessment.adopt', ['requesterId' => $ADM, 'keys' => ['egra.orf', 'not.a.real.key']]);
        $n = (int)(db_row("SELECT COUNT(*) c FROM assessment_instruments WHERE catalogueKey = 'egra.orf' AND archivedAt = ''")['c'] ?? 0);
        return !empty($again['ok']) && $n === 1 && count($again['created']) === 0
            && count($again['existing']) === 1 && $again['unknown'] === ['not.a.real.key'];
    })());

    chk('assessment: the catalogue marks what has already been adopted', (function () use ($ADM) {
        $r = backend_dispatch('admin.assessment.catalogue', ['requesterId' => $ADM]);
        $orf = null; $other = null;
        foreach ($r['catalogue'] as $c) { if ($c['key'] === 'egra.orf') $orf = $c; elseif ($other === null) $other = $c; }
        return $orf && is_array($orf['adopted']) && $orf['adopted']['instrumentId'] === ($GLOBALS['__catOrf'] ?? '')
            && $other && $other['adopted'] === null;
    })());

    chk('assessment: a rate is never reported as a percentage of a maximum', (function () use ($ADM) {
        /* Correct words per minute has no maximum. "The mean rose 4.2% of the
           paper" is a sentence with nothing behind it, so every percent field
           comes back null and the raw means carry the result instead. */
        $iid = $GLOBALS['__catOrf'] ?? ''; if ($iid === '') return false;
        foreach (['baseline' => [12, 18, 9, 25, 14, 20], 'endline' => [30, 34, 21, 41, 28, 39]] as $phase => $scores) {
            $w = backend_dispatch('admin.assessment.window.save', ['requesterId' => $ADM, 'data' => [
                'instrumentId' => $iid, 'phase' => $phase, 'label' => ucfirst($phase)]]);
            if (empty($w['ok'])) return false;
            $res = []; foreach ($scores as $k => $s) $res[] = ['studentId' => 'AS-' . ($k + 1), 'score' => $s];
            backend_dispatch('admin.assessment.record', ['requesterId' => $ADM, 'windowId' => $w['windowId'], 'results' => $res]);
        }
        $g = backend_dispatch('admin.assessment.gains', ['requesterId' => $ADM, 'instrumentId' => $iid]);
        $row = ($g['gains'] ?? [])[0] ?? null;
        if (!$row) return false;
        $texts = implode(' | ', array_column($row['caveats'], 'text'));
        return $row['pctMeaningful'] === false && $row['scale'] === 'rate'
            && $row['gainPct'] === null && $row['baselineMeanPct'] === null && $row['pairedBaselinePct'] === null
            // …and the raw means are there, which is the only honest headline.
            && abs($row['baselineMean'] - 16.33) < 0.02 && abs($row['gain']['mean'] - 15.83) < 0.01
            && $row['improved'] === true
            && strpos($texts, 'no maximum') !== false;
    })());

    chk('assessment: on an instrument where lower is better, the fall is the improvement', (function () use ($ADM) {
        /* The SDQ total difficulties score. A report that prints "-4.5" under a
           heading called Gain has said the opposite of what happened, and the
           attrition direction inverts with it: the higher baseline is the child
           in MORE difficulty, so leavers who scored higher were the weaker ones. */
        $a = backend_dispatch('admin.assessment.adopt', ['requesterId' => $ADM, 'keys' => ['sdq.total']]);
        $iid = $a['created'][0]['instrumentId'] ?? ''; if ($iid === '') return false;
        foreach (['baseline' => [20, 22, 18, 24, 19, 21], 'endline' => [15, 18, 13, 20, 14, 16]] as $phase => $scores) {
            $w = backend_dispatch('admin.assessment.window.save', ['requesterId' => $ADM, 'data' => [
                'instrumentId' => $iid, 'phase' => $phase, 'label' => ucfirst($phase)]]);
            $res = []; foreach ($scores as $k => $s) $res[] = ['studentId' => 'AS-' . ($k + 1), 'score' => $s];
            backend_dispatch('admin.assessment.record', ['requesterId' => $ADM, 'windowId' => $w['windowId'], 'results' => $res]);
        }
        $g = backend_dispatch('admin.assessment.gains', ['requesterId' => $ADM, 'instrumentId' => $iid]);
        $row = ($g['gains'] ?? [])[0] ?? null;
        if (!$row) return false;
        $texts = implode(' | ', array_column($row['caveats'], 'text'));
        return $row['higherIsBetter'] === false
            && $row['gain']['mean'] < 0 && $row['improved'] === true
            && strpos($texts, 'LOWER score is the better result') !== false;
    })());

    chk('assessment: the direction of an instrument locks with everything else', (function () use ($ADM) {
        /* Flip higherIsBetter after results exist and last term's decline
           becomes this term's improvement, with not one recorded score
           changed. It belongs in the locked set. */
        $iid = $GLOBALS['__catOrf'] ?? ''; if ($iid === '') return false;
        $cur = db_row('SELECT * FROM assessment_instruments WHERE instrumentId = ?', [$iid]);
        $flip = backend_dispatch('admin.assessment.instrument.save', ['requesterId' => $ADM, 'instrumentId' => $iid,
            'data' => ['name' => (string)$cur['name'], 'domain' => (string)$cur['domain'], 'maxScore' => (int)$cur['maxScore'],
                       'items' => (int)$cur['items'], 'gradeFrom' => (int)$cur['gradeFrom'], 'gradeTo' => (int)$cur['gradeTo'],
                       'scale' => (string)$cur['scale'], 'higherIsBetter' => false]]);
        $rescale = backend_dispatch('admin.assessment.instrument.save', ['requesterId' => $ADM, 'instrumentId' => $iid,
            'data' => ['name' => (string)$cur['name'], 'domain' => (string)$cur['domain'], 'maxScore' => (int)$cur['maxScore'],
                       'items' => (int)$cur['items'], 'gradeFrom' => (int)$cur['gradeFrom'], 'gradeTo' => (int)$cur['gradeTo'],
                       'scale' => 'points', 'higherIsBetter' => true]]);
        $after = db_row('SELECT scale, higherIsBetter FROM assessment_instruments WHERE instrumentId = ?', [$iid]);
        return ($flip['error'] ?? '') === 'locked' && ($rescale['error'] ?? '') === 'locked'
            && (string)$after['scale'] === 'rate' && (int)$after['higherIsBetter'] === 1;
    })());

    chk('assessment: a new version keeps the citation and drops the catalogue key', (function () use ($ADM) {
        $iid = $GLOBALS['__catOrf'] ?? ''; if ($iid === '') return false;
        $rev = backend_dispatch('admin.assessment.instrument.revise', ['requesterId' => $ADM, 'instrumentId' => $iid]);
        if (empty($rev['ok'])) return false;
        $new = db_row('SELECT * FROM assessment_instruments WHERE instrumentId = ?', [$rev['instrumentId']]);
        /* The citation follows — a v2 of EGRA ORF is still EGRA ORF, and losing
           it is how a report ends up unable to say what it measured with. The
           catalogue key does not, or adoption would see the revision and hide
           the original from the catalogue screen. */
        return strpos((string)$new['citation'], 'RTI International') !== false
            && (string)$new['scale'] === 'rate' && (string)$new['catalogueKey'] === ''
            && (int)(db_row("SELECT COUNT(*) c FROM assessment_instruments WHERE catalogueKey = 'egra.orf' AND archivedAt = ''")['c'] ?? 0) === 1;
    })());

    chk('assessment: renaming an instrument does not erase what it is or where it came from', (function () use ($ADM) {
        /* Provenance arrives by ADOPTION, not by typing, so a save that only
         * carries a name — a script, an older client, a partial payload — must
         * not take the citation with it, and must not reset a level ladder to
         * a mark out of a total. An absent key leaves the value alone; an
         * empty string still clears it, so a deliberate wipe is still possible. */
        $a = backend_dispatch('admin.assessment.adopt', ['requesterId' => $ADM, 'keys' => ['aser.reading']]);
        $iid = $a['created'][0]['instrumentId'] ?? ''; if ($iid === '') return false;
        $before = db_row('SELECT * FROM assessment_instruments WHERE instrumentId = ?', [$iid]);
        backend_dispatch('admin.assessment.instrument.save', ['requesterId' => $ADM, 'instrumentId' => $iid,
            'data' => ['name' => 'ASER reading (Yoruba)', 'domain' => 'literacy', 'maxScore' => 4,
                       'items' => 4, 'gradeFrom' => 1, 'gradeTo' => 8]]);
        $after = db_row('SELECT * FROM assessment_instruments WHERE instrumentId = ?', [$iid]);
        $kept = (string)$after['citation'] === (string)$before['citation']
            && (string)$after['scale'] === 'level' && (string)$after['unit'] === (string)$before['unit']
            && (string)$after['source'] === (string)$before['source']
            && (string)$after['adaptNote'] === (string)$before['adaptNote']
            && (string)$after['name'] === 'ASER reading (Yoruba)';
        // …and an explicitly empty value still clears, so this is not a one-way door.
        backend_dispatch('admin.assessment.instrument.save', ['requesterId' => $ADM, 'instrumentId' => $iid,
            'data' => ['name' => 'ASER reading (Yoruba)', 'domain' => 'literacy', 'maxScore' => 4,
                       'items' => 4, 'gradeFrom' => 1, 'gradeTo' => 8, 'citation' => '']]);
        $wiped = db_row('SELECT citation, scale FROM assessment_instruments WHERE instrumentId = ?', [$iid]);
        return $kept && (string)$wiped['citation'] === '' && (string)$wiped['scale'] === 'level';
    })());

    chk('assessment: every op is gated on the roster capability', (function () {
        foreach (['admin.assessment.instruments', 'admin.assessment.windows', 'admin.assessment.gains',
                  'admin.assessment.record', 'admin.assessment.sheet', 'admin.assessment.instrument.save',
                  'admin.assessment.catalogue', 'admin.assessment.adopt'] as $op) {
            if ((backend_dispatch($op, ['requesterId' => ''])['ok'] ?? false) === true) return false;
        }
        return true;
    })());
})();

/* ── Data merge: one design, many people ─────────────────────────────────────
 *
 * Last in the file on purpose. These tests insert children, and every earlier
 * assertion about "the roster" would have to be re-read against a roster this
 * block had changed.
 *
 * The thing under test is not the filtering — it is WHO the merge can see. The
 * studio's only roster read used to be admin.cards.data, which exists to feed a
 * card printer and is hard-bound to "has an ID card". A child who attended all
 * twelve days and whose card was never issued is exactly the child a
 * certificate is for, and to that read they did not exist.
 */
(function () {
    $ADM = 'NGG-2025-0099';
    $co = summer_ensure_cohort();
    $cohortId = (string)$co['cohortId'];

    // Three children in one centre: one with a card, one without, one who never
    // came. Distinctive names so the search filter has something exact to find.
    $mk = function (string $id, string $first, string $last, string $token, string $photo, string $track, string $when) use ($cohortId) {
        db_insert('summer_students', [
            'studentId' => $id, 'cohortId' => $cohortId, 'token' => $token,
            'fullName' => $first . ' ' . $last, 'firstName' => $first, 'lastName' => $last,
            'centre' => 'Ijaiye', 'track' => $track, 'photoUrl' => $photo,
            'regStatus' => 'verified', 'status' => 'active',
            'enrolledAt' => $when, 'daysPresent' => 99,   // a deliberate lie; see below
        ]);
    };
    $mk('MRG-A', 'Zubaida', 'Merglet', 'SUMQR-MRGA', 'https://x/a.jpg', 'Piano', '2026-06-01T09:00:00Z');
    $mk('MRG-B', 'Yakubu', 'Merglet', '',            '',                'Piano', '2026-06-08T09:00:00Z');
    $mk('MRG-C', 'Xola',   'Mergson', 'SUMQR-MRGC', 'https://x/c.jpg', 'Coding', '2026-07-02T09:00:00Z');
    /* A real assigned card for MRG-A, with an expiry. Without one the merge row
       and the card row would agree on `expiresAt` trivially (both empty), and
       the drift test below would pass against a merge that had stopped reading
       qr_codes — which is the exact bug that hid on the volunteer card. */
    db_insert('qr_codes', ['token' => 'SUMQR-MRGA', 'cohortId' => $cohortId, 'status' => 'assigned',
        'studentId' => 'MRG-A', 'expiresAt' => '2026-10-29', 'createdAt' => now_iso(), 'assignedAt' => now_iso()]);
    // Real attendance, for two of the three.
    foreach ([['MRG-A', 5], ['MRG-B', 3]] as [$sid, $days]) {
        for ($i = 1; $i <= $days; $i++) {
            db_insert('attendance', ['cohortId' => $cohortId, 'studentId' => $sid,
                'date' => sprintf('2026-06-%02d', $i), 'checkInAt' => now_iso(), 'createdAt' => now_iso()]);
        }
    }
    $rows = fn(array $f) => backend_dispatch('admin.merge.rows', ['requesterId' => $ADM] + $f);
    $find = function (array $r, string $key) {
        foreach ($r['rows'] ?? [] as $x) if ($x['key'] === $key) return $x;
        return null;
    };

    chk('merge: a child with no ID card is invisible to the card payload and present in a merge', (function () use ($rows, $find, $ADM) {
        $cards = backend_dispatch('admin.cards.data', ['requesterId' => $ADM])['cards'] ?? [];
        $inCards = false;
        foreach ($cards as $c) if ($c['studentId'] === 'MRG-B') $inCards = true;
        $m = $rows(['q' => 'Merglet']);
        /* THE acceptance test for this whole file. Not "the filter works" —
           "the certificate run includes the child whose photo was rejected". */
        return $inCards === false && $find($m, 'MRG-B') !== null && $find($m, 'MRG-A') !== null;
    })());

    /* ── Ordering a print run ─────────────────────────────────────────────
       There was none. Rows came back in `id ASC` — the order they happened to
       be inserted — which is nothing anybody printing a stack of certificates
       wants. A guillotine operator wants them grouped by centre; somebody
       handing them out at assembly wants them alphabetical; somebody chasing
       the children who nearly qualified wants them by attendance. */
    $names = function (array $r) { return array_map(fn($x) => $x['firstName'] . ' ' . $x['surname'], $r['rows'] ?? []); };
    $ours = function (array $r) {
        return array_values(array_filter($r['rows'] ?? [], fn($x) => strpos((string)$x['key'], 'MRG-') === 0));
    };

    chk('merge: a run can be ordered by name', (function () use ($rows, $ours) {
        $r = $ours($rows(['q' => 'Merg', 'sort' => 'name', 'dir' => 'asc']));
        $got = array_map(fn($x) => $x['firstName'], $r);
        return $got === ['Xola', 'Yakubu', 'Zubaida'];
    })());
    chk('…and by surname, which is how a register is filed', (function () use ($rows, $ours) {
        $r = $ours($rows(['q' => 'Merg', 'sort' => 'surname', 'dir' => 'asc']));
        // Mergson before Merglet? No — Merglet sorts first, and the two
        // Merglets then order by first name: Yakubu, Zubaida, then Mergson.
        return array_map(fn($x) => $x['surname'] . '/' . $x['firstName'], $r)
            === ['Merglet/Yakubu', 'Merglet/Zubaida', 'Mergson/Xola'];
    })());
    chk('…and by attendance, largest first, which is the certificate question', (function () use ($rows, $ours) {
        $r = $ours($rows(['q' => 'Merg', 'sort' => 'attended', 'dir' => 'desc']));
        return array_map(fn($x) => (int)$x['attended'], $r) === [5, 3, 0];
    })());
    chk('…and by whether the piece will actually print correctly', (function () use ($rows, $ours) {
        /* The sort an operator reaches for before a run: it puts everything
           that will come out with a hole in it at one end of the list instead
           of scattered through a thousand rows. MRG-B has neither photo nor
           card, so ascending it comes first. */
        $r = $ours($rows(['q' => 'Merg', 'sort' => 'ready', 'dir' => 'asc']));
        return count($r) === 3 && $r[0]['key'] === 'MRG-B';
    })());
    chk('…the direction really reverses it', (function () use ($rows, $ours) {
        $a = array_map(fn($x) => $x['key'], $ours($rows(['q' => 'Merg', 'sort' => 'name', 'dir' => 'asc'])));
        $d = array_map(fn($x) => $x['key'], $ours($rows(['q' => 'Merg', 'sort' => 'name', 'dir' => 'desc'])));
        return $a === array_reverse($d) && count($a) === 3;
    })());
    chk('…an unknown sort key falls back to name rather than erroring', (function () use ($rows, $ours) {
        $r = $rows(['q' => 'Merg', 'sort' => 'id ASC; DROP TABLE summer_students--']);
        $got = array_map(fn($x) => $x['firstName'], $ours($r));
        return !empty($r['ok']) && $r['sort'] === 'name' && $got === ['Xola', 'Yakubu', 'Zubaida']
            // These sort SHAPED rows in PHP, so the key never reaches SQL —
            // asserted anyway, because that is the claim the allow-list makes.
            && (int)db_row('SELECT COUNT(*) c FROM summer_students')['c'] > 0;
    })());
    chk('…and the response says which order it actually used', (function () use ($rows) {
        $r = $rows(['sort' => 'centre', 'dir' => 'desc']);
        $d = $rows([]);
        return $r['sort'] === 'centre' && $r['dir'] === 'desc'
            && $d['sort'] === 'name' && $d['dir'] === 'asc';
    })());
    chk('…and the order is total, so the same request twice is the same stack', (function () use ($rows) {
        /* Every comparison falls through to the display id. Without that, two
           children with the same name in the same centre can swap places
           between two reads and the printed stack stops matching the list that
           was on screen. */
        $a = array_map(fn($x) => $x['key'], $rows(['sort' => 'centre'])['rows']);
        $b = array_map(fn($x) => $x['key'], $rows(['sort' => 'centre'])['rows']);
        return $a === $b && count($a) > 2;
    })());
    chk('merge: browsing is not capped at what one run can render', (function () use ($rows) {
        /* One number used to do both jobs, so a coordinator with a thousand
           children was told "only the first 600 are listed" — a property of the
           renderer reported as a property of the roster. Two ceilings now, and
           the run one is sent so the picker and the server cannot drift. */
        $r = $rows([]);
        return $r['limit'] === MERGE_LIST_MAX && $r['runMax'] === MERGE_RUN_MAX
            && MERGE_LIST_MAX > MERGE_RUN_MAX;
    })());

    chk('merge: attendance is counted from the register, not read from the cached column', (function () use ($rows, $find) {
        $m = $rows([]);
        $a = $find($m, 'MRG-A'); $b = $find($m, 'MRG-B'); $c = $find($m, 'MRG-C');
        /* daysPresent says 99 for all three. A certificate that prints "attended
           11 of 12 days" has to be true on the day it prints, not on the day of
           the last sweep — so this reads the register. */
        return $a && $b && $c && $a['attended'] === 5 && $b['attended'] === 3 && $c['attended'] === 0;
    })());

    chk('merge: "attended at least N" is the filter a certificate run is made of', (function () use ($rows, $find) {
        $m = $rows(['attendedMin' => 4]);
        return $find($m, 'MRG-A') !== null && $find($m, 'MRG-B') === null && $find($m, 'MRG-C') === null;
    })());

    chk('merge: card issuance, photograph, course and date are filters, not preconditions', (function () use ($rows, $find) {
        $noCard = $rows(['issued' => 'no']);
        $noPhoto = $rows(['photo' => 'no']);
        $coding = $rows(['track' => 'Coding']);
        $july = $rows(['from' => '2026-07-01']);
        return $find($noCard, 'MRG-B') !== null && $find($noCard, 'MRG-A') === null
            && $find($noPhoto, 'MRG-B') !== null && $find($noPhoto, 'MRG-A') === null
            && $find($coding, 'MRG-C') !== null && $find($coding, 'MRG-A') === null
            && $find($july, 'MRG-C') !== null && $find($july, 'MRG-A') === null;
    })());

    chk('merge: the count and the rows come from one predicate, so they cannot disagree', (function () use ($rows) {
        foreach ([[], ['track' => 'Piano'], ['attendedMin' => 4], ['q' => 'Mergson'], ['issued' => 'no']] as $f) {
            $m = $rows($f);
            if (count($m['rows']) !== $m['matched']) return false;
        }
        return true;
    })());

    chk('merge: the facets stay whole when a filter is applied', (function () use ($rows) {
        $all = $rows([]);
        $one = $rows(['track' => 'Coding']);
        /* A course picker that drops every other course the moment you choose
           one is a picker you cannot change your mind in. Facets are computed
           over the whole audience, deliberately. */
        return in_array('Piano', $one['facets']['tracks'], true)
            && $one['facets']['tracks'] === $all['facets']['tracks']
            && $one['facets']['maxAttended'] === $all['facets']['maxAttended'];
    })());

    chk('merge: a run cut short by the limit says so rather than coming back quietly short', (function () use ($rows) {
        $m = $rows(['q' => 'Merglet', 'limit' => 1]);
        // A silently truncated print run is a child without a certificate.
        return $m['matched'] === 2 && count($m['rows']) === 1 && $m['truncated'] === true;
    })());

    chk('merge: a merged row and a printed card are the same child, built by the same function', (function () use ($rows, $find, $ADM) {
        $cards = backend_dispatch('admin.cards.data', ['requesterId' => $ADM])['cards'] ?? [];
        $card = null;
        foreach ($cards as $c) if ($c['studentId'] === 'MRG-A') $card = $c;
        $m = $find($rows(['q' => 'Zubaida']), 'MRG-A');
        if (!$card || !$m) return false;
        /* The reason card_row_student exists. Two hand-written copies of this
           mapping is how the volunteer card printed no expiry date for months
           while both copies looked complete on their own. */
        foreach (['firstName', 'surname', 'displayId', 'token', 'photoUrl', 'track', 'expiresAt', 'enrolledAt'] as $k) {
            if (($card[$k] ?? null) !== ($m[$k] ?? null)) return false;
        }
        // Named explicitly, because an expiry silently absent from one of two
        // payload builders is the precise failure this guards against.
        return $card['centre'] === $m['centre'] && $m['expiresAt'] === '2026-10-29';
    })());

    chk('merge: volunteers are their own audience, with tier colour and no borrowed attendance', (function () use ($rows) {
        $m = $rows(['audience' => 'volunteers']);
        if (empty($m['ok']) || $m['audience'] !== 'volunteers') return false;
        if (!count($m['rows'])) return true;                 // no volunteers on this run
        $v = $m['rows'][0];
        /* Zero rather than a number borrowed from somewhere else: a volunteer's
           days are duty days in a different table with a different meaning, and
           a certificate that printed check-ins as "days attended" would be
           wrong in a way nobody could see. */
        return isset($v['tier']['color']) && $v['tier']['color'] !== '' && $v['attended'] === 0
            && $v['key'] === $v['displayId'];
    })());

    chk('merge: exporting a roster needs the capability that guards reading it', (function () {
        /* The studio is gated on 'people' — deciding what a credential looks
           like. A merge EXPORTS 240 children's names and faces as a file, so
           the roster capability has to hold here too. */
        $anon = backend_dispatch('admin.merge.rows', ['requesterId' => '']);
        $bogus = backend_dispatch('admin.merge.rows', ['requesterId' => 'NGG-2025-0001']);
        return ($anon['ok'] ?? false) !== true && ($bogus['ok'] ?? false) !== true;
    })());

    chk('merge: an unknown audience falls back to children rather than leaking everything', (function () use ($rows) {
        $m = $rows(['audience' => 'donors']);
        return !empty($m['ok']) && $m['audience'] === 'students';
    })());
})();

/* ── Who may operate a gate desk ─────────────────────────────────────────────
 *
 * The bug this block exists for: a gate link "did not work" whenever a
 * non-admin was already signed in on the device. It worked exactly as
 * designed — a parent, mentor, volunteer or student session is not a desk
 * session — but the page turned that recoverable refusal into a dead end with
 * a Retry button that could only fail again, instead of showing the desk
 * password box that was the way through the whole time.
 *
 * The decision lived as four lines inside two route files, which is why nobody
 * saw that the two ends disagreed about what `forbidden` meant. It is one
 * function now, and these are its cases.
 */
(function () {
    $mk = fn(string $role, string $gate = '') => array_filter(['role' => $role, 'gate' => $gate]);

    $staff = function (string $id, string $role, string $status = 'active') {
        db_exec('DELETE FROM members WHERE memberId = ?', [$id]);
        db_insert('members', ['memberId' => $id, 'fullName' => 'Desk ' . $role, 'email' => strtolower($id) . '@example.com', 'type' => 'NGG', 'role' => $role, 'status' => $status, 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
        return ['mid' => $id, 'role' => $role];
    };
    chk('gate: a staff account holding the desk’s capability opens it', gate_operator_ok($staff('NGG-DESK-A', 'admin'), 'GL-ONE')
        && gate_operator_ok($staff('NGG-DESK-S', 'super_admin'), 'GL-ONE') && gate_operator_ok($staff('NGG-DESK-C', 'summer_admin'), 'GL-ONE'));
    chk('gate: staff WITHOUT the check-in capability (an editor, an auditor) cannot register children at a desk',
        gate_operator_ok($staff('NGG-DESK-E', 'editor'), 'GL-ONE') === false && gate_operator_ok($staff('NGG-DESK-U', 'audit'), 'GL-ONE') === false);
    $sus = $staff('NGG-DESK-X', 'admin', 'suspended');
    $staff('NGG-DESK-D', 'member');
    chk('gate: the cookie’s role is not trusted — a suspended or demoted account is refused though its cookie says admin',
        gate_operator_ok($sus, 'GL-ONE') === false && gate_operator_ok(['mid' => 'NGG-DESK-D', 'role' => 'admin'], 'GL-ONE') === false
        && gate_operator_ok(['mid' => 'NGG-NOBODY', 'role' => 'admin'], 'GL-ONE') === false);
    chk('session: a live cookie dies when the account is suspended, demoted or gone', session_still_valid(['sid' => 'x', 'mid' => 'NGG-DESK-A', 'role' => 'admin']) === ''
        && session_still_valid(['sid' => 'x', 'mid' => 'NGG-DESK-X', 'role' => 'admin']) === 'suspended'
        && session_still_valid(['sid' => 'x', 'mid' => 'NGG-DESK-D', 'role' => 'admin']) === 'session_expired'
        && session_still_valid(['sid' => 'x', 'mid' => 'NGG-NOBODY', 'role' => 'member']) === 'session_expired'
        && session_still_valid(['mid' => 'kiosk:GL-ONE', 'role' => 'kiosk', 'kiosk' => true]) === '');
    chk('session: a card holder is not a member account', session_is_cardholder(['mid' => 'SUM-2026-0001', 'role' => 'student', 'stu' => 'SUM-2026-0001'])
        && session_is_cardholder(['role' => 'volunteer', 'stu' => 'VOL-1']) && !session_is_cardholder(['mid' => 'NGG-DESK-A', 'role' => 'admin', 'sid' => 'x']));

    chk('gate: a kiosk session opens the gate it was unlocked for', (function () {
        return gate_operator_ok(['role' => 'kiosk', 'gate' => 'GL-ONE'], 'GL-ONE') === true;
    })());

    chk('gate: a kiosk session for another desk is not a session for this one', (function () {
        /* Two gate links open in one browser is the normal case at a centre.
         * The kiosk claim is compared against the gate in the REQUEST, so one
         * desk's password never opens another's. */
        return gate_operator_ok(['role' => 'kiosk', 'gate' => 'GL-TWO'], 'GL-ONE') === false
            // …and a kiosk claim with nothing to compare against is not a pass.
            && gate_operator_ok(['role' => 'kiosk', 'gate' => ''], 'GL-ONE') === false
            && gate_operator_ok(['role' => 'kiosk', 'gate' => 'GL-ONE'], '') === false;
    })());

    chk('gate: an ordinary signed-in profile cannot operate a desk', (function () use ($mk) {
        /* THE REPORTED CASE. Every one of these is a real person on a real
         * shared phone: a guardian in the Circle, a mentor, a volunteer or
         * student signed in with their ID card. None of them may register a
         * child, and the refusal must stay a refusal — the fix for this bug is
         * on the page, not here. */
        foreach (['member', 'mentor', 'volunteer', 'student', 'parent', '', 'KIOSK-ish'] as $role) {
            if (gate_operator_ok($mk($role), 'GL-ONE') !== false) return false;
            /* And still refused when the session ALSO carries a matching gate
             * claim. Only session_issue_kiosk mints that claim today, so this
             * cannot happen yet — which is exactly why it is pinned. A future
             * session type that carried a gate field would otherwise walk
             * straight into a registration desk, and the role check that stops
             * it would look like dead code to whoever removed it. */
            if (gate_operator_ok(['role' => $role, 'gate' => 'GL-ONE'], 'GL-ONE') !== false) return false;
        }
        return true;
    })());

    chk('gate: the desk password is the way through, and it works over a signed-in profile', (function () {
        /* The recovery path the page now offers has to actually exist: unlocking
         * mints a kiosk session for THIS gate, and it does so without needing
         * the signed-in member to have any staff access at all — gate-unlock.php
         * never calls require_session(). */
        $gate = db_row("SELECT gateId FROM gate_links WHERE status = 'active' ORDER BY id DESC LIMIT 1");
        if (!$gate) return true;
        $gid = (string)$gate['gateId'];
        backend_dispatch('admin.gates.setpass', ['requesterId' => 'NGG-2025-0099', 'gateId' => $gid, 'password' => 'desk-pass-9x']);
        $bad = backend_dispatch('gate.unlock', ['gate' => $gid, 'password' => 'wrong']);
        $ok = backend_dispatch('gate.unlock', ['gate' => $gid, 'password' => 'desk-pass-9x']);
        if (($bad['error'] ?? '') !== 'bad_password' || empty($ok['ok'])) return false;
        // The session that unlock would hand back opens this desk and no other.
        $sess = ['role' => 'kiosk', 'gate' => (string)$ok['gate']['gateId']];
        return gate_operator_ok($sess, $gid) === true && gate_operator_ok($sess, 'GL-OTHER') === false;
    })());
})();

/* ── Volunteer attendance analysis ──────────────────────────────────────────
 *
 * A ten-day programme window with three volunteers whose behaviour is known
 * exactly, on a centre name nothing else in this file uses — so the numbers
 * asserted here are arithmetic, not "whatever the fixture happens to add up
 * to". Each test names the specific decision it is holding: the denominator,
 * the join date, the non-programme day, the un-taken roll, the privacy line.
 */
(function () {
    $today = attendance_today();
    $D = fn(int $n) => gmdate('Y-m-d', (int)strtotime($today . ' -' . $n . ' days'));
    $lab = 'Attendance Lab';
    $prevProg = setting_get('programme');

    // Every day counts, so the window is exactly ten days regardless of when
    // the suite runs — a Monday run and a Saturday run assert the same thing.
    programme_settings_save(['enabled' => true, 'startDate' => $D(9), 'endDate' => $today,
        'weekdays' => [1, 2, 3, 4, 5, 6, 7], 'holidays' => [], 'extraDays' => []], 'NGG-2025-0099');

    db_exec("DELETE FROM attendance WHERE studentId LIKE 'VOL-ATT-%'");
    db_exec("DELETE FROM volunteers WHERE volunteerId LIKE 'VOL-ATT-%'");
    $mkVol = function (string $id, string $role, int $joinedDaysAgo, string $centre = '') use ($lab, $D) {
        db_insert('volunteers', ['volunteerId' => $id, 'fullName' => 'Att ' . $id, 'email' => strtolower($id) . '@example.com',
            'role' => $role, 'centre' => $centre !== '' ? $centre : $lab, 'status' => 'active', 'safeguarding' => 'cleared',
            'visibilityConsent' => 0, 'createdAt' => $D($joinedDaysAgo) . ' 08:00:00', 'updatedAt' => now_iso()]);
    };
    /* The cohort id is on these rows because a real badge QR carries it —
     * volunteers_assign writes the active cohort onto the qr_codes row, and the
     * scanner copies it onto the attendance row. Leaving it blank here made a
     * test about the recent-check-in feed silently vacuous: the feed is scoped
     * by cohort, so no volunteer row ever reached it. */
    $attCohort = (string)summer_ensure_cohort()['cohortId'];
    $mark = function (string $id, int $daysAgo, bool $late = false) use ($D, $attCohort) {
        db_insert('attendance', ['cohortId' => $attCohort, 'studentId' => $id, 'token' => '', 'date' => $D($daysAgo),
            'checkInAt' => $D($daysAgo) . 'T08:00:00Z', 'method' => 'qr', 'byId' => 'NGG-2025-0099', 'device' => '',
            'status' => $late ? 'late' : 'present', 'lateMinutes' => $late ? 20 : 0, 'redline' => 0, 'halfDay' => 0,
            'createdAt' => now_iso()]);
    };
    $mkVol('VOL-ATT-A', 'mentor', 9);        // perfect, two of them late
    $mkVol('VOL-ATT-B', 'mentor', 9);        // half the days, none recent
    $mkVol('VOL-ATT-C', 'instructor', 4);    // joined late, perfect since
    /* The two states the four-way retention split needs, and which the old
       `never` chip could not tell apart: one placed at the start of the term who
       has never appeared, and one approved yesterday who has had no chance to.
       They belong on opposite lists — one is a phone call, one is nothing.
       In a centre of their OWN, for two reasons: it leaves every existing
       per-centre assertion above measuring exactly what it measured before, and
       it gives the retention table the case it exists for — a site where not one
       volunteer is turning up, which the site's attendance RATE cannot express
       because there is no attendance to take a rate of. */
    $volGhost = 'Ghostfield ' . substr(md5($lab), 0, 4);
    $mkVol('VOL-ATT-D', 'mentor', 9, $volGhost);   // ten open days, not one check-in
    $mkVol('VOL-ATT-E', 'mentor', 1, $volGhost);   // approved yesterday; too new to say
    for ($i = 9; $i >= 0; $i--) $mark('VOL-ATT-A', $i, $i === 3 || $i === 7);
    for ($i = 9; $i >= 5; $i--) $mark('VOL-ATT-B', $i);
    for ($i = 4; $i >= 0; $i--) $mark('VOL-ATT-C', $i);

    $labRow = function (array $a) use ($lab) {
        foreach ($a['byCentre'] as $r) if ($r['centre'] === $lab) return $r;
        return null;
    };

    $A = volunteer_attendance_analysis();
    chk('vol attendance: the window is programme days, not calendar days', $A['measurable'] === true
        && $A['days'] === 10 && $A['basis'] === 'calendar' && $A['from'] === $D(9) && $A['to'] === $today);

    chk('vol attendance: rate is days served over days the programme ran', (function () use ($A, $labRow) {
        $r = $labRow($A);
        // 10 + 5 + 5 served, out of 10 + 10 + 5 open.
        return $r && $r['people'] === 3 && $r['sessions'] === 20 && $r['expected'] === 25
            && $r['rate'] === 80 && $r['absences'] === 5;
    })());

    chk('vol attendance: late counts as present and only moves punctuality', (function () use ($A, $labRow) {
        $r = $labRow($A);
        // Two late arrivals out of twenty sessions → 90% on time, rate untouched.
        return $r && $r['late'] === 2 && $r['onTime'] === 18 && $r['onTimePct'] === 90 && $r['rate'] === 80;
    })());

    chk('vol attendance: a volunteer is not charged for days before they joined', (function () use ($A) {
        $c = $A['perVolunteer']['VOL-ATT-C'] ?? null;
        // Joined on day -4, so five open days, all served — not 5/10.
        return $c && $c['expected'] === 5 && $c['sessions'] === 5 && $c['rate'] === 100;
    })());

    chk('vol attendance: streak counts back from the last measured day', (function () use ($A) {
        $a = $A['perVolunteer']['VOL-ATT-A'] ?? null;
        $b = $A['perVolunteer']['VOL-ATT-B'] ?? null;
        // B stopped coming five days ago, so the streak is over — not "5".
        return $a && $b && $a['streak'] === 10 && $b['streak'] === 0 && $b['rate'] === 50 && $b['band'] === 'patchy';
    })());

    chk('vol attendance: the trend plots present against who was on the roster that day', (function () use ($A, $today) {
        $last = $A['trend'][count($A['trend']) - 1] ?? null;
        if (!$last || $last['date'] !== $today) return false;
        // Only A and C are in today; B is not. Eligible counts everyone active
        // programme-wide, so assert the relationship rather than the headcount.
        return $last['present'] <= $last['eligible'] && $last['present'] >= 2 && count($A['trend']) === 10;
    })());

    chk('vol attendance: reliability bands only count volunteers with enough days', (function () use ($A) {
        $by = []; foreach ($A['bands'] as $b) $by[$b['key']] = $b['count'];
        // A and C are perfect, B is patchy. Everyone here has 3+ open days.
        return ($by['every'] ?? 0) >= 2 && ($by['patchy'] ?? 0) >= 1 && $A['kpis']['measured'] >= 3;
    })());

    chk('vol attendance: a cancelled day leaves both sides of the fraction', (function () use ($D, $today, $labRow, $lab) {
        /* Day -5 becomes a holiday and VOL-ATT-B has a scan on it. The day
         * leaves the denominator; the scan has to leave the numerator with it,
         * or B reads 5 served out of 9 open and looks better for having turned
         * up on a day the programme was closed. */
        programme_settings_save(['enabled' => true, 'startDate' => $D(9), 'endDate' => $today,
            'weekdays' => [1, 2, 3, 4, 5, 6, 7], 'holidays' => [$D(5)], 'extraDays' => []], 'NGG-2025-0099');
        $H = volunteer_attendance_analysis();
        $b = $H['perVolunteer']['VOL-ATT-B'] ?? null;
        $r = $labRow($H);
        $ok = $H['days'] === 9 && $b && $b['expected'] === 9 && $b['sessions'] === 4 && $b['rate'] <= 100
            && $r && $r['rate'] <= 100;
        programme_settings_save(['enabled' => true, 'startDate' => $D(9), 'endDate' => $today,
            'weekdays' => [1, 2, 3, 4, 5, 6, 7], 'holidays' => [], 'extraDays' => []], 'NGG-2025-0099');
        return $ok;
    })());

    chk('vol attendance: the no-rota caveat is always said out loud', (function () use ($A) {
        foreach ($A['caveats'] as $c) if (strpos($c, 'no rota') !== false) return true;
        return false;
    })());

    chk('vol attendance: with no calendar set, the basis says so rather than counting every day', (function () {
        setting_set('programme', ['enabled' => false, 'startDate' => '', 'endDate' => '',
            'weekdays' => [1, 2, 3, 4, 5], 'holidays' => [], 'extraDays' => []], 'NGG-2025-0099');
        $O = volunteer_attendance_analysis();
        $said = false;
        foreach ($O['caveats'] as $c) if (strpos($c, 'calendar has not been set') !== false) $said = true;
        return $O['basis'] === 'observed' && $said;
    })());

    chk('vol attendance: a day with no roll taken yet is not an absence', (function () use ($today, $D) {
        programme_settings_save(['enabled' => true, 'startDate' => $D(9), 'endDate' => $today,
            'weekdays' => [1, 2, 3, 4, 5, 6, 7], 'holidays' => [], 'extraDays' => []], 'NGG-2025-0099');
        /* Empty today's roll entirely — the state at 7am every morning. Before
         * the trim, every volunteer's rate dipped and every streak reset. */
        $held = db_all('SELECT * FROM attendance WHERE date = ?', [$today]);
        db_exec('DELETE FROM attendance WHERE date = ?', [$today]);
        $P = volunteer_attendance_analysis();
        foreach ($held as $row) { unset($row['id']); db_insert('attendance', $row); }
        $a = $P['perVolunteer']['VOL-ATT-A'] ?? null;
        return $P['pendingDays'] === 1 && $P['days'] === 9 && $P['to'] === $D(1)
            && $a && $a['expected'] === 9 && $a['rate'] === 100 && $a['streak'] === 9;
    })());

    chk('vol attendance: the window is the term from the programme page, not a rolling 30 days', (function () use ($D, $today) {
        /* A rolling window answers a different question from the one on screen.
         * The term start is already set on the programme page; a 30-day slice
         * drifts away from it every morning, so by week seven week one had
         * silently left the numbers with nothing saying so.
         *
         * A FIFTY-day term, because a ten-day one cannot tell the two apart —
         * which is how the rolling slice survived being tested in the first
         * place. */
        programme_settings_save(['enabled' => true, 'startDate' => $D(49), 'endDate' => $today,
            'weekdays' => [1, 2, 3, 4, 5, 6, 7], 'holidays' => [], 'extraDays' => []], 'NGG-2025-0099');
        $L = volunteer_attendance_analysis();
        $long = $L['scope'] === 'term' && $L['termStart'] === $D(49) && $L['from'] === $D(49) && $L['days'] === 50;
        // Back to the ten-day term the rest of this block is written against.
        programme_settings_save(['enabled' => true, 'startDate' => $D(9), 'endDate' => $today,
            'weekdays' => [1, 2, 3, 4, 5, 6, 7], 'holidays' => [], 'extraDays' => []], 'NGG-2025-0099');
        $A = volunteer_attendance_analysis();
        return $long && $A['scope'] === 'term' && $A['termStart'] === $D(9) && $A['from'] === $D(9) && $A['days'] === 10;
    })());

    chk('vol attendance: a chosen range narrows the window and is clamped inside the term', (function () use ($D, $today, $labRow) {
        /* A range reaching back before the programme opened would count days it
         * was shut as days a volunteer missed. */
        $R = volunteer_attendance_analysis([], ['from' => $D(4), 'to' => $D(2)]);
        $wide = volunteer_attendance_analysis([], ['from' => '2000-01-01', 'to' => $today]);
        $a = $R['perVolunteer']['VOL-ATT-A'] ?? null;
        return $R['scope'] === 'range' && $R['days'] === 3 && $R['from'] === $D(4) && $R['to'] === $D(2)
            && $a && $a['expected'] === 3 && $a['sessions'] === 3
            // Clamped: a range before the term cannot invent days.
            && $wide['days'] === 10 && $wide['from'] === $D(9);
    })());

    chk('vol attendance: a reversed range is read as a range, not as nothing', (function () use ($D) {
        $R = volunteer_attendance_analysis([], ['from' => $D(2), 'to' => $D(4)]);
        return $R['days'] === 3 && $R['from'] === $D(4) && $R['to'] === $D(2);
    })());

    chk('vol attendance: the admin register names volunteers and counts each from their own start', (function () use ($lab) {
        $r = backend_dispatch('admin.volunteer.attendance', ['requesterId' => 'NGG-2025-0099']);
        if (empty($r['ok'])) return false;
        $by = []; foreach ($r['volunteers']['roster'] as $row) $by[$row['volunteerId']] = $row;
        $a = $by['VOL-ATT-A'] ?? null; $c = $by['VOL-ATT-C'] ?? null;
        // Named, unlike the public board, and each with their own denominator.
        return $a && $c && $a['fullName'] !== '' && $a['expected'] === 10 && $a['rate'] === 100
            && $c['expected'] === 5 && $c['rate'] === 100 && $c['joined'] !== ''
            // Per-person rows here are for staff, so the id IS the point.
            && isset($r['volunteers']['summary']['kpis'])
            && !isset($r['volunteers']['summary']['perVolunteer']);
    })());

    chk('one day drills down to WHO, children and volunteers in separate lists', (function () use ($D, $today) {
        /* The bar chart could say a day was thin and nothing else, and the
         * follow-up question is always which people. VOL-ATT-B stopped coming
         * five days ago, so on the most recent day they are on the not-in list
         * and VOL-ATT-A is on the in list. */
        $r = backend_dispatch('admin.summer.attendance.day', ['requesterId' => 'NGG-2025-0099', 'date' => $today]);
        if (empty($r['ok'])) return false;
        $by = []; foreach ($r['day']['volunteers'] as $v) $by[$v['id']] = $v;
        $a = $by['VOL-ATT-A'] ?? null; $b = $by['VOL-ATT-B'] ?? null;
        return $a && $b && $a['in'] === true && $a['name'] !== '' && $b['in'] === false
            && $r['day']['volunteerCounts']['in'] >= 2
            && isset($r['day']['students']) && isset($r['day']['studentCounts']['out'])
            && $r['day']['programmeDay'] === true;
    })());

    chk('a day nobody had joined yet does not list them as absent from it', (function () use ($D) {
        /* VOL-ATT-C joined on day -4. Asking about day -9 must not accuse them
         * of missing it — the same rule the rate uses, applied to the list. */
        $r = backend_dispatch('admin.summer.attendance.day', ['requesterId' => 'NGG-2025-0099', 'date' => $D(9)]);
        $ids = array_column($r['day']['volunteers'], 'id');
        $late = backend_dispatch('admin.summer.attendance.day', ['requesterId' => 'NGG-2025-0099', 'date' => $D(3)]);
        $idsLate = array_column($late['day']['volunteers'], 'id');
        return !in_array('VOL-ATT-C', $ids, true) && in_array('VOL-ATT-C', $idsLate, true)
            && in_array('VOL-ATT-A', $ids, true);
    })());

    chk('a day drill-down refuses a date rather than guessing one', (function () {
        return (backend_dispatch('admin.summer.attendance.day', ['requesterId' => 'NGG-2025-0099', 'date' => 'tuesday'])['error'] ?? '') === 'bad_date'
            && (backend_dispatch('admin.summer.attendance.day', ['requesterId' => 'NGG-2025-0099', 'date' => ''])['error'] ?? '') === 'bad_date'
            && (backend_dispatch('admin.summer.attendance.day', ['requesterId' => '', 'date' => '2026-07-06'])['ok'] ?? false) !== true;
    })());

    chk('the recent check-in feed names volunteers instead of printing their id', (function () use ($today) {
        /* A volunteer's badge QR carries the cohort id, so their scans always
         * matched this feed — and it joined summer_students only, so every one
         * rendered as a bare VOL-… with nothing saying it was a member of staff
         * rather than a child whose record had gone missing. */
        $att = backend_dispatch('admin.summer.attendance', ['requesterId' => 'NGG-2025-0099'])['attendance'];
        $seen = null;
        foreach ($att['recent'] as $row) if (strpos((string)$row['studentId'], 'VOL-ATT-') === 0) $seen = $row;
        if ($seen === null) return true;            // no volunteer scan in the last 25
        return ($seen['kind'] ?? '') === 'volunteer' && trim((string)($seen['fullName'] ?? '')) !== ''
            && (string)$seen['fullName'] !== (string)$seen['studentId'];
    })());

    chk('vol attendance: the admin register is gated on the roster capability', (function () {
        return (backend_dispatch('admin.volunteer.attendance', ['requesterId' => ''])['ok'] ?? false) !== true
            && (backend_dispatch('admin.volunteer.attendance', ['requesterId' => 'NGG-2025-0001'])['ok'] ?? false) !== true;
    })());

    /* ── Are we KEEPING our volunteers? ───────────────────────────────────────
     *
     * The register carried a per-person `stopped` flag and nothing that added it
     * up, so it could show one lapsed mentor per screen and never that a centre
     * had lost its whole faculty. A rate cannot raise the alarm — a volunteer who
     * stops leaves the numerator and the denominator together, so a site that has
     * lost two of three mentors still posts a healthy rate off the one who
     * remains; and `bands` cannot either, because it only counts volunteers with
     * three or more open days, so someone who came twice and vanished is in no
     * band at all.
     *
     * Four states rather than three, because volunteers trickle in all term where
     * a cohort of children starts together. Someone approved yesterday is not a
     * no-show, and counting them as one would make retention look worse every
     * time recruitment went well. */
    chk('vol attendance: retention tells "stopped" from "never came" from "too new"', (function () use ($volGhost) {
        $A = volunteer_attendance_analysis();
        $R = $A['retention'] ?? null;
        if (!is_array($R) || !$R) return false;
        $p = $A['perVolunteer'];
        // Each of the four states, on the person who is actually in it.
        if (($p['VOL-ATT-A']['retention'] ?? '') !== 'coming') return false;   // in every day
        if (($p['VOL-ATT-B']['retention'] ?? '') !== 'stopped') return false;  // came, then quit
        if (($p['VOL-ATT-D']['retention'] ?? '') !== 'never') return false;    // ten days, never once
        if (($p['VOL-ATT-E']['retention'] ?? '') !== 'new') return false;      // approved yesterday
        /* THE INVARIANT. The four parts are the headcount — a retention block
           whose states do not sum to the roster is one where somebody has fallen
           through a gap between two of them. */
        if ($R['coming'] + $R['stopped'] + $R['never'] + $R['new'] !== $R['people']) return false;
        // Same threshold the per-person flag uses, so one screen cannot disagree.
        return (int)$R['stoppedRun'] === VOL_ATT_STOPPED_RUN
            && $R['stopped'] >= 1 && $R['never'] >= 1 && $R['new'] >= 1 && $R['coming'] >= 2;
    })());

    chk('…and the percentage is over those who have had a chance, not the headcount', (function () {
        $R = volunteer_attendance_analysis()['retention'];
        /* Dividing by the headcount would report a programme as losing
           volunteers every time it recruited any — the new arrivals would dilute
           `coming` and inflate nothing. `settled` is returned so a reader can
           see which denominator the percentage used rather than assume. */
        if ($R['settled'] !== $R['people'] - $R['new']) return false;
        if ($R['settled'] >= $R['people']) return false;          // VOL-ATT-E is new
        $expect = round($R['stopped'] / $R['settled'] * 100, 1);
        return abs($R['stoppedPct'] - $expect) < 0.05
            && abs($R['neverPct'] - round($R['never'] / $R['settled'] * 100, 1)) < 0.05;
    })());

    chk('…and it is broken out per centre AND per role', (function () use ($volGhost, $lab) {
        $R = volunteer_attendance_analysis()['retention'];
        $cBy = []; foreach ($R['byCentre'] as $r) $cBy[$r['centre']] = $r;
        $rBy = []; foreach ($R['byRole'] as $r) $rBy[$r['role']] = $r;
        /* The case the table exists for: a site where NOBODY is coming. Its
           attendance rate cannot say so — there is no attendance to take a rate
           of — so without this it is a blank row that reads as "no data". */
        $g = $cBy[$volGhost] ?? null;
        if (!$g || $g['people'] !== 2 || $g['never'] !== 1 || $g['new'] !== 1 || $g['coming'] !== 0) return false;
        // The lab centre is the opposite: people are coming, and one has stopped.
        $l = $cBy[$lab] ?? null;
        if (!$l || $l['coming'] < 2 || $l['stopped'] < 1) return false;
        /* Per role as well, because they fail differently: a centre losing
           mentors is a supervision problem, a ROLE losing people everywhere is a
           problem with the role. */
        $m = $rBy['mentor'] ?? null;
        if (!$m || $m['stopped'] < 1 || $m['never'] < 1) return false;
        // Worst first, so the row that needs reading is the one at the top.
        $lost = array_values(array_map(fn($r) => $r['stopped'] + $r['never'], $R['byCentre']));
        for ($i = 1; $i < count($lost); $i++) if ($lost[$i] > $lost[$i - 1]) return false;
        return count($lost) >= 2;
    })());

    /* "Never came" used to mean `present === 0` whatever the date they joined,
       so every volunteer approved this week sat on the same list as one placed a
       month ago who has never appeared. Two situations needing opposite
       responses, and one of them is "do nothing". */
    chk('vol register: "never attended" no longer accuses volunteers approved this week', (function () {
        $r = backend_dispatch('admin.volunteer.attendance', ['requesterId' => 'NGG-2025-0099'])['volunteers'];
        $sc = $r['scenarios'];
        $ids = fn(string $s) => array_column(backend_dispatch('admin.volunteer.attendance',
            ['requesterId' => 'NGG-2025-0099', 'scenario' => $s])['volunteers']['roster'], 'volunteerId');
        $never = $ids('never'); $new = $ids('new');
        return in_array('VOL-ATT-D', $never, true) && !in_array('VOL-ATT-E', $never, true)
            && in_array('VOL-ATT-E', $new, true) && !in_array('VOL-ATT-D', $new, true)
            // Both counted, so the pair still adds up to what the old chip showed.
            && $sc['never'] >= 1 && ($sc['new'] ?? 0) >= 1
            && count($never) === $sc['never'] && count($new) === $sc['new'];
    })());

    /* The register offered a "Warned or worse" filter hardcoded to zero, under a
       comment saying volunteers carry no policy standing. They do: the settings
       define a volunteer redline, an absence limit and a lateness cap of four,
       policy_states_for() has taken a type since it was written, and the
       enforcement pass already walks volunteers. So a volunteer two lates from
       suspension looked exactly like one in good standing. */
    chk('vol register: policy standing is read for volunteers instead of assumed clear', (function () {
        $r = backend_dispatch('admin.volunteer.attendance', ['requesterId' => 'NGG-2025-0099'])['volunteers'];
        $row = $r['roster'][0] ?? null;
        if (!$row) return false;
        // The shape the children's register uses, so a warning means one thing.
        foreach (['state', 'absences', 'lateCap'] as $k) if (!array_key_exists($k, $row)) return false;
        // The cap comes from the policy, not from a literal in this file.
        if ((int)$row['lateCap'] !== (int)policy_for('volunteer')['latenessCap']) return false;
        /* Driven, not asserted from the seed: give a volunteer a real sanction
           and the count has to move. A test that only read the existing zero
           would pass against the hardcoded zero it is here to catch. */
        $before = (int)$r['scenarios']['flagged'];
        db_insert('sanctions', ['personId' => 'VOL-ATT-B', 'personType' => 'volunteer', 'kind' => 'warning',
            'tier' => 1, 'status' => 'active', 'reason' => 'test', 'amount' => 0,
            'startsAt' => attendance_today(), 'endsAt' => '', 'issuedBy' => 'test', 'createdAt' => now_iso()]);
        $after = backend_dispatch('admin.volunteer.attendance', ['requesterId' => 'NGG-2025-0099'])['volunteers'];
        $flaggedIds = array_column(backend_dispatch('admin.volunteer.attendance',
            ['requesterId' => 'NGG-2025-0099', 'scenario' => 'flagged'])['volunteers']['roster'], 'volunteerId');
        db_exec("DELETE FROM sanctions WHERE personId = 'VOL-ATT-B' AND reason = 'test'");
        return (int)$after['scenarios']['flagged'] === $before + 1
            && in_array('VOL-ATT-B', $flaggedIds, true)
            && count($flaggedIds) === $before + 1;
    })());

    chk('vol attendance: a day the children were scanned and no volunteer was is not everyone\'s absence', (function () use ($D, $today) {
        /* With no programme calendar the window was every distinct date in the
         * attendance table — and that table is mostly children. Three hundred
         * pupils scanned on a Tuesday made Tuesday a day every volunteer had
         * missed, whether or not one was ever expected, which is how the rates
         * on this board became indefensible. */
        $keep = setting_get('programme');
        setting_set('programme', ['enabled' => false, 'startDate' => '', 'endDate' => '',
            'weekdays' => [1, 2, 3, 4, 5], 'holidays' => [], 'extraDays' => []], 'test');
        // A day only children were on: a student check-in, no volunteer mark.
        $c = summer_ensure_cohort();
        $kidDay = $D(20);
        db_exec("DELETE FROM attendance WHERE studentId = 'ATT-KID-1'");
        db_exec("DELETE FROM summer_students WHERE studentId = 'ATT-KID-1'");
        db_insert('summer_students', ['studentId' => 'ATT-KID-1', 'cohortId' => (string)$c['cohortId'],
            'fullName' => 'Kid Only', 'handle' => 'kidonly', 'track' => 'Tech', 'centre' => 'Egbeda',
            'status' => 'active', 'regStatus' => 'verified']);
        db_insert('attendance', ['cohortId' => (string)$c['cohortId'], 'studentId' => 'ATT-KID-1', 'token' => '',
            'date' => $kidDay, 'checkInAt' => $kidDay . 'T08:00:00Z', 'method' => 'qr', 'byId' => 'NGG-2025-0099',
            'device' => '', 'status' => 'present', 'lateMinutes' => 0, 'redline' => 0, 'halfDay' => 0,
            'createdAt' => now_iso()]);
        $O = volunteer_attendance_analysis();
        db_exec("DELETE FROM attendance WHERE studentId = 'ATT-KID-1'");
        db_exec("DELETE FROM summer_students WHERE studentId = 'ATT-KID-1'");
        if (is_array($keep)) setting_set('programme', $keep, 'test');
        // The children-only day must not be in the volunteers' window at all.
        return $O['basis'] === 'observed' && $O['from'] > $kidDay
            && ($O['kpis']['expected'] ?? 0) > 0
            && ($O['kpis']['sessions'] ?? 0) <= ($O['kpis']['expected'] ?? 0);
    })());

    chk('vol attendance: the public board carries the breakdown but never a volunteerId', (function () use ($lab) {
        backend_dispatch('admin.status.pages.set', ['requesterId' => 'NGG-2025-0099',
            'data' => ['volunteer' => ['published' => true, 'centres' => []]]]);
        $r = backend_dispatch('public.volunteer.status', []);
        $s = $r['status'] ?? [];
        if (empty($s['attendance']['measurable'])) return false;
        if (isset($s['attendance']['perVolunteer'])) return false;
        /* The handle is a hash of the volunteerId. Shipping the id alongside it
         * would hand anyone the mapping the hash exists to withhold. */
        if (strpos(json_encode($s), 'VOL-ATT-A') !== false) return false;
        $mine = null;
        foreach ($s['directory'] as $v) if ($v['centre'] === $lab && ($v['window']['expected'] ?? 0) === 10 && $v['window']['rate'] === 100) $mine = $v;
        return $mine !== null && $mine['window']['streak'] === 10;
    })());

    chk('vol status: the headline reconciles with the rows underneath it', (function () {
        /* It printed "14 active volunteers" above centre rows that added up to
         * five, with nothing to account for the other nine — so a reader who
         * totted up the centres got a number that contradicted the headline and
         * no way to tell which one to trust. Three separate things hid in that
         * gap and each is now counted: no centre recorded, a centre that is no
         * longer active, and a centre this board is filtered to hide. */
        backend_dispatch('admin.status.pages.set', ['requesterId' => 'NGG-2025-0099',
            'data' => ['volunteer' => ['published' => true, 'centres' => []]]]);
        $s = backend_dispatch('public.volunteer.status', [])['status'] ?? [];
        $k = $s['kpis'] ?? [];
        foreach (['placedVolunteers', 'unplacedVolunteers', 'offBoardVolunteers', 'hiddenVolunteers'] as $f) {
            if (!array_key_exists($f, $k)) return false;
        }
        $sum = $k['placedVolunteers'] + $k['unplacedVolunteers'] + $k['offBoardVolunteers'] + $k['hiddenVolunteers'];
        if ($sum !== (int)$k['activeVolunteers']) return false;
        // And the centre rows total the ones the board is actually showing.
        $rows = 0;
        foreach ($s['byCentre'] as $c) $rows += (int)$c['attendance']['active'];
        return $rows === $k['placedVolunteers'] + $k['hiddenVolunteers'];
    })());

    chk('vol status: a centre\'s attendance is out of its HEADCOUNT, not its filled slots', (function () {
        /* `active` was the role-need FULFILMENT count. present counts PEOPLE and
         * filled counts SLOTS, so the two were never the same question — a
         * centre with three volunteers against two defined slots read "3 of 2 in
         * today". A volunteer whose role is not one of the three the fulfilment
         * board tracks fills no slot at all, which is the case that separates
         * them: they are on the roster and they can walk in. */
        db_exec("DELETE FROM volunteers WHERE volunteerId = 'VOL-COACH-1'");
        $before = backend_dispatch('public.volunteer.status', [])['status'] ?? [];
        $pick = function ($s) { foreach ($s['byCentre'] as $c) if ((string)$c['name'] === 'Egbeda') return $c; return null; };
        $b = $pick($before);
        if (!$b) return true;
        db_insert('volunteers', ['volunteerId' => 'VOL-COACH-1', 'fullName' => 'Coach Kay',
            'email' => 'coach@example.com', 'role' => 'coach', 'centre' => 'Egbeda', 'status' => 'active',
            'safeguarding' => 'cleared', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
        $after = $pick(backend_dispatch('public.volunteer.status', [])['status'] ?? []);
        db_exec("DELETE FROM volunteers WHERE volunteerId = 'VOL-COACH-1'");
        if (!$after) return false;
        $ok = ((int)$after['attendance']['active'] === (int)$b['attendance']['active'] + 1)
            // …and the fulfilment figure is unchanged, because no slot was filled.
            && ((int)$after['attendance']['filled'] === (int)$b['attendance']['filled']);
        // Nobody can be present at a centre more often than it has people.
        $s = backend_dispatch('public.volunteer.status', [])['status'] ?? [];
        foreach ($s['byCentre'] as $c) if ($c['attendance']['present'] > $c['attendance']['active']) return false;
        return $ok;
    })());

    chk('vol status: a role recorded with a capital letter still fills its slot', (function () {
        /* VOL_ROLES is lower-case. A row saying "Mentor" — an import, an admin
         * edit — landed in a bucket the board never reads: no slot filled, no
         * role total, and still counted under "active volunteers". */
        $idx = volunteer_filled_index();
        db_exec("DELETE FROM volunteers WHERE volunteerId = 'VOL-CASE-1'");
        db_insert('volunteers', ['volunteerId' => 'VOL-CASE-1', 'fullName' => 'Case Test',
            'email' => 'case@example.com', 'role' => 'Mentor', 'centre' => 'Egbeda', 'status' => 'active',
            'safeguarding' => 'cleared', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
        $after = volunteer_filled_index();
        db_exec("DELETE FROM volunteers WHERE volunteerId = 'VOL-CASE-1'");
        $was = $idx['role']['Egbeda|mentor'] ?? 0;
        return (($after['role']['Egbeda|mentor'] ?? 0) === $was + 1)
            && !isset($after['role']['Egbeda|Mentor']);
    })());

    // Leave the calendar as this suite found it.
    if (is_array($prevProg)) setting_set('programme', $prevProg, 'NGG-2025-0099');
    else db_exec("DELETE FROM settings WHERE settingKey = 'programme'");
})();

/* ── Member obligations: membership fee, monthly dues, training fee ───────────
 *
 * A LEDGER, not a payment processor. What these guard, in order of how badly
 * each would hurt if it broke:
 *
 *   1. Charging a family twice for the same month. The accrual runs from a cron
 *      AND from an admin button, so it WILL be run twice; the unique index on
 *      (memberId, kind, periodKey) is the only thing standing between that and a
 *      duplicate charge nobody notices until a guardian complains.
 *   2. The training fee's write-down. It is charged but a member who completes
 *      their MOU never pays it — get that wrong in either direction and the
 *      programme either bills somebody who has served their time, or forgives an
 *      obligation somebody walked away from.
 *   3. The cap. An account that accrues past what anyone could pay stops being a
 *      fact about the family and becomes one about the software.
 *   4. Money must not reach a child's public record, and must not gate a gate.
 */
(function () use ($SUR) {
    $ADM = 'NGG-2025-0099';
    $keepFees = setting_get('fees');
    $mk = function (string $id, string $joined) {
        db_exec('DELETE FROM member_ledger WHERE memberId = ?', [$id]);
        db_exec('DELETE FROM members WHERE memberId = ?', [$id]);
        db_insert('members', ['memberId' => $id, 'fullName' => 'Fee ' . $id, 'email' => strtolower($id) . '@example.com',
            'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'centre' => 'Egbeda',
            'joinDate' => $joined, 'parentName' => 'Mrs ' . $id, 'parentPhone' => '08031119001',
            'parentEmail' => 'g-' . strtolower($id) . '@example.com',
            'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    };
    // Joined on the 1st, so the first month is a full one (a mid-month start is pro-rated; tested on its own below).
    $D = fn(int $monthsAgo) => gmdate('Y-m-01', strtotime(gmdate('Y-m-15') . ' -' . $monthsAgo . ' months'));
    // Joined 20 months ago: 18 months training done, 2 months into service.
    $mk('NGG-FEE-A', $D(20));
    // Joined this month: nothing has accrued but the joining fee.
    $mk('NGG-FEE-B', gmdate('Y-m-d'));

    $set = fn(array $o) => backend_dispatch('admin.fees.settings.set',
        ['requesterId' => $ADM, 'data' => array_merge(['enabled' => true, 'membershipFee' => 5000,
            'monthlyDues' => 1000, 'trainingFee' => 75000, 'trainingMonths' => 18, 'serviceMonths' => 18,
            'balanceCap' => 0, 'remindEnabled' => false], $o)]);
    $set([]);

    chk('fees: every amount is admin-defined, clamped, and 75k is only a default', (function () use ($ADM) {
        $d = backend_dispatch('admin.fees.settings.get', ['requesterId' => $ADM]);
        if (($d['defaults']['trainingFee'] ?? 0) !== 75000) return false;
        // A slipped keystroke cannot post a 900-million-naira charge.
        $r = backend_dispatch('admin.fees.settings.set', ['requesterId' => $ADM,
            'data' => ['monthlyDues' => 999999999999, 'trainingFee' => -5]]);
        $f = $r['fees'];
        return $f['monthlyDues'] === FEES_AMOUNT_MAX && $f['trainingFee'] === 0;
    })());

    $set([]);   // back to the working figures

    chk('fees: three years is 18 months training then 18 months service', (function () use ($D) {
        $a = db_row("SELECT * FROM members WHERE memberId = 'NGG-FEE-A'");
        $t = fees_tenure($a);
        // 20 months in: training done, two months of service served.
        return $t['phase'] === 'service' && $t['months'] === 20
            && $t['trainingMonths'] === 18 && $t['serviceMonths'] === 18 && $t['servedMonths'] === 2
            && $t['complete'] === false;
    })());

    chk('fees: accrual charges membership yearly and the dues once per month', (function () use ($ADM) {
        $a = db_row("SELECT * FROM members WHERE memberId = 'NGG-FEE-A'");
        fees_accrue_member($a);
        $acc = backend_dispatch('admin.fees.member', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A'])['account'];
        $k = $acc['balance']['byKind'];
        /* 20 months elapsed → 21 monthly dues keys from the join month to this
           one, and TWO membership years: the one they joined on and the
           anniversary they have passed. */
        return ($k['membership'] ?? 0) === 10000 && ($k['dues'] ?? 0) === 21000;
    })());

    /* Membership renews on the ANNIVERSARY, not on 1 January. A member who
       joined in November has paid for a year in November; billing them again
       six weeks later because the calendar rolled is how a family concludes the
       programme cannot count. */
    chk('fees: the membership year runs from the join date, not the calendar', (function () {
        $p = fees_membership_periods('2024-11-20', '2026-01-05', 12);
        return count($p) === 2 && $p[0]['due'] === '2024-11-20' && $p[1]['due'] === '2025-11-20'
            && $p[0]['key'] === 'y1' && $p[1]['key'] === 'y2';
    })());
    chk('fees: …a cycle of 0 months is the old one-off charge, still reachable',
        fees_membership_periods('2024-11-20', '2026-01-05', 0) === [['key' => 'once', 'due' => '2024-11-20']]);
    chk('fees: …and an admin cannot turn the cycle into a monthly charge by typing 0.5',
        (function () use ($ADM) {
            $f = backend_dispatch('admin.fees.settings.set', ['requesterId' => $ADM, 'data' => ['membershipEveryMonths' => 0.5]])['fees'];
            $back = backend_dispatch('admin.fees.settings.set', ['requesterId' => $ADM, 'data' => ['membershipEveryMonths' => 12]])['fees'];
            return (int)$f['membershipEveryMonths'] === 0 && (int)$back['membershipEveryMonths'] === 12;
        })());

    /* THE ONE THAT MATTERS MOST. Accrual runs from a cron and from a button, so
       it will be run twice; a family charged twice for August finds out by being
       chased for money they do not owe. */
    chk('fees: running accrual again does NOT charge the same month twice', (function () use ($ADM) {
        $a = db_row("SELECT * FROM members WHERE memberId = 'NGG-FEE-A'");
        $before = backend_dispatch('admin.fees.member', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A'])['account']['balance'];
        fees_accrue_member($a); fees_accrue_member($a);
        backend_dispatch('admin.fees.accrue', ['requesterId' => $ADM]);
        $after = backend_dispatch('admin.fees.member', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A'])['account']['balance'];
        return (int)$after['charged'] === (int)$before['charged']
            && (int)$after['outstanding'] === (int)$before['outstanding'];
    })());

    /* "Deducts as they come." Two months of an eighteen-month service half are
       served, so a ninth of the training fee has been earned off — not none of
       it, and not all of it. */
    chk('fees: the training fee is written down as service is served, not in one step', (function () use ($ADM) {
        $acc = backend_dispatch('admin.fees.member', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A'])['account'];
        $b = $acc['balance'];
        if ((int)$b['trainingCharged'] <= 0) return false;
        $expect = (int)floor($b['trainingCharged'] * (2 / 18));
        if ((int)$b['trainingEarned'] !== $expect) return false;
        // Earned is NOT the same as written off — nothing has been forgiven yet.
        if ((int)$b['trainingWrittenOff'] !== 0) return false;
        /* `payable` is REAL money only, and the training fee is not real money —
           it is the cost of a free place, carried so the programme can say what
           it spends. So the two figures differ by the whole of the training that
           has not been written off, not merely by the part earned. This is the
           invariant that keeps a notional cost out of every screen and every
           email that asks a family to pay. */
        if ((int)$b['payable'] !== (int)$b['outstanding'] - ((int)$b['trainingCharged'] - (int)$b['trainingWrittenOff'])) return false;
        // And the notional side is reported under its own name.
        return (int)$b['programmeCost'] === (int)$b['trainingCharged']
            && (int)$b['programmeCovered'] === (int)$b['trainingEarned'] + (int)$b['trainingWrittenOff'];
    })());

    chk('fees: a member with no service yet has earned none of the training fee off', (function () use ($ADM) {
        $b = db_row("SELECT * FROM members WHERE memberId = 'NGG-FEE-B'");
        fees_accrue_member($b);
        $bal = fees_balance(db_row("SELECT * FROM members WHERE memberId = 'NGG-FEE-B'"));
        return $bal['tenure']['phase'] === 'training' && (int)$bal['trainingEarned'] === 0
            && (int)$bal['payable'] === (int)$bal['outstanding'];
    })());

    /* Accomplishing the MOU writes off whatever the training fee has left, and
       records that it happened — the two are different statements and both are
       needed. */
    chk('fees: the MOU writes the training fee off completely, and is recorded as a fact', (function () use ($ADM) {
        $r = backend_dispatch('admin.fees.mou', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A']);
        if (empty($r['ok'])) return false;
        $m = db_row("SELECT mouAt, mouBy FROM members WHERE memberId = 'NGG-FEE-A'");
        if (trim((string)$m['mouAt']) === '' || trim((string)$m['mouBy']) === '') return false;
        $b = $r['balance'];
        // Nothing of the training fee is left owing.
        if ((int)$b['trainingWrittenOff'] !== (int)$b['trainingCharged']) return false;
        // …and it cannot be done twice, which would write off a second time.
        $again = backend_dispatch('admin.fees.mou', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A']);
        return ($again['error'] ?? '') === 'already_done' && (int)$r['writtenOff'] > 0;
    })());

    /* ── The training fee charged per meeting day ─────────────────────────
     *
     * "It should add the money each day they come" — and the days they come are
     * the admin's calendar, not the attendance register: the weekdays the
     * programme meets, its holidays, its extra days, inside each session's own
     * start and end dates. Charging off attendance instead would make missing a
     * day cheaper than turning up, which is not what a training fee is for.
     *
     * The switch is per-deployment and non-destructive, so the three properties
     * that matter are: it counts the calendar correctly, it does not re-bill a
     * session already charged as a whole, and it charges nothing at all when
     * there is no calendar to count. */
    (function () use ($ADM) {
        $keep = fees_settings();
        $keepCal = setting_get('memberProgramme');
        db_exec("DELETE FROM members WHERE memberId = 'NGG-FEE-DAY'");
        db_exec("DELETE FROM member_ledger WHERE memberId = 'NGG-FEE-DAY'");
        db_exec("DELETE FROM sessions WHERE sessionId LIKE 'S-DAY-%'");

        // Two Saturdays a week apart, one of them declared a holiday.
        setting_set('memberProgramme', ['enabled' => true, 'startDate' => '2026-01-01', 'endDate' => '2026-12-31',
            'weekdays' => [6], 'holidays' => ['2026-01-10'], 'extraDays' => ['2026-01-14']], 'test');
        db_insert('sessions', ['sessionId' => 'S-DAY-1', 'name' => 'Term one',
            'startDate' => '2026-01-01', 'endDate' => '2026-01-20', 'isActive' => 0]);
        db_insert('members', ['memberId' => 'NGG-FEE-DAY', 'fullName' => 'Day Rate', 'type' => 'NGG',
            'status' => 'active', 'joinDate' => '2026-01-01', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);

        backend_dispatch('admin.fees.settings.set', ['requesterId' => $ADM, 'data' => [
            'enabled' => true, 'membershipFee' => 0, 'monthlyDues' => 0, 'trainingFee' => 500,
            'trainingBasis' => 'day', 'balanceCap' => 0, 'remindEnabled' => false]]);

        $m = db_row("SELECT * FROM members WHERE memberId = 'NGG-FEE-DAY'");
        $r = fees_accrue_member($m, null, '2026-01-31');
        /* Scoped to this fixture's own session: the suite's database carries
           sessions from other blocks, and a member enrolled through them is
           correctly charged for those too. */
        $days = db_all("SELECT periodKey FROM member_ledger WHERE memberId = 'NGG-FEE-DAY' AND kind = 'training' AND periodKey LIKE 'S-DAY-1:%' ORDER BY periodKey");
        $keys = array_map(fn($x) => (string)$x['periodKey'], $days);

        /* Jan 2026: Saturdays fall on the 3rd, 10th, 17th and 24th. The 10th is
           a holiday, the 24th is past the session's end, and the 14th is an
           extra day the admin added. */
        chk('fees (day rate): one charge per meeting day inside the session window',
            $keys === ['S-DAY-1:2026-01-03', 'S-DAY-1:2026-01-14', 'S-DAY-1:2026-01-17']);
        chk('fees (day rate): …a declared holiday is not charged for',
            !in_array('S-DAY-1:2026-01-10', $keys, true));
        chk('fees (day rate): …nor a day past the session end date',
            !in_array('S-DAY-1:2026-01-24', $keys, true));
        chk('fees (day rate): the amount is the day rate, once each',
            count($keys) === 3
            && (int)db_row("SELECT COALESCE(SUM(amount),0) t FROM member_ledger WHERE memberId = 'NGG-FEE-DAY' AND kind = 'training' AND periodKey LIKE 'S-DAY-1:%'")['t'] === 1500);

        chk('fees (day rate): running it again charges nothing more',
            (function () use ($m) {
                $n = fn() => (int)db_row("SELECT COUNT(*) c FROM member_ledger WHERE memberId = 'NGG-FEE-DAY' AND kind = 'training'")['c'];
                $before = $n();
                fees_accrue_member($m, null, '2026-01-31');
                return $n() === $before;
            })());

        /* Switching the basis mid-programme must not re-bill a family for a
           session they were already invoiced for as a whole. */
        chk('fees (day rate): a session already charged as a whole is not charged again by the day',
            (function () use ($ADM, $m) {
                db_insert('sessions', ['sessionId' => 'S-DAY-2', 'name' => 'Term two',
                    'startDate' => '2026-02-01', 'endDate' => '2026-02-28', 'isActive' => 0]);
                fees_post('NGG-FEE-DAY', 'training', 75000, ['periodKey' => 'S-DAY-2', 'by' => 'test']);
                fees_accrue_member($m, null, '2026-02-28');
                $n = (int)db_row("SELECT COUNT(*) c FROM member_ledger WHERE memberId = 'NGG-FEE-DAY' AND kind = 'training' AND periodKey LIKE 'S-DAY-2%'")['c'];
                return $n === 1;
            })());

        chk('fees (day rate): with no meeting calendar set, nothing is charged and the run says why',
            (function () use ($m) {
                setting_set('memberProgramme', ['enabled' => false, 'startDate' => '', 'endDate' => '',
                    'weekdays' => [6], 'holidays' => [], 'extraDays' => []], 'test');
                db_exec("DELETE FROM member_ledger WHERE memberId = 'NGG-FEE-DAY'");
                $r = fees_accrue_member($m, null, '2026-01-31');
                return $r['training'] === 0 && $r['skipped'] === 'no_calendar';
            })());

        /* The week rate: one charge per Monday–Sunday week the programme meets
           in. Jan 3 is in the week of Dec 29; the 14th and 17th share the week
           of Jan 12 — two weeks, not three days. */
        setting_set('memberProgramme', ['enabled' => true, 'startDate' => '2026-01-01', 'endDate' => '2026-12-31',
            'weekdays' => [6], 'holidays' => ['2026-01-10'], 'extraDays' => ['2026-01-14']], 'test');
        db_exec("DELETE FROM member_ledger WHERE memberId = 'NGG-FEE-DAY'");
        db_exec("DELETE FROM sessions WHERE sessionId = 'S-DAY-2'");
        backend_dispatch('admin.fees.settings.set', ['requesterId' => $ADM, 'data' => ['trainingBasis' => 'week', 'trainingFee' => 2000]]);
        chk('fees (week rate): the basis can be set to weekly', fees_settings()['trainingBasis'] === 'week');
        fees_post('NGG-FEE-DAY', 'training', 500, ['periodKey' => 'S-DAY-1:2026-01-03', 'by' => 'test']);   // charged by the day before the switch
        fees_accrue_member($m, null, '2026-01-31');
        $wk = array_map(fn($x) => (string)$x['periodKey'], db_all("SELECT periodKey FROM member_ledger WHERE memberId = 'NGG-FEE-DAY' AND kind = 'training' AND periodKey LIKE 'S-DAY-1:W%' ORDER BY periodKey"));
        chk('fees (week rate): one charge per week the programme meets, at the week rate', $wk === ['S-DAY-1:W2026-01-12']
            && (int)db_row("SELECT amount FROM member_ledger WHERE memberId = 'NGG-FEE-DAY' AND periodKey = 'S-DAY-1:W2026-01-12'")['amount'] === 2000);
        chk('fees (week rate): a week already charged by the day is not charged again', !in_array('S-DAY-1:W2025-12-29', $wk, true));
        $before = (int)db_row("SELECT COUNT(*) c FROM member_ledger WHERE memberId = 'NGG-FEE-DAY'")['c'];
        fees_accrue_member($m, null, '2026-01-31');
        chk('fees (week rate): running it again charges nothing more', (int)db_row("SELECT COUNT(*) c FROM member_ledger WHERE memberId = 'NGG-FEE-DAY'")['c'] === $before);

        db_exec("DELETE FROM members WHERE memberId = 'NGG-FEE-DAY'");
        db_exec("DELETE FROM member_ledger WHERE memberId = 'NGG-FEE-DAY'");
        db_exec("DELETE FROM sessions WHERE sessionId LIKE 'S-DAY-%'");
        if ($keepCal === null) db_exec("DELETE FROM settings WHERE settingKey = 'memberProgramme'");
        else setting_set('memberProgramme', $keepCal, 'test');
        setting_set('fees', $keep, 'test');
    })();

    chk('fees: what is left owing after the MOU is the dues, not the training fee', (function () use ($ADM) {
        $acc = backend_dispatch('admin.fees.member', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A'])['account'];
        $b = $acc['balance'];
        // membership 2 × 5000 + dues 21000 = 31000. The 75k training is gone.
        return (int)$b['payable'] === 31000 && (int)$b['outstanding'] === 31000;
    })());

    chk('fees: a recorded payment reduces what is payable, and is not a gateway', (function () use ($ADM) {
        $r = backend_dispatch('admin.fees.payment', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A',
            'amount' => 6000, 'method' => 'transfer', 'reference' => 'TRF-1']);
        if (empty($r['ok'])) return false;
        $b = $r['balance'];
        if ((int)$b['payable'] !== 25000) return false;
        // Two payments in one month are two events, not a duplicate.
        backend_dispatch('admin.fees.payment', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A', 'amount' => 1000, 'method' => 'cash']);
        $after = fees_balance(db_row("SELECT * FROM members WHERE memberId = 'NGG-FEE-A'"));
        return (int)$after['payable'] === 24000
            && (backend_dispatch('admin.fees.payment', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A', 'amount' => 0])['error'] ?? '') === 'bad_amount';
    })());

    chk('fees: a correction VOIDS an entry with a reason and keeps it on the account', (function () use ($ADM) {
        $acc = backend_dispatch('admin.fees.member', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A'])['account'];
        $pay = null;
        foreach ($acc['entries'] as $e) if ($e['kind'] === 'payment' && !$e['void']) { $pay = $e; break; }
        if (!$pay) return false;
        // A void with no reason is refused — "why is this different from last
        // month" is the question an account has to be able to answer.
        if ((backend_dispatch('admin.fees.void', ['requesterId' => $ADM, 'entryId' => $pay['entryId'], 'reason' => ''])['error'] ?? '') !== 'reason_required') return false;
        $r = backend_dispatch('admin.fees.void', ['requesterId' => $ADM, 'entryId' => $pay['entryId'], 'reason' => 'entered twice']);
        if (empty($r['ok'])) return false;
        $after = backend_dispatch('admin.fees.member', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A'])['account'];
        $still = null;
        foreach ($after['entries'] as $e) if ($e['entryId'] === $pay['entryId']) $still = $e;
        // Visible, flagged, with its reason — and out of the balance.
        return $still && $still['void'] === true && $still['voidReason'] === 'entered twice'
            && (int)$after['balance']['payable'] === (int)$acc['balance']['payable'] + (int)$pay['amount']
            && (backend_dispatch('admin.fees.void', ['requesterId' => $ADM, 'entryId' => $pay['entryId'], 'reason' => 'again'])['error'] ?? '') === 'already_void';
    })());

    /* The cap is enforced, not merely displayed. An account that keeps charging
       past what anybody could pay drives the family out of the programme. */
    chk('fees: a capped account stops accruing instead of growing without limit', (function () use ($ADM, $set) {
        $set(['balanceCap' => 1000]);
        $m = db_row("SELECT * FROM members WHERE memberId = 'NGG-FEE-B'");
        $before = fees_balance($m);
        $r = fees_accrue_member($m);
        $after = fees_balance(db_row("SELECT * FROM members WHERE memberId = 'NGG-FEE-B'"));
        $ok = $r['skipped'] === 'at_cap' && (int)$after['charged'] === (int)$before['charged']
            && !empty($after['atCap']);
        $set(['balanceCap' => 0]);
        return $ok;
    })());

    /* "Constant reminder" as literally built is how a programme gets its sender
       blocked and its guardians to stop reading anything it sends. */
    chk('fees: the reminder cadence has a floor and a per-family off-switch', (function () use ($ADM, $set) {
        $r = backend_dispatch('admin.fees.settings.set', ['requesterId' => $ADM,
            'data' => ['enabled' => true, 'remindEnabled' => true, 'remindEveryDays' => 1]]);
        if ((int)$r['fees']['remindEveryDays'] !== FEES_REMIND_MIN_DAYS) return false;
        $off = backend_dispatch('admin.fees.remindOff', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A', 'off' => true]);
        if (empty($off['ok'])) return false;
        $acc = backend_dispatch('admin.fees.member', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A'])['account'];
        // One family off does not disable reminders for the programme.
        $stillOn = !empty(fees_settings()['remindEnabled']);
        backend_dispatch('admin.fees.remindOff', ['requesterId' => $ADM, 'memberId' => 'NGG-FEE-A', 'off' => false]);
        $set([]);
        return $acc['remindOff'] === true && $stillOn;
    })());

    /* Sorted by what is PAYABLE, not by what is charged: a member whose balance
       is large only because their training fee has not been written off yet is
       not the person to telephone. */
    chk('fees: the arrears list ranks by what is payable, not by what is charged', (function () use ($ADM) {
        $r = backend_dispatch('admin.fees.arrears', ['requesterId' => $ADM]);
        if (empty($r['ok'])) return false;
        $by = []; foreach ($r['arrears'] as $a) $by[$a['memberId']] = $a;
        $b = $by['NGG-FEE-B'] ?? null;
        if (!$b) return false;
        // B is mid-training, so their training fee is fully payable; A has had
        // theirs written off. Ordering is by payable, descending.
        $vals = array_map(fn($a) => (int)$a['payable'], $r['arrears']);
        for ($i = 1; $i < count($vals); $i++) if ($vals[$i] > $vals[$i - 1]) return false;
        return $b['payable'] > 0 && array_key_exists('guardianPhone', $b) && $r['totalPayable'] > 0;
    })());

    /* MONEY MUST NOT REACH THE CHILD'S PUBLIC RECORD, and must not gate a gate.
       A child turned away at a door over their guardian's arrears is the failure
       this is designed against. */
    chk('fees: no balance reaches the public boards, and no fee gates a check-in', (function () {
        $j = json_encode(backend_dispatch('public.status', [])) . json_encode(backend_dispatch('public.volunteer.status', []));
        foreach (['payable', 'outstanding', 'monthlyDues', 'trainingFee', 'arrears', 'mouAt'] as $k) {
            if (strpos($j, $k) !== false) return false;
        }
        /* Structural, not a promise: the gate and scanner code must not read the
           ledger at all. Grepped, because a future edit that starts reading it
           would pass every behavioural test above. */
        foreach (['api/_lib/domain/summer.php', 'api/public/gate.php', 'api/public/checkin.php'] as $f) {
            $src = (string)@file_get_contents(dirname(dirname(__DIR__)) . '/' . $f);
            if ($src !== '' && (strpos($src, 'member_ledger') !== false || strpos($src, 'fees_balance') !== false)) return false;
        }
        return true;
    })());

    chk('fees: every op is gated, and a content-only admin cannot see an account', (function () {
        /* Its own editor rather than one of the shared fixtures: the suite
           promotes NGG-2025-0002 to `admin` partway through, so a test written
           against it would assert on whatever the preceding tests had left —
           and would have read a real gate as a leak. */
        $ed = 'NGG-FEE-ED';
        db_exec('DELETE FROM members WHERE memberId = ?', [$ed]);
        db_insert('members', ['memberId' => $ed, 'fullName' => 'Fees Editor', 'email' => 'feesed@example.com',
            'type' => 'NGG', 'status' => 'active', 'role' => 'editor', 'centre' => 'Egbeda',
            'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
        $caps = member_effective_caps(db_row('SELECT * FROM members WHERE memberId = ?', [$ed]));
        if (in_array('people', $caps, true)) return false;      // the premise, asserted
        $bad = true;
        foreach (['admin.fees.settings.get', 'admin.fees.member', 'admin.fees.arrears', 'admin.fees.accrue'] as $op) {
            if ((backend_dispatch($op, ['requesterId' => ''])['ok'] ?? false) === true) $bad = false;
            if ((backend_dispatch($op, ['requesterId' => $ed])['ok'] ?? false) === true) $bad = false;
        }
        if ((backend_dispatch('admin.fees.payment', ['requesterId' => $ed,
            'memberId' => 'NGG-FEE-A', 'amount' => 100])['ok'] ?? false) === true) $bad = false;
        db_exec('DELETE FROM members WHERE memberId = ?', [$ed]);
        return $bad;
    })());

    /* The client's fees block must not have been spliced into the middle of
       another object. Caught exactly this while wiring it: an extra brace closed
       `summer` early and silently moved qrList/checkin/attendance onto `fees` —
       the bundle still PARSED, so nothing flagged it. */
    chk('fees: wiring the client did not move another namespace onto the fees object', (function () {
        $src = (string)@file_get_contents(dirname(dirname(__DIR__)) . '/api-client.js');
        if ($src === '') return false;
        if (!preg_match('/\n      fees: \{(.*?)\n      \},/s', $src, $m)) return false;
        // Every route inside `fees` is a fees route, and nothing else is.
        if (preg_match('#/admin/(?!fees\.php)[a-z-]+\.php#', $m[1])) return false;
        // …and summer kept the methods that belong to it.
        return preg_match('/\n      summer: \{(.*?)\n      \},/s', $src, $s2) === 1
            && strpos($s2[1], "view: 'qr'") !== false
            && strpos($s2[1], "action: 'checkin'") !== false;
    })());

    /* ── Uprating: the amounts keep their real value, balances do not move ────
     *
     * Naira inflation erodes a fixed figure fast — ₦75,000 set today is worth
     * noticeably less in two years, and a programme that never revisits its
     * amounts is quietly taking a pay cut. So the AMOUNTS can be raised on a
     * schedule.
     *
     * The load-bearing property, and the first test below: a charge ALREADY
     * POSTED does not move. A family quoted ₦1,000 for August owes ₦1,000 for
     * August however many times the price is revised afterwards. Reaching back
     * into a balance somebody has already been told is the one thing that would
     * make this ledger untrustworthy, and it is the mistake a naive
     * implementation makes — recompute from the settings and every historic
     * charge silently reprices.
     */
    /* `uprateLastAt` is deliberately NOT accepted from the settings form — a
       field an admin can clear is a field that can raise prices twice in a year,
       and there is a test below pinning that. So a test that needs a clean slate
       writes the stamp straight to the setting instead of pretending the form
       can do it. Everything else still goes through the ordinary save. */
    $setU = function (array $o) use ($set) {
        $stamp = array_key_exists('uprateLastAt', $o) ? (string)$o['uprateLastAt'] : null;
        unset($o['uprateLastAt']);
        $set($o);
        if ($stamp !== null) {
            $cfg = fees_settings();
            $cfg['uprateLastAt'] = $stamp;
            setting_set('fees', $cfg, 'test');
        }
        return fees_settings();
    };

    chk('fees uprate: raising the amounts does NOT reprice a charge already posted', (function () use ($ADM, $setU) {
        $setU(['monthlyDues' => 1000, 'trainingFee' => 75000, 'upratePct' => 20,
               'uprateEveryMonths' => 12, 'uprateLastAt' => '']);
        $id = 'NGG-FEE-UP';
        db_exec('DELETE FROM member_ledger WHERE memberId = ?', [$id]);
        db_exec('DELETE FROM members WHERE memberId = ?', [$id]);
        db_insert('members', ['memberId' => $id, 'fullName' => 'Uprate Test', 'email' => 'up@example.com',
            'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'centre' => 'Egbeda',
            'joinDate' => gmdate('Y-m-d', strtotime('-2 months')), 'parentEmail' => 'upg@example.com',
            'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
        // Charge at today's prices.
        fees_accrue_member(db_row('SELECT * FROM members WHERE memberId = ?', [$id]));
        $before = fees_balance(db_row('SELECT * FROM members WHERE memberId = ?', [$id]));
        $duesBefore = (int)($before['byKind']['dues'] ?? 0);
        if ($duesBefore <= 0) return false;
        // Raise the prices by a fifth.
        $r = fees_uprate_apply($ADM);
        if (empty($r['ok'])) return false;
        $cfg = fees_settings();
        if ((int)$cfg['monthlyDues'] !== 1200 || (int)$cfg['trainingFee'] !== 90000) return false;
        /* THE ASSERTION. The balance is byte-for-byte what it was: the rows carry
           their own amounts and nothing recomputes them from the settings. */
        $after = fees_balance(db_row('SELECT * FROM members WHERE memberId = ?', [$id]));
        $ok = (int)($after['byKind']['dues'] ?? 0) === $duesBefore
            && (int)$after['charged'] === (int)$before['charged']
            && (int)$after['payable'] === (int)$before['payable'];
        db_exec('DELETE FROM member_ledger WHERE memberId = ?', [$id]);
        db_exec('DELETE FROM members WHERE memberId = ?', [$id]);
        return $ok;
    })());

    chk('…and the NEXT month is charged at the new figure, not the old one', (function () use ($ADM, $setU) {
        $setU(['monthlyDues' => 1000, 'trainingFee' => 0, 'membershipFee' => 0,
              'upratePct' => 20, 'uprateEveryMonths' => 12, 'uprateLastAt' => '']);
        $id = 'NGG-FEE-UP2';
        db_exec('DELETE FROM member_ledger WHERE memberId = ?', [$id]);
        db_exec('DELETE FROM members WHERE memberId = ?', [$id]);
        db_insert('members', ['memberId' => $id, 'fullName' => 'Uprate Next', 'email' => 'up2@example.com',
            'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'centre' => 'Egbeda',
            'joinDate' => gmdate('Y-m-01', strtotime(gmdate('Y-m-15') . ' -1 month')), 'parentEmail' => 'up2g@example.com',
            'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
        $m = fn() => db_row('SELECT * FROM members WHERE memberId = ?', [$id]);
        // Charge last month at 1000, then raise, then charge this month.
        fees_accrue_member($m(), null, gmdate('Y-m-d', strtotime('-1 month')));
        fees_uprate_apply('test');
        fees_accrue_member($m());
        $amounts = array_map('intval', array_column(
            db_all('SELECT amount FROM member_ledger WHERE memberId = ? AND kind = ? ORDER BY id', [$id, 'dues']), 'amount'));
        db_exec('DELETE FROM member_ledger WHERE memberId = ?', [$id]);
        db_exec('DELETE FROM members WHERE memberId = ?', [$id]);
        // Two months, at two different prices — the old one preserved.
        return $amounts === [1000, 1200];
    })());

    chk('fees uprate: it is PROPOSED, never applied on its own', (function () use ($ADM, $setU) {
        /* A percentage that fired from a cron would mean the first anyone hears
           of a price rise is a bigger reminder email, and nobody could say who
           decided it. So the preview computes and the apply is a separate act. */
        $setU(['monthlyDues' => 1000, 'upratePct' => 20, 'uprateEveryMonths' => 12, 'uprateLastAt' => '']);
        $pv = backend_dispatch('admin.fees.uprate.preview', ['requesterId' => $ADM]);
        if (empty($pv['ok'])) return false;
        $u = $pv['uprate'];
        if (empty($u['due']) || ($u['changes']['monthlyDues']['to'] ?? 0) !== 1200) return false;
        // Looking changed nothing.
        if ((int)fees_settings()['monthlyDues'] !== 1000) return false;
        // Accrual does not sneak an uprate in either.
        $before = (string)fees_settings()['uprateLastAt'];
        backend_dispatch('admin.fees.accrue', ['requesterId' => $ADM]);
        return (int)fees_settings()['monthlyDues'] === 1000
            && (string)fees_settings()['uprateLastAt'] === $before;
    })());

    chk('…and a second press inside the interval is refused, so prices cannot double-rise', (function () use ($ADM, $setU) {
        $setU(['monthlyDues' => 1000, 'upratePct' => 20, 'uprateEveryMonths' => 12, 'uprateLastAt' => '']);
        $first = backend_dispatch('admin.fees.uprate.apply', ['requesterId' => $ADM]);
        if (empty($first['ok']) || (int)fees_settings()['monthlyDues'] !== 1200) return false;
        $second = backend_dispatch('admin.fees.uprate.apply', ['requesterId' => $ADM]);
        // Refused, with the reason, and the price unmoved.
        return ($second['error'] ?? '') === 'not_due' && (int)fees_settings()['monthlyDues'] === 1200
            && (int)($second['everyMonths'] ?? 0) === 12;
    })());

    chk('…and it becomes due again once the interval has passed', (function () use ($ADM, $setU) {
        $setU(['monthlyDues' => 1000, 'upratePct' => 10, 'uprateEveryMonths' => 12]);
        // Stamp it as applied 13 months ago — past the interval.
        $cfg = fees_settings();
        $cfg['uprateLastAt'] = gmdate('Y-m-d\TH:i:s\Z', strtotime('-13 months'));
        setting_set('fees', $cfg, 'test');
        $pv = fees_uprate_preview();
        if (empty($pv['due']) || (int)$pv['monthsSince'] < 12) return false;
        // …and NOT due at 11 months.
        $cfg['uprateLastAt'] = gmdate('Y-m-d\TH:i:s\Z', strtotime('-11 months'));
        setting_set('fees', $cfg, 'test');
        return empty(fees_uprate_preview()['due']);
    })());

    chk('fees uprate: rounded to something a family could read, and clamped', (function () use ($setU) {
        // ₦1,173.50 is arithmetic, not a price. Nearest ₦10.
        $setU(['monthlyDues' => 1055, 'upratePct' => 11, 'uprateEveryMonths' => 12, 'uprateLastAt' => '']);
        $to = fees_uprate_preview()['changes']['monthlyDues']['to'] ?? 0;
        if ($to % FEES_UPRATE_ROUND !== 0) return false;
        // 1055 * 1.11 = 1171.05 → 1170.
        if ((int)$to !== 1170) return false;
        /* And the percentage itself is capped: above the ceiling it is a
           repricing decision that wants a human typing the figure. */
        $r = backend_dispatch('admin.fees.settings.set', ['requesterId' => 'NGG-2025-0099', 'data' => ['upratePct' => 900]]);
        return (int)$r['fees']['upratePct'] === FEES_UPRATE_MAX_PCT;
    })());

    chk('fees uprate: the debt ceiling is not inflated along with the prices', (function () use ($ADM, $setU) {
        /* `balanceCap` is a safety limit on how far a family's arrears may run,
           not a price. Raising it with the dues would quietly undo the protection
           it exists to provide, every year, without anybody choosing to. */
        $setU(['monthlyDues' => 1000, 'balanceCap' => 50000, 'upratePct' => 20,
              'uprateEveryMonths' => 12, 'uprateLastAt' => '']);
        $pv = fees_uprate_preview();
        if (array_key_exists('balanceCap', $pv['changes'])) return false;
        backend_dispatch('admin.fees.uprate.apply', ['requesterId' => $ADM]);
        $cfg = fees_settings();
        return (int)$cfg['balanceCap'] === 50000 && (int)$cfg['monthlyDues'] === 1200;
    })());

    chk('fees uprate: switched off by default, and off means nothing is due', (function () use ($ADM, $setU) {
        if ((int)FEES_DEFAULTS['upratePct'] !== 0) return false;   // not inherited
        $setU(['monthlyDues' => 1000, 'upratePct' => 0, 'uprateLastAt' => '']);
        $pv = fees_uprate_preview();
        return empty($pv['enabled']) && empty($pv['due'])
            && (backend_dispatch('admin.fees.uprate.apply', ['requesterId' => $ADM])['error'] ?? '') === 'uprate_off';
    })());

    chk('fees uprate: the last-applied stamp cannot be set from the settings form', (function () use ($ADM, $setU) {
        /* A field an admin can edit is a field that can be used to apply an
           uprate twice in a year. Only the apply writes it. */
        $setU(['monthlyDues' => 1000, 'upratePct' => 20, 'uprateEveryMonths' => 12, 'uprateLastAt' => '']);
        backend_dispatch('admin.fees.uprate.apply', ['requesterId' => $ADM]);
        $stamped = (string)fees_settings()['uprateLastAt'];
        if ($stamped === '') return false;
        // Try to clear it through the ordinary settings save.
        backend_dispatch('admin.fees.settings.set', ['requesterId' => $ADM, 'data' => ['uprateLastAt' => '', 'monthlyDues' => 1200]]);
        return (string)fees_settings()['uprateLastAt'] === $stamped;
    })());

    /* ── The nudge: said out loud, and still not automatic ────────────────
     *
     * An uprate that is only visible on the tab where it is set is an uprate
     * nobody performs, because nothing tells you to look. So the reminder cron
     * journals it. The two properties that matter are that it CANNOT raise
     * anything (a nudge that could would be the automatic uprate this design
     * refuses) and that it is spaced — the cron ticks every fifteen minutes.
     */
    chk('fees uprate: an overdue review is journalled, not applied', (function () use ($setU) {
        $setU(['monthlyDues' => 1000, 'upratePct' => 20, 'uprateEveryMonths' => 12, 'uprateLastAt' => '']);
        db_exec('DELETE FROM ops_events WHERE source = ?', ['fees.uprate']);
        $before = (int)fees_settings()['monthlyDues'];
        $r = fees_uprate_note();
        if (empty($r['ok'])) return false;
        $row = db_row('SELECT * FROM ops_events WHERE source = ? LIMIT 1', ['fees.uprate']);
        return $row
            && (string)$row['kind'] === 'warn'          // a decision to make, not a fault
            && strpos((string)$row['message'], '20%') !== false
            /* THE ASSERTION: nothing was raised. */
            && (int)fees_settings()['monthlyDues'] === $before
            && (string)fees_settings()['uprateLastAt'] === '';
    })());

    chk('…and it is noted once a month, not once every cron tick', (function () use ($setU) {
        $setU(['monthlyDues' => 1000, 'upratePct' => 20, 'uprateEveryMonths' => 12, 'uprateLastAt' => '']);
        db_exec('DELETE FROM ops_events WHERE source = ?', ['fees.uprate']);
        $cfg = fees_settings(); $cfg['uprateNotedAt'] = ''; setting_set('fees', $cfg, 'test');
        if (empty(fees_uprate_note()['ok'])) return false;
        $hits = (int)(db_row('SELECT hits FROM ops_events WHERE source = ? LIMIT 1', ['fees.uprate'])['hits'] ?? 0);
        /* Ninety-six ticks a day: if the spacing did not hold, this is where a
           to-do item turns the ops journal into a scrolling wall. */
        for ($i = 0; $i < 5; $i++) {
            if ((fees_uprate_note()['error'] ?? '') !== 'noted_recently') return false;
        }
        $after = (int)(db_row('SELECT hits FROM ops_events WHERE source = ? LIMIT 1', ['fees.uprate'])['hits'] ?? 0);
        if ($after !== $hits) return false;
        // …and it speaks again once the spacing has passed.
        $cfg = fees_settings();
        $cfg['uprateNotedAt'] = gmdate('Y-m-d\TH:i:s\Z', strtotime('-' . (FEES_UPRATE_NOTE_DAYS + 1) . ' days'));
        setting_set('fees', $cfg, 'test');
        return !empty(fees_uprate_note()['ok']);
    })());

    chk('…and it says nothing when there is nothing to say', (function () use ($setU) {
        // Uprating off.
        $setU(['monthlyDues' => 1000, 'upratePct' => 0, 'uprateLastAt' => '']);
        if ((fees_uprate_note()['error'] ?? '') !== 'uprate_off') return false;
        // Not due yet.
        $setU(['monthlyDues' => 1000, 'upratePct' => 20, 'uprateEveryMonths' => 12]);
        $cfg = fees_settings();
        $cfg['uprateLastAt'] = gmdate('Y-m-d\TH:i:s\Z', strtotime('-1 month'));
        $cfg['uprateNotedAt'] = '';
        setting_set('fees', $cfg, 'test');
        if ((fees_uprate_note()['error'] ?? '') !== 'not_due') return false;
        // Fees switched off entirely: nobody is being charged, so nothing to review.
        $setU(['enabled' => false, 'monthlyDues' => 1000, 'upratePct' => 20, 'uprateLastAt' => '']);
        $off = (fees_uprate_note()['error'] ?? '');
        $setU(['enabled' => true]);
        return $off === 'fees_off';
    })());

    chk('…and the note stamp is carried by the settings form, not cleared by it', (function () use ($ADM, $setU) {
        $setU(['monthlyDues' => 1000, 'upratePct' => 20, 'uprateEveryMonths' => 12, 'uprateLastAt' => '']);
        $cfg = fees_settings(); $cfg['uprateNotedAt'] = ''; setting_set('fees', $cfg, 'test');
        fees_uprate_note();
        $stamped = (string)fees_settings()['uprateNotedAt'];
        if ($stamped === '') return false;
        backend_dispatch('admin.fees.settings.set', ['requesterId' => $ADM,
            'data' => ['uprateNotedAt' => '', 'monthlyDues' => 1000]]);
        // Clearing it from a form would restart the nagging.
        return (string)fees_settings()['uprateNotedAt'] === $stamped;
    })());

    /* The cron carries it, guarded, and the reminder dispatch is not in its
       shadow — a nudge failing must not cost anybody their reminder. */
    chk('…and the reminders cron carries the nudge in its own guard', (function () {
        $src = (string)@file_get_contents(dirname(__DIR__) . '/_lib/webcron.php');
        if ($src === '') return false;
        if (!preg_match('/function web_cron_reminders\(\).*?\n\}/s', $src, $m)) return false;
        $body = $m[0];
        return strpos($body, 'fees_uprate_note()') !== false
            && strpos($body, 'fees_reminders_run(FEES_REMIND_CRON_BATCH)') !== false
            // Two separate try/catch blocks, not one shared one.
            && substr_count($body, 'catch (Throwable') >= 2;
    })());

    /* ── Nothing hardcoded: one owner per number ───────────────────────────
     *
     * Every bound this subsystem enforces belongs to fees.php, and the screen
     * READS them. The failure this prevents is quiet: a floor written `max(7,…)`
     * in PHP and `|| 7` in React agrees until somebody changes one, and then an
     * admin is told one minimum and given another.
     */
    chk('fees: every bound the screen needs travels with the settings', (function () use ($ADM) {
        $r = backend_dispatch('admin.fees.settings.get', ['requesterId' => $ADM]);
        $b = $r['bounds'] ?? null;
        if (!is_array($b)) return false;
        foreach (['amountMax', 'phaseMin', 'phaseMax', 'remindMinDays', 'remindMaxDays',
                  'uprateMaxPct', 'uprateEveryMin', 'uprateEveryMax', 'uprateRound',
                  'uprateFields', 'accrueBatch', 'remindBatch', 'arrearsPage'] as $k) {
            if (!array_key_exists($k, $b)) return false;
        }
        // And they are the SAME numbers the server enforces, not a second copy.
        return (int)$b['remindMinDays'] === FEES_REMIND_MIN_DAYS
            && (int)$b['uprateMaxPct'] === FEES_UPRATE_MAX_PCT
            && (int)$b['uprateRound'] === FEES_UPRATE_ROUND
            && $b['uprateFields'] === FEES_UPRATE_FIELDS
            && (int)$b['amountMax'] === FEES_AMOUNT_MAX;
    })());

    chk('…and the fees screen keeps no copy of a number the server owns', (function () {
        $src = (string)@file_get_contents(dirname(dirname(__DIR__)) . '/page-admin.jsx');
        if ($src === '') return false;
        $i = strpos($src, 'function AdminFees()');
        if ($i === false) return false;
        // The component, up to the next top-level function.
        $j = strpos($src, "\nfunction ", $i + 10);
        $body = substr($src, $i, ($j === false ? strlen($src) : $j) - $i);
        /* Batch sizes asked for as literals, and fallback copies of a floor —
           both are the shape this regressed into before. */
        if (preg_match('/\.(remindRun|accrue)\(\s*\d/', $body)) return false;
        if (preg_match('/(remindMinDays|everyDays|maxPct|everyMonths)\s*\|\|\s*\d/', $body)) return false;
        // The bounds are read, and read from the server's object.
        return strpos($body, 'meta.bounds') !== false
            && strpos($body, 'B.remindMinDays') !== false
            && strpos($body, 'B.uprateMaxPct') !== false;
    })());

    chk('…and the naira sign is written once on each side, not per screen', (function () {
        $php = (string)@file_get_contents(dirname(__DIR__) . '/_lib/domain/fees.php');
        $root = dirname(dirname(__DIR__));
        $lib = (string)@file_get_contents($root . '/components.jsx');
        $jsx = (string)@file_get_contents($root . '/page-admin.jsx') . (string)@file_get_contents($root . '/page-portals.jsx')
             . (string)@file_get_contents($root . '/src/modules/control/cr-tab-money.jsx');
        if ($php === '' || $lib === '' || $jsx === '') return false;
        /* In PHP the symbol appears in the currency map and in prose/comments,
           never as a second formatter: no `'₦' . number_format(` anywhere. */
        if (preg_match("/'₦'\s*\.\s*number_format/", $php)) return false;
        if (!function_exists('fees_money_text')) return false;
        if (fees_money_text(1000) !== '₦1,000') return false;
        /* One formatter in the client — fmtMoney, in components.jsx — and no
           screen building "₦" + a number of its own (the money screens, and the
           v1 panels Control Room v2 mounts). */
        return preg_match_all('/function fmtMoney\(/', $lib) === 1
            && !preg_match('/₦\{|["\']₦["\']\s*\+|₦"\s*\+\s*(fmtN|Number|String)/u', $jsx);
    })());

    /* ── Fines, adjustments and waivers: the kinds nothing could post ──────
     *
     * `fine`, `adjustment` and `waiver` were declared valid kinds from the
     * start. The reminder email even rendered a "Fines" line. Nothing could
     * create any of them, so that line was unreachable and the only way to
     * forgive a hard month was to VOID a real charge — rewriting history to be
     * kind, which is how a ledger loses its reason.
     */
    chk('fees: a fine can be issued, with a reason, and it lands on the ledger', (function () use ($ADM, $setU) {
        $setU(['monthlyDues' => 1000, 'balanceCap' => 0, 'upratePct' => 0]);
        $id = 'NGG-FEE-FINE';
        db_exec('DELETE FROM member_ledger WHERE memberId = ?', [$id]);
        db_exec('DELETE FROM members WHERE memberId = ?', [$id]);
        db_insert('members', ['memberId' => $id, 'fullName' => 'Fine Test', 'email' => 'fine@example.com',
