    chk('…and a reminder sent today is not sent again tomorrow', (function () use ($set) {
        $set(['remindEnabled' => true, 'remindMinBalance' => 1]);
        db_update('members', ['duesRemindedAt' => ''], ['memberId' => 'NGG-FEE-A']);
        if (!in_array('NGG-FEE-A', array_column(fees_reminder_candidates()['due'], 'memberId'), true)) return false;
        // Stamped as of now → inside the floor, so out of the list.
        db_update('members', ['duesRemindedAt' => now_iso()], ['memberId' => 'NGG-FEE-A']);
        $c = fees_reminder_candidates();
        if (in_array('NGG-FEE-A', array_column($c['due'], 'memberId'), true)) return false;
        if ((int)$c['skipped']['tooSoon'] < 1) return false;
        // …and back in once the floor has passed.
        db_update('members', ['duesRemindedAt' => gmdate('Y-m-d\TH:i:s\Z', strtotime('-' . (FEES_REMIND_MIN_DAYS + 1) . ' days'))], ['memberId' => 'NGG-FEE-A']);
        return in_array('NGG-FEE-A', array_column(fees_reminder_candidates()['due'], 'memberId'), true);
    })());

    chk('…and the cadence floor is what decides, not how often the cron fires', (function () use ($set) {
        /* The cron runs every fifteen minutes. Running the dispatcher repeatedly
           must send at most one message per family per `everyDays` — otherwise the
           schedule becomes the cadence and "constant reminder" is what a guardian
           actually receives. */
        $set(['remindEnabled' => true, 'remindMinBalance' => 1]);
        db_update('members', ['duesRemindedAt' => ''], ['memberId' => 'NGG-FEE-A']);
        $first = fees_reminders_run(50);
        $second = fees_reminders_run(50);
        $third = fees_reminders_run(50);
        return (int)$first['due'] >= 1 && (int)$second['due'] === 0 && (int)$third['due'] === 0
            && (int)$first['everyDays'] >= FEES_REMIND_MIN_DAYS;
    })());

    chk('…and an attempt is stamped even when the mailer fails, so nobody is chased in a loop', (function () use ($set) {
        /* There is no SMTP in the test environment, so send_mail fails — which is
           exactly the case worth pinning. A dispatcher that only stamped on
           SUCCESS would re-send to the same family on every cron tick for as long
           as the mailer stayed broken. */
        $set(['remindEnabled' => true, 'remindMinBalance' => 1]);
        db_update('members', ['duesRemindedAt' => ''], ['memberId' => 'NGG-FEE-A']);
        $r = fees_reminders_run(50);
        $stamp = (string)db_row("SELECT duesRemindedAt FROM members WHERE memberId = 'NGG-FEE-A'")['duesRemindedAt'];
        return $stamp !== '' && ((int)$r['sent'] + (int)$r['failed']) === (int)$r['due'];
    })());

    chk('fees reminders: nothing is sent while they are switched off', (function () use ($ADM, $set) {
        $set(['remindEnabled' => false]);
        db_update('members', ['duesRemindedAt' => ''], ['memberId' => 'NGG-FEE-A']);
        $c = fees_reminder_candidates();
        $r = fees_reminders_run(50);
        $refused = backend_dispatch('admin.fees.remind.run', ['requesterId' => $ADM]);
        $ok = count($c['due']) === 0 && (int)$r['sent'] === 0
            && ($refused['error'] ?? '') === 'reminders_disabled';
        // …and with fees off entirely, likewise.
        $set(['enabled' => false, 'remindEnabled' => true]);
        $ok = $ok && count(fees_reminder_candidates()['due']) === 0;
        $set(['enabled' => true, 'remindEnabled' => false]);
        return $ok;
    })());

    chk('fees reminders: the preview says who and why-not before anything is sent', (function () use ($ADM, $set) {
        $set(['remindEnabled' => true, 'remindMinBalance' => 1]);
        db_update('members', ['duesRemindedAt' => ''], ['memberId' => 'NGG-FEE-A']);
        $p2 = backend_dispatch('admin.fees.remind.preview', ['requesterId' => $ADM]);
        if (empty($p2['ok'])) return false;
        $pv = $p2['preview'];
        foreach (['due', 'count', 'skipped', 'everyDays', 'enabled'] as $k) if (!array_key_exists($k, $pv)) return false;
        // Every exclusion is NAMED — "it will send 4 of 60" is not checkable.
        foreach (['off', 'optedOut', 'nothingPayable', 'underMinimum', 'tooSoon', 'noEmail'] as $k) {
            if (!array_key_exists($k, $pv['skipped'])) return false;
        }
        // A preview does not send: the stamp is untouched by looking.
        $stamp = (string)db_row("SELECT duesRemindedAt FROM members WHERE memberId = 'NGG-FEE-A'")['duesRemindedAt'];
        return $pv['count'] >= 1 && $stamp === '' && $pv['enabled'] === true;
    })());

    chk('fees reminders: the dispatcher is wired to the cron, not only to a button', (function () {
        /* A reminder that only fires when somebody presses something is not a
           reminder. Read off the source because there is no way to make the cron
           tick inside this suite — and the guard matters too: a fault here must
           not take the registration reminders down with it. */
        $src = (string)@file_get_contents(dirname(dirname(__DIR__)) . '/api/_lib/webcron.php');
        if ($src === '') return false;
        if (!preg_match('/function web_cron_reminders\(\).*?\$pending = /s', $src, $m)) return false;
        return strpos($m[0], 'fees_reminders_run') !== false
            && strpos($m[0], 'catch (Throwable') !== false;
    })());

    chk('fees reminders: every reminder op is gated on the roster capability', (function () {
        foreach (['admin.fees.remind.preview', 'admin.fees.remind.run'] as $op) {
            if ((backend_dispatch($op, ['requesterId' => ''])['ok'] ?? false) === true) return false;
        }
        return true;
    })());

    // Tidy up: the ledger rows and the two members are ours.
    db_exec("DELETE FROM member_ledger WHERE memberId IN ('NGG-FEE-A','NGG-FEE-B')");
    db_exec("DELETE FROM members WHERE memberId IN ('NGG-FEE-A','NGG-FEE-B')");
    if (is_array($keepFees)) setting_set('fees', $keepFees, 'test');
    else db_exec("DELETE FROM settings WHERE settingKey = 'fees'");
})();

/* ── M4: the dues ledger is gated by its own `fees` capability, not `people` ──
 * A member-desk admin (people, not fees) must be refused; granting `fees` per
 * person opens it; super_admin holds it by role; and the one-time backfill seed
 * grants `fees` to pre-split admins so nobody is locked out on deploy. */
(function () {
    db_exec("DELETE FROM members WHERE memberId IN ('NGG-FEECAP-DESK','NGG-FEECAP-OLD')");
    db_insert('members', ['memberId' => 'NGG-FEECAP-DESK', 'fullName' => 'Desk Admin', 'email' => 'desk-feecap@example.com',
        'type' => 'NGG', 'status' => 'active', 'role' => 'admin', 'centre' => 'Egbeda',
        'createdAt' => now_iso(), 'updatedAt' => now_iso()]);

    // The gate is the first statement in every fee op, so a denied requester is
    // rejected before any params are read — minimal payloads are fine.
    $deskDenied = true;
    foreach (['admin.fees.settings.get', 'admin.fees.member', 'admin.fees.accrue',
              'admin.fees.charge', 'admin.fees.void', 'admin.fees.waive'] as $op) {
        $r = backend_dispatch($op, ['requesterId' => 'NGG-FEECAP-DESK', 'memberId' => 'NGG-FEE-A']);
        if (($r['ok'] ?? false) !== false || ($r['error'] ?? '') !== 'forbidden') { $deskDenied = false; break; }
    }
    chk('a people-only admin is refused every fee op (missing_cap:fees)', $deskDenied);

    backend_dispatch('admin.members.caps', ['requesterId' => 'NGG-2025-0099', 'memberId' => 'NGG-FEECAP-DESK', 'caps' => ['fees']]);
    chk('granting the fees cap (capsExtra) opens fee ops',
        (backend_dispatch('admin.fees.settings.get', ['requesterId' => 'NGG-FEECAP-DESK'])['ok'] ?? false) === true);
    chk('super_admin still reaches fee ops by role',
        (backend_dispatch('admin.fees.settings.get', ['requesterId' => 'NGG-2025-0099'])['ok'] ?? false) === true);

    // Backfill seed: a pre-split member-desk admin gains `fees` once, no role change.
    db_insert('members', ['memberId' => 'NGG-FEECAP-OLD', 'fullName' => 'Legacy Fee Admin', 'email' => 'legacy-feecap@example.com',
        'type' => 'NGG', 'status' => 'active', 'role' => 'admin', 'centre' => 'Egbeda',
        'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    $keepSeed = setting_raw('seed_fees_cap_v1');
    setting_set('seed_fees_cap_v1', '0', 'system');   // re-arm the one-time seed
    db_run_seeds(db_conn());
    $old = member_effective_caps(db_row('SELECT role, capsExtra FROM members WHERE memberId = ?', ['NGG-FEECAP-OLD']) ?: []);
    chk('backfill grants fees to a pre-split member-desk admin', in_array('fees', $old, true));
    $saExtra = safe_json((string)(db_row('SELECT capsExtra FROM members WHERE memberId = ?', ['NGG-2025-0099'])['capsExtra'] ?? ''));
    chk('backfill leaves super_admin capsExtra untouched (fees is by role)', !is_array($saExtra) || !in_array('fees', $saExtra, true));
    setting_set('seed_fees_cap_v1', $keepSeed === '' ? '1' : $keepSeed, 'system');

    db_exec("DELETE FROM members WHERE memberId IN ('NGG-FEECAP-DESK','NGG-FEECAP-OLD')");
})();

/* ── Seasonal nudges: dated encouragement/appreciation/reminder EMAILS to
 * volunteers, students and parents — same-day only, once per recipient. Uses the
 * mail sink so nothing actually sends. ── */
(function () {
    db_exec("DELETE FROM volunteers WHERE volunteerId = 'V-NUDGE-1'");
    db_exec("DELETE FROM members WHERE memberId = 'NGG-NUDGE-1'");
    db_exec("DELETE FROM summer_students WHERE studentId = 'SS-NUDGE-1'");
    db_insert('volunteers', ['volunteerId' => 'V-NUDGE-1', 'fullName' => 'Val Unteer', 'email' => 'val-nudge@example.com',
        'role' => 'volunteer', 'status' => 'active', 'token' => 'VOLQR-NUDGE', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    db_insert('members', ['memberId' => 'NGG-NUDGE-1', 'fullName' => 'Stu Dent', 'email' => 'stu-nudge@example.com',
        'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'centre' => 'Egbeda',
        'parentName' => 'Pat Parent', 'parentEmail' => 'par-nudge@example.com', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    db_insert('summer_students', ['studentId' => 'SS-NUDGE-1', 'cohortId' => 'SUM-2026', 'fullName' => 'Summer Kid',
        'status' => 'active', 'regStatus' => 'verified', 'guardianName' => 'Gee Guard', 'parentEmail' => 'spar-nudge@example.com',
        'enrolledAt' => now_iso(), 'updatedAt' => now_iso()]);

    $sink = function () { $GLOBALS['__mail_sink'] = []; return $GLOBALS['__mail_sink']; };
    $tos  = fn() => array_map(fn($m) => $m['to'], $GLOBALS['__mail_sink']);

    // Aug 13 carries a volunteer reminder + a parent check-in (no student note).
    $sink();
    $r = nudges_run('2026-08-13', 100);
    chk('nudge emails the volunteer their dated note',
        (bool)array_filter($GLOBALS['__mail_sink'], fn($m) => $m['to'] === 'val-nudge@example.com' && strpos($m['subject'], 'shift') !== false));
    chk('nudge reaches BOTH an NGG parent and a summer-student parent',
        in_array('par-nudge@example.com', $tos(), true) && in_array('spar-nudge@example.com', $tos(), true));
    chk('nudge bodies are HTML email, not SMS text', (function () {
        if (!count($GLOBALS['__mail_sink'])) return false;
        foreach ($GLOBALS['__mail_sink'] as $m) if (strpos($m['html'], '<') === false) return false; return true;
    })());
    chk('the run summary counts exactly the sends made (all active recipients, ≥ our 3)',
        ($r['sent'] ?? -1) === count($GLOBALS['__mail_sink']) && ($r['sent'] ?? 0) >= 3);

    // Idempotent: a second run of the same day re-sends nothing.
    $sink();
    $r2 = nudges_run('2026-08-13', 100);
    chk('re-running the same day is idempotent (once per recipient)', ($r2['sent'] ?? -1) === 0 && count($GLOBALS['__mail_sink']) === 0);

    // No backfill: a date with no scheduled message is silent.
    $sink();
    chk('a date with no message sends nothing (never backfills)', (nudges_run('2026-08-12', 100)['sent'] ?? -1) === 0);

    // Students get their OWN dated note (Aug 16 has a volunteer + a student one).
    $sink();
    $r3 = nudges_run('2026-08-16', 100);
    chk('the NGG student receives their own dated nudge', in_array('stu-nudge@example.com', $tos(), true));

    // Pause switch.
    setting_set('nudges_enabled', '0', 'test');
    $sink();
    $r4 = nudges_run('2026-08-23', 100);
    chk('nudges_enabled=0 pauses the whole campaign', ($r4['skipped'] ?? '') === 'disabled' && count($GLOBALS['__mail_sink']) === 0);

    unset($GLOBALS['__mail_sink']);
    db_exec("DELETE FROM settings WHERE settingKey = 'nudges_enabled'");
    db_exec("DELETE FROM nudge_log WHERE recipient IN ('val-nudge@example.com','par-nudge@example.com','spar-nudge@example.com','stu-nudge@example.com')");
    db_exec("DELETE FROM volunteers WHERE volunteerId = 'V-NUDGE-1'");
    db_exec("DELETE FROM members WHERE memberId = 'NGG-NUDGE-1'");
    db_exec("DELETE FROM summer_students WHERE studentId = 'SS-NUDGE-1'");
})();

