        if ($op === 'faces') return ['ok' => true, 'design' => '2-abc', 'faces' => ['41' => ['front' => '<article class="avc">F</article>', 'back' => '<article class="avc">B</article>']]];
        return ['ok' => false, 'error' => 'unknown_op'];
    };
