    $dm = backend_dispatch('admin.members.demoteNgv', ['requesterId' => $ADM, 'memberId' => 'NGG-PORT-1']);
    $rv = array_values(array_filter($calls, fn($c) => str_contains((string)$c[1], 'private.ngv.revoked')));
