    chk('door: …and needs a password', (backend_dispatch('admin.gates.create', ['requesterId' => 'NGG-APR-SUM', 'name' => 'x', 'kind' => 'register'])['error'] ?? '') === 'password_required');
    $lc = backend_dispatch('admin.gates.list', ['requesterId' => 'NGG-APR-CLUB']);
