    $sub2 = backend_dispatch('staff.curriculum.material', ['requesterId' => 'NGG-SUB-INS', 'unitId' => 'CUR-SUB-1', 'title' => 'Blurry photo', 'url' => 'https://example.org/p.jpg']);
