    $list = backend_dispatch('admin.requests.list', ['requesterId' => 'NGG-FA-ADM', 'status' => 'open']);
    $row = array_values(array_filter($list['requests'] ?? [], fn($x) => $x['requestId'] === $rq['request']['requestId']))[0] ?? [];
