    chk('separation: a Summer School coordinator cannot edit the Club\'s courses', (backend_dispatch('admin.club.catalogue.set', ['requesterId' => 'NGG-SEP-SUM', 'catalogue' => ['X' => ['Y']]])['error'] ?? '') === 'forbidden');
    $pn = backend_dispatch('public.programme', ['program' => 'anchor']); $ps = backend_dispatch('public.programme', ['program' => 'summer']);
    $flat = fn($r) => array_merge(...array_map(fn($f) => $f['courses'], $r['faculties'] ?? [['courses' => []]]));
    chk('separation: the join form offers each programme its own courses', in_array('Media Lab', $flat($pn), true) && !in_array('Piano', $flat($pn), true) && $flat($ps) === ['Piano']);

    // Centres.
    db_insert('centres', ['centreId' => 'CEN-SEP-S', 'name' => 'Sep Summer Venue', 'code' => 'SV', 'status' => 'active', 'slug' => 'sep-summer', 'pageStatus' => 'published', 'programmes' => 'summer', 'meetDays' => 'Saturdays', 'createdAt' => $now]);
    db_insert('centres', ['centreId' => 'CEN-SEP-C', 'name' => 'Sep Club House', 'code' => 'SC', 'status' => 'active', 'slug' => 'sep-club', 'pageStatus' => 'published', 'programmes' => 'ngg', 'meetDays' => 'Saturdays', 'createdAt' => $now]);
    db_insert('centres', ['centreId' => 'CEN-SEP-B', 'name' => 'Sep Both', 'code' => 'SB', 'status' => 'active', 'slug' => 'sep-both', 'pageStatus' => 'published', 'createdAt' => $now]);
    $names = fn($list) => array_column($list, 'name');
    $pn = backend_dispatch('public.programme', ['program' => 'anchor']); $ps = backend_dispatch('public.programme', ['program' => 'summer']);
    chk('separation: a centre with no programme set runs both — every existing row keeps working', in_array('Sep Both', centre_names_for_programme('ngg'), true) && in_array('Sep Both', centre_names_for_programme('summer'), true));
    chk('separation: the NGG join form does not offer a Summer-only venue; the Summer form does not offer a Club-only centre',
        in_array('Sep Club House', $names($pn['centres']), true) && !in_array('Sep Summer Venue', $names($pn['centres']), true)
        && in_array('Sep Summer Venue', $names($ps['centres']), true) && !in_array('Sep Club House', $names($ps['centres']), true));
    $tl = backend_dispatch('admin.timetable.list', ['requesterId' => 'NGG-SEP-SUP']);
    chk('separation: the Club timetable does not offer a Summer-only venue', !in_array('Sep Summer Venue', $names($tl['centres'] ?? []), true) && in_array('Sep Club House', $names($tl['centres'] ?? []), true));
    $ts = backend_dispatch('admin.timetable.save', ['requesterId' => 'NGG-SEP-SUP', 'data' => ['centreId' => 'CEN-SEP-S', 'course' => 'Guitar', 'weekday' => 6, 'startTime' => '10:00', 'endTime' => '11:00']]);
    chk('separation: …and refuses a class there, saying how to fix it', ($ts['error'] ?? '') === 'centre_not_ngg' && str_contains($ts['detail'], 'People → Centres'));
    chk('separation: Summer School\'s public centre pages do not list a Club-only centre', !in_array('Sep Club House', $names(public_centres_list()['centres']), true) && (public_centre_page(['slug' => 'sep-club'])['error'] ?? '') === 'not_found');
    $ap = backend_dispatch('public.apply', ['kind' => 'teen', 'program' => 'anchor', 'firstName' => 'Sep', 'lastName' => 'Kid', 'dob' => '2014-01-01', 'sex' => 'Female',
        'centre' => 'sep summer venue', 'track' => 'guitar', 'why' => str_repeat('I want to learn. ', 3), 'email' => 'sepkid@example.com', 'phone' => '08030000000']);
    chk('separation: an NGG application to a Summer-only venue is refused by name', ($ap['error'] ?? '') === 'centre_not_offered' && str_contains($ap['detail'] ?? '', 'Sep Summer Venue'));
    $cu = fn($d) => backend_dispatch('admin.centres.upsert', ['requesterId' => 'NGG-SEP-SUP', 'data' => $d + ['name' => 'Sep New', 'color' => '#76B043']]);
    chk('separation: "ST" is kept for unplaced Summer cards and cannot be a centre code', ($cu(['code' => 'ST'])['error'] ?? '') === 'code_reserved');
    chk('separation: an all-digit code (an NGG year prefix) is refused', ($cu(['code' => '026'])['error'] ?? '') === 'code_reserved');
    chk('separation: a centre must run at least one programme', ($cu(['code' => 'SN', 'programmes' => []])['error'] ?? '') === 'programme_required');
    $ok = $cu(['code' => 'SN', 'programmes' => ['summer']]);
    chk('separation: the programmes a centre runs are saved', !empty($ok['ok']) && (string)db_row("SELECT programmes FROM centres WHERE code = 'SN'")['programmes'] === 'summer');

    // Summer cards mint from the highest serial, never a count.
    $yy = gmdate('y');
    db_insert('summer_students', ['studentId' => 'STU-SEP-1', 'fullName' => 'Sep A', 'centre' => 'Sep Summer Venue', 'displayId' => "SV-$yy-001"]);
    db_insert('summer_students', ['studentId' => 'STU-SEP-2', 'fullName' => 'Sep B', 'centre' => 'Sep Summer Venue', 'displayId' => "SV-$yy-007"]);
    db_insert('summer_students', ['studentId' => 'STU-SEP-3', 'fullName' => 'Sep C', 'centre' => 'Sep Summer Venue']);
    chk('separation: a Summer card number follows the highest serial, not the count (a gap is a printed card)',
        card_display_id(db_row("SELECT * FROM summer_students WHERE studentId = 'STU-SEP-3'")) === "SV-$yy-008");

    db_exec("DELETE FROM summer_students WHERE studentId LIKE 'STU-SEP-%'");
    db_exec("DELETE FROM centres WHERE centreId LIKE 'CEN-SEP-%' OR code = 'SN'");
    db_exec("DELETE FROM applications WHERE email = 'sepkid@example.com'");
    db_exec("DELETE FROM members WHERE memberId LIKE 'NGG-SEP-%'");
    foreach (['club_catalogue' => $keepClub, 'academy_catalogue' => $keepAcad] as $k => $v) {
        if ($v === null || $v === '') db_exec('DELETE FROM settings WHERE settingKey = ?', [$k]); else setting_set($k, $v, 'test');
    }
})();

/* ── The timetable: clashes refused on the way in, by name ── */
(function () {
    $now = now_iso();
    db_insert('centres', ['centreId' => 'CEN-TT-A', 'name' => 'Tt Alpha', 'code' => 'TA', 'status' => 'active', 'meetDays' => 'Saturdays', 'meetTime' => '9am - 2pm', 'slug' => 'tt-alpha', 'createdAt' => $now]);
    db_insert('centres', ['centreId' => 'CEN-TT-B', 'name' => 'Tt Beta', 'code' => 'TB', 'status' => 'active', 'meetDays' => 'Saturdays, Wednesdays', 'meetTime' => '', 'slug' => 'tt-beta', 'createdAt' => $now]);
    db_insert('volunteers', ['volunteerId' => 'VOL-TT-1', 'fullName' => 'Ife Instructor', 'email' => 'tt1@example.com', 'role' => 'instructor', 'status' => 'active', 'createdAt' => $now, 'updatedAt' => $now]);
    $mk = fn($id, $role, $extra = []) => db_insert('members', array_merge(['memberId' => $id, 'fullName' => 'Tt ' . $id, 'email' => strtolower($id) . '@example.com',
        'type' => 'NGG', 'status' => 'active', 'role' => $role, 'createdAt' => $now, 'updatedAt' => $now], $extra));
    $mk('NGG-TT-ADM', 'club_admin'); $mk('NGG-TT-SCOPED', 'club_admin', ['centreScope' => json_encode(['Tt Beta'])]);
    $mk('NGG-TT-ED', 'editor'); $mk('NGG-TT-M', 'member', ['centre' => 'Tt Alpha', 'track' => 'Piano']);
    $save = fn($d, $who = 'NGG-TT-ADM') => backend_dispatch('admin.timetable.save', ['requesterId' => $who, 'data' => $d]);
    $base = ['centreId' => 'CEN-TT-A', 'course' => 'piano', 'weekday' => 6, 'startTime' => '10:00', 'endTime' => '11:30', 'room' => '', 'instructorId' => 'VOL-TT-1'];

    $a = $save($base);
    chk('timetable: a slot saves, with the course spelt as the catalogue spells it', !empty($a['ok']) && $a['slot']['course'] === 'Piano' && $a['slot']['day'] === 'Saturday');
    $r = $save(array_merge($base, ['course' => 'Guitar', 'instructorId' => '', 'startTime' => '11:00', 'endTime' => '12:00']));
    chk('timetable: two courses in the same room at once are refused, naming what is there', ($r['error'] ?? '') === 'clash' && $r['clashes'][0]['type'] === 'room' && str_contains($r['detail'], 'Piano'));
    $r = $save(array_merge($base, ['course' => 'Guitar', 'instructorId' => '', 'startTime' => '11:30', 'endTime' => '12:30']));
    chk('timetable: back-to-back is not a clash', !empty($r['ok']));
    $r = $save(array_merge($base, ['course' => 'Guitar', 'room' => 'Studio 2', 'startTime' => '10:30', 'endTime' => '11:00']));
    chk('timetable: one instructor in two rooms at once is refused', ($r['error'] ?? '') === 'clash' && in_array('instructor', array_column($r['clashes'], 'type'), true) && str_contains($r['detail'], 'Ife Instructor'));
    $r = $save(array_merge($base, ['centreId' => 'CEN-TT-B', 'course' => 'Guitar', 'room' => '']));
    chk('timetable: …and at another centre too', ($r['error'] ?? '') === 'clash' && $r['clashes'][0]['type'] === 'instructor' && str_contains($r['detail'], 'Tt Alpha'));
    $r = $save(array_merge($base, ['instructorId' => '', 'room' => 'Studio 2', 'startTime' => '11:00', 'endTime' => '12:00']));
    chk('timetable: the same course twice at one centre at once is refused — its members cannot be in two rooms', ($r['error'] ?? '') === 'clash' && $r['clashes'][0]['type'] === 'course');
    $r = $save(array_merge($base, ['weekday' => 2, 'instructorId' => '']));
    chk('timetable: a day the centre does not meet is refused, saying which days it does', ($r['error'] ?? '') === 'clash' && $r['clashes'][0]['type'] === 'centre_day' && str_contains($r['detail'], 'Saturday'));
    $r = $save(array_merge($base, ['instructorId' => '', 'course' => 'Guitar', 'room' => 'Hall B', 'startTime' => '13:30', 'endTime' => '15:00']));
    chk('timetable: outside the centre\'s meeting hours is refused', ($r['error'] ?? '') === 'clash' && $r['clashes'][0]['type'] === 'centre_time' && str_contains($r['detail'], '09:00–14:00'));
    chk('timetable: a course outside the catalogue is refused', ($save(array_merge($base, ['course' => 'Underwater Basketry']))['error'] ?? '') === 'unknown_course');
    chk('timetable: it must end after it starts', ($save(array_merge($base, ['startTime' => '12:00', 'endTime' => '11:00']))['error'] ?? '') === 'bad_time');
    chk('timetable: moving a slot does not clash with itself', !empty($save(array_merge($base, ['slotId' => $a['slot']['slotId'], 'endTime' => '11:15']))['ok']));

    // Scope and permission.
    chk('timetable: a scoped club admin cannot add to a centre outside their scope', ($save(array_merge($base, ['course' => 'Guitar', 'weekday' => 6, 'startTime' => '09:00', 'endTime' => '09:45', 'instructorId' => '']), 'NGG-TT-SCOPED')['error'] ?? '') === 'out_of_scope');
    chk('timetable: changing it needs the club permission', ($save($base, 'NGG-TT-ED')['ok'] ?? true) === false);
    $sl = backend_dispatch('admin.timetable.list', ['requesterId' => 'NGG-TT-SCOPED']);
    chk('timetable: a scoped list shows only their centres', !array_filter($sl['slots'], fn($x) => $x['centreId'] === 'CEN-TT-A') && !in_array('CEN-TT-A', array_column($sl['centres'], 'centreId'), true));

    // A clash already stored (the centre changed its days after) is reported, not hidden.
    db_update('centres', ['meetDays' => 'Sundays'], ['centreId' => 'CEN-TT-A']);
    $l = backend_dispatch('admin.timetable.list', ['requesterId' => 'NGG-TT-ADM', 'centreId' => 'CEN-TT-A']);
    chk('timetable: a centre changing its days later shows up as clashes on the list', $l['clashCount'] === count($l['slots']) && $l['clashCount'] >= 2
        && $l['slots'][0]['clashes'][0]['type'] === 'centre_day');
    db_update('centres', ['meetDays' => 'Saturdays'], ['centreId' => 'CEN-TT-A']);

    // The member, the family, the public.
    $mt = backend_dispatch('member.timetable', ['memberId' => 'NGG-TT-M']);
    chk('timetable: a member sees their centre\'s timetable, with their own course marked', count($mt['slots']) === 2
        && array_values(array_filter($mt['slots'], fn($x) => $x['mine']))[0]['course'] === 'Piano');
    $pub = backend_dispatch('public.timetable', ['slug' => 'tt-alpha']);
    chk('timetable: the public page lists the centre\'s slots without naming instructors', count($pub['slots']) === 2 && !isset($pub['slots'][0]['instructor']) && !str_contains(json_encode($pub), 'Ife Instructor'));
    chk('timetable: the public index lists only centres that have a timetable', in_array('tt-alpha', array_column($pub['centres'], 'slug'), true) && !in_array('tt-beta', array_column($pub['centres'], 'slug'), true));
    chk('timetable: deleting a centre counts its timetable as a use', (backend_dispatch('admin.centres.delete', ['requesterId' => 'NGG-2025-0099', 'centreId' => 'CEN-TT-A'])['uses']['timetable'] ?? 0) === 2);

    // Removing: per-row verdicts, one audit event.
    $rm = backend_dispatch('admin.timetable.remove', ['requesterId' => 'NGG-TT-ADM', 'slotIds' => [$a['slot']['slotId'], 'TT-NOPE']]);
    chk('timetable: removing reports per row', $rm['done'] === 1 && $rm['results'][1]['error'] === 'not_found');
    chk('timetable: a removed slot leaves the member\'s view', count(backend_dispatch('member.timetable', ['memberId' => 'NGG-TT-M'])['slots']) === 1);

    db_exec("DELETE FROM timetable_slots WHERE centreId LIKE 'CEN-TT-%'");
    db_exec("DELETE FROM centres WHERE centreId LIKE 'CEN-TT-%'");
    db_exec("DELETE FROM volunteers WHERE volunteerId = 'VOL-TT-1'");
    db_exec("DELETE FROM members WHERE memberId LIKE 'NGG-TT-%'");
})();


/* ── Personal timetables (the Timetable Maker): validated, never written into a centre's week ── */
(function () {
    $now = now_iso();
    db_insert('members', ['memberId' => 'NGG-TP-1', 'fullName' => 'Tp Learner', 'email' => 'tp-1@example.org', 'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'createdAt' => $now, 'updatedAt' => $now]);
    $doc = fn(array $over = []) => array_merge([
        'settings' => ['title' => 'My week', 'theme' => 'paper'],
        'entries' => [['id' => 'e1', 'title' => 'Maths', 'days' => [3, 1, 1], 'start' => '08:00', 'end' => '09:00', 'place' => 'Room 4', 'color' => 9, 'kind' => 'class']],
        'exceptions' => ['2026-10-05' => ['skip' => ['e1:1' => true, 'bad' => true], 'once' => [['id' => 'x1', 'title' => 'Test', 'days' => [4], 'start' => '10:00', 'end' => '11:00', 'kind' => 'class']]]],
    ], $over);
    $slotsBefore = (int)db_row('SELECT COUNT(*) c FROM timetable_slots')['c'];

    chk('personal timetable: none is stored until one is saved', backend_dispatch('member.myTimetable', ['memberId' => 'NGG-TP-1'])['timetable'] === null);
    $s = backend_dispatch('member.myTimetable.save', ['memberId' => 'NGG-TP-1', 'baseUpdatedAt' => ''] + $doc());
    $g = backend_dispatch('member.myTimetable', ['memberId' => 'NGG-TP-1'])['timetable'];
    chk('personal timetable: a member saves their week and reads it back', !empty($s['ok']) && $g['entries'][0]['title'] === 'Maths' && $g['updatedAt'] === $s['updatedAt']);
    chk('personal timetable: days are deduped and sorted, a colour is clamped', $g['entries'][0]['days'] === [1, 3] && $g['entries'][0]['color'] === 7);
    chk('personal timetable: a skip keeps only well-formed keys, a one-off is kept', array_keys($g['exceptions']['2026-10-05']['skip']) === ['e1:1'] && $g['exceptions']['2026-10-05']['once'][0]['once'] === true);
    chk('personal timetable: it never lands in a centre\'s timetable_slots', (int)db_row('SELECT COUNT(*) c FROM timetable_slots')['c'] === $slotsBefore);

    $c = backend_dispatch('member.myTimetable.save', ['memberId' => 'NGG-TP-1', 'baseUpdatedAt' => '2000-01-01T00:00:00Z'] + $doc());
    chk('personal timetable: a save from a stale copy is a conflict carrying the stored one, not an overwrite', ($c['error'] ?? '') === 'conflict' && $c['server']['updatedAt'] === $s['updatedAt']);
    $s2 = backend_dispatch('member.myTimetable.save', ['memberId' => 'NGG-TP-1', 'baseUpdatedAt' => $s['updatedAt']] + $doc(['settings' => ['title' => 'Again']]));
    chk('personal timetable: a save from the current copy goes through with a later stamp', !empty($s2['ok']) && $s2['updatedAt'] > $s['updatedAt']);

    $bad = fn(array $e) => backend_dispatch('member.myTimetable.save', ['memberId' => 'NGG-TP-1', 'baseUpdatedAt' => $s2['updatedAt']] + $doc(['entries' => [$e]]))['error'] ?? 'saved';
    $ok = ['id' => 'e', 'title' => 'Maths', 'days' => [1], 'start' => '08:00', 'end' => '09:00', 'kind' => 'class'];
    chk('personal timetable: an entry that ends before it starts is refused', $bad(['start' => '10:00', 'end' => '09:00'] + $ok) === 'bad_time');
    chk('personal timetable: a time that is not HH:MM is refused', $bad(['start' => '8am'] + $ok) === 'bad_time');
    chk('personal timetable: a weekday outside 1–7 is refused', $bad(['days' => [0, 8]] + $ok) === 'bad_days');
    chk('personal timetable: a title over 60 characters is refused', $bad(['title' => str_repeat('x', 61)] + $ok) === 'bad_title');
    chk('personal timetable: a type outside class/study/activity/break is refused', $bad(['kind' => 'party'] + $ok) === 'bad_kind');
    $many = backend_dispatch('member.myTimetable.save', ['memberId' => 'NGG-TP-1', 'baseUpdatedAt' => $s2['updatedAt']] + $doc(['entries' => array_fill(0, 121, $ok)]));
    chk('personal timetable: more than 120 entries is refused', ($many['error'] ?? '') === 'too_many_entries');
    $weeks = [];
    for ($i = 0; $i < 53; $i++) $weeks[gmdate('Y-m-d', strtotime('2026-01-05 +' . $i . ' weeks'))] = ['skip' => ['e1:1' => true]];
    chk('personal timetable: more than 52 weeks of changes is refused', (backend_dispatch('member.myTimetable.save', ['memberId' => 'NGG-TP-1', 'baseUpdatedAt' => $s2['updatedAt']] + $doc(['exceptions' => $weeks]))['error'] ?? '') === 'too_many_weeks');

    // Without an account: an emailed link, its token stored only as a hash.
    $l = backend_dispatch('public.timetableSave', ['email' => 'Parent@Example.org'] + $doc());
    $row = db_row('SELECT * FROM timetable_links WHERE email = ?', ['parent@example.org']);
    chk('personal timetable: saving by email mints a link and keeps only its hash', !empty($l['ok']) && preg_match('/^[a-f0-9]{64}$/', $l['k']) && $row && $row['tokenHash'] === hash('sha256', $l['k']));
    chk('personal timetable: the link opens the same timetable', backend_dispatch('public.timetableLoad', ['k' => $l['k']])['timetable']['entries'][0]['title'] === 'Maths');
    $u = backend_dispatch('public.timetableSave', ['k' => $l['k']] + $doc(['settings' => ['title' => 'Edited']]));
    chk('personal timetable: saving through the link updates it', !empty($u['ok']) && backend_dispatch('public.timetableLoad', ['k' => $l['k']])['timetable']['settings']['title'] === 'Edited');
    chk('personal timetable: an unknown or malformed token opens nothing', (backend_dispatch('public.timetableLoad', ['k' => str_repeat('a', 64)])['error'] ?? '') === 'link_expired'
        && (backend_dispatch('public.timetableLoad', ['k' => 'nope'])['error'] ?? '') === 'link_expired');
    db_exec("UPDATE timetable_links SET expiresAt = '2000-01-01T00:00:00Z' WHERE email = 'parent@example.org'");
    chk('personal timetable: a lapsed link neither opens nor saves', (backend_dispatch('public.timetableLoad', ['k' => $l['k']])['error'] ?? '') === 'link_expired'
        && (backend_dispatch('public.timetableSave', ['k' => $l['k']] + $doc())['error'] ?? '') === 'link_expired');
    backend_dispatch('public.timetableSave', ['email' => 'parent@example.org'] + $doc());
    backend_dispatch('public.timetableSave', ['email' => 'parent@example.org'] + $doc());
    chk('personal timetable: three links a day per address, then refused', (backend_dispatch('public.timetableSave', ['email' => 'parent@example.org'] + $doc())['error'] ?? '') === 'too_many_links');
    chk('personal timetable: an address that is not one is refused', (backend_dispatch('public.timetableSave', ['email' => 'not-an-email'] + $doc())['error'] ?? '') === 'bad_email');
    $term = backend_dispatch('public.timetableTerm', []);
    chk('personal timetable: the term op answers with two dates or two blanks', !empty($term['ok']) && array_key_exists('start', $term) && array_key_exists('end', $term));
    chk('personal timetable: a member merge says what happens to a personal week', (member_merge_policy()['member_timetables'] ?? '') === 'MOVE_UNIQUE');

    db_exec("DELETE FROM timetable_links WHERE email = 'parent@example.org'");
    db_exec("DELETE FROM member_timetables WHERE memberId = 'NGG-TP-1'");
    db_exec("DELETE FROM members WHERE memberId = 'NGG-TP-1'");
})();

/* ── ID Card Studio: who has a card, the reprint queue, failures after printing ── */
(function () use ($CARDADM, $RUN1, $TID) {
    $TIDX = $TID;
    $SUMADM = 'NGG-2025-0700';   // summer_admin: Summer School's cards, not members'
    $st = backend_dispatch('admin.ids.state', ['requesterId' => $CARDADM]);
    $key = 'member:NGG-CARD-1';
    $last = db_row("SELECT i.runId, i.displayId FROM card_issues i JOIN card_runs r ON r.runId = i.runId
                    WHERE i.subjectType = 'member' AND i.subjectId = 'NGG-CARD-1' AND r.mode != 'proof' AND i.ok = 1 ORDER BY i.id DESC LIMIT 1");
    chk('id studio: the state says who already has a card, from the issue log', !empty($st['ok']) && $last && ($st['issued']->$key['runId'] ?? '') === $last['runId']);
    chk('id studio: …and it is the LATEST issue per person, not the first', ($st['issued']->$key['displayId'] ?? '') === $last['displayId']
        && (int)db_row("SELECT COUNT(*) c FROM card_issues WHERE subjectId = 'NGG-CARD-1'")['c'] > 1);
    $pr = backend_dispatch('admin.card.run.record', ['requesterId' => $CARDADM, 'kind' => 'member', 'subjectType' => 'member', 'mode' => 'proof', 'output' => 'sheet',
        'items' => [['subjectId' => 'NGG-IDS-PROOF', 'displayId' => 'P-1']]]);
    chk('id studio: a PROOF does not count as having a card, so nobody drops out of the queue', !empty($pr['ok'])
        && !property_exists(backend_dispatch('admin.ids.state', ['requesterId' => $CARDADM])['issued'], 'member:NGG-IDS-PROOF'));
    $sst = backend_dispatch('admin.ids.state', ['requesterId' => $SUMADM]);
    chk('id studio: a Summer admin sees participants only, never the members\' log', !empty($sst['ok']) && $sst['types'] === ['student'] && !property_exists($sst['issued'], $key));
    db_insert('members', ['memberId' => 'NGG-IDS-ED', 'fullName' => 'Ida Editor', 'email' => 'ids-ed@example.com', 'type' => 'NGG', 'status' => 'active', 'role' => 'editor', 'centre' => 'Egbeda', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    chk('id studio: staff with neither capability are refused', (backend_dispatch('admin.ids.state', ['requesterId' => 'NGG-IDS-ED'])['error'] ?? '') === 'forbidden');

    $r = backend_dispatch('admin.ids.reprint.request', ['requesterId' => $CARDADM, 'items' => [
        ['subjectType' => 'member', 'subjectId' => 'NGG-CARD-1', 'why' => 'Lost'], ['subjectType' => 'alien', 'subjectId' => 'x']]]);
    chk('id studio: a reprint is queued, and a bad row is refused by name, not dropped', !empty($r['ok']) && $r['added'] === 1 && ($r['refused'][0]['error'] ?? '') === 'bad_subject');
    $r = backend_dispatch('admin.ids.reprint.request', ['requesterId' => $CARDADM, 'items' => [['subjectType' => 'member', 'subjectId' => 'NGG-CARD-1', 'why' => 'Damaged']]]);
    chk('id studio: asking again updates the open request rather than doubling it', $r['added'] === 0 && $r['updated'] === 1
        && (int)db_row("SELECT COUNT(*) c FROM id_reprints WHERE subjectId = 'NGG-CARD-1' AND doneAt = ''")['c'] === 1);
