        fn($op) => (backend_dispatch($op, ['requesterId' => ''])['error'] ?? '') === 'unknown_op')) === 0);
    db_exec("DELETE FROM id_reprints"); db_exec("DELETE FROM id_photo_asks"); db_exec("DELETE FROM members WHERE memberId = 'NGG-IDS-ED'");
